def evaluate_material_contract(
    material_contract: dict[str, Any],
    submission_profile: str,
) -> list[RuleResult]:
    rule_engine = RuleEngine(build_default_material_rules())
    return rule_engine.run(material_contract, submission_profile=submission_profile)


def evaluate_parsed_documents(
    parsed_documents: list[dict[str, Any]],
    submission_profile: str,
) -> tuple[dict[str, Any], list[RuleResult]]:
    material_contract = build_material_review_contract(parsed_documents)
    rule_results = evaluate_material_contract(material_contract, submission_profile)
    return material_contract, rule_results


def build_compliance_result_payload(
    submission_profile: str,
    parsed_documents: list[dict[str, Any]],
    consistency_rows: list[dict[str, Any]] | None,
    final_status: str,
) -> dict[str, Any]:
    material_contract, rule_results = evaluate_parsed_documents(parsed_documents, submission_profile)
    consistency_rows = consistency_rows or build_fact_consistency_rows(material_contract)
    asset_coverage_rows = build_non_text_asset_coverage_rows(material_contract)
    section_anchor_rows = build_section_anchor_rows(material_contract)
    toc_body_alignment_rows = build_toc_body_alignment_rows(material_contract)
    fact_provenance_rows = build_atomic_fact_provenance_rows(material_contract)
    fact_signal_alignment_rows = build_atomic_fact_signal_alignment_rows(material_contract)
    fact_signal_consistency_rows = build_intra_document_fact_signal_consistency_rows(material_contract)
    fact_support_quality_rows = build_atomic_fact_support_quality_rows(material_contract)
    hard_failures = sum(
        1
        for item in rule_results
        if item.category == "hard" and item.status == "fail"
    )
    soft_rule_risks = sum(
        1
        for item in rule_results
        if item.category == "soft" and item.status in {"fail", "warn"}
    )

    table_count = sum(len(document.get("table_asts", [])) for document in parsed_documents)
    image_count = sum(len(document.get("image_blocks", [])) for document in parsed_documents)
    toc_count = sum(len(document.get("toc_blocks", [])) for document in parsed_documents)
    toc_sequence_count = sum(len(document.get("toc_sequences", [])) for document in parsed_documents)

    rule_payloads = [_rule_result_to_payload(item) for item in rule_results]
    risks = _build_risk_payloads(rule_results)

    return {
        "submission_profile": submission_profile,
        "run_status": final_status,
        "submission_scope": dict(material_contract.get("submission_scope", {}) or {}),
        "summary": {
            "hard_failures": hard_failures,
            "soft_risks": soft_rule_risks,
            "parsed_documents": len(parsed_documents),
            "tables": table_count,
            "images": image_count,
            "tocs": toc_count,
            "toc_sequences": toc_sequence_count,
            "rule_count": len(rule_payloads),
            "pass_rules": sum(1 for item in rule_results if item.status == "pass"),
            "warn_rules": sum(1 for item in rule_results if item.status == "warn"),
            "na_rules": sum(1 for item in rule_results if item.status == "na"),
        },
        "rules": rule_payloads,
        "risks": risks,
        "artifacts": {
            "material_contract_version": material_contract.get("schema_version"),
            "material_contract_summary": material_contract.get("index_summary", {}),
            "fact_consistency_row_count": len(consistency_rows),
            "fact_inconsistency_count": sum(1 for row in consistency_rows if not row.get("is_consistent")),
            "non_text_asset_coverage_row_count": len(asset_coverage_rows),
            "non_text_asset_gap_count": sum(1 for row in asset_coverage_rows if not row.get("coverage_ready")),
            "section_anchor_row_count": len(section_anchor_rows),
            "section_anchor_gap_count": sum(1 for row in section_anchor_rows if not row.get("anchor_ready")),
            "toc_body_alignment_row_count": len(toc_body_alignment_rows),
            "toc_body_alignment_gap_count": sum(
                1
                for row in toc_body_alignment_rows
                if int(row.get("toc_outline_count", 0) or 0) > 0 and not row.get("alignment_ready")
            ),
            "toc_root_page_order_gap_count": sum(
                1
                for row in toc_body_alignment_rows
                if int(row.get("comparable_root_page_count", 0) or 0) >= 2 and not row.get("root_page_order_ready")
            ),
            "toc_root_page_offset_gap_count": sum(
                1
                for row in toc_body_alignment_rows
                if int(row.get("comparable_root_page_count", 0) or 0) >= 2 and not row.get("root_page_offset_ready")
            ),
            "toc_root_page_span_gap_count": sum(
                1
                for row in toc_body_alignment_rows
                if False
            ),
            "toc_direct_child_coverage_gap_count": sum(
                1
                for row in toc_body_alignment_rows
                if int(row.get("toc_direct_child_count", 0) or 0) > 0 and not row.get("direct_child_coverage_ready")
            ),
            "toc_bounded_subtree_coverage_gap_count": sum(
                1
                for row in toc_body_alignment_rows
                if int(row.get("toc_bounded_subtree_count", 0) or 0) > 0 and not row.get("bounded_subtree_coverage_ready")
            ),
            "fact_provenance_row_count": len(fact_provenance_rows),
            "fact_provenance_gap_count": sum(1 for row in fact_provenance_rows if not row.get("has_unit_provenance")),
            "fact_signal_alignment_row_count": len(fact_signal_alignment_rows),
            "fact_signal_alignment_gap_count": sum(1 for row in fact_signal_alignment_rows if not row.get("is_aligned")),
            "fact_signal_consistency_row_count": len(fact_signal_consistency_rows),
            "fact_signal_conflict_count": sum(1 for row in fact_signal_consistency_rows if not row.get("is_consistent")),
            "fact_support_quality_row_count": len(fact_support_quality_rows),
            "fact_context_only_support_count": sum(1 for row in fact_support_quality_rows if row.get("has_context_only_support")),
            "submission_scope": dict(material_contract.get("submission_scope", {}) or {}),
        },
    }


def build_fact_consistency_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_fact_consistency_rows(material_contract)


def build_fact_consistency_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    fact_index = list(material_contract.get("fact_index", []) or [])

    document_slots: list[dict[str, str]] = []
    facts_by_document: dict[str, dict[str, str]] = {}

    for document in documents:
        document_id = str(document.get("document_id") or "").strip()
        filename = str(document.get("filename") or document_id).strip()
        classification = dict(document.get("classification", {}) or {})
        module_label = str(classification.get("module_label") or document_id or "unknown-document").strip()
        document_slots.append(
            {
                "document_id": document_id,
                "filename": filename,
                "module": module_label,
            }
        )
        facts_by_document.setdefault(document_id, {})

    for fact_record in fact_index:
        document_id = str(fact_record.get("document_id") or "").strip()
        fact_key = str(fact_record.get("fact_key") or "").strip()
        if not document_id or not fact_key:
            continue
        facts_by_document.setdefault(document_id, {})[fact_key] = _normalize_fact_value(fact_record.get("fact_value"))

    all_fact_keys = sorted(
        {
            fact_key
            for document_facts in facts_by_document.values()
            for fact_key in document_facts.keys()
        }
    )

    rows: list[dict[str, Any]] = []
    for fact_key in all_fact_keys:
        module_values: list[dict[str, str]] = []
        present_values: set[str] = set()
        populated_document_count = 0

        for slot in document_slots:
            value = facts_by_document.get(slot["document_id"], {}).get(fact_key, "")
            module_values.append(
                {
                    "document_id": slot["document_id"],
                    "filename": slot["filename"],
                    "module": slot["module"],
                    "value": value,
                }
            )
            if value:
                populated_document_count += 1
                present_values.add(value)

        rows.append(
            {
                "fact": fact_key,
                "module_values": module_values,
                "is_consistent": len(present_values) <= 1,
                "present_value_count": populated_document_count,
                "distinct_value_count": len(present_values),
            }
        )

    return rows


def build_atomic_fact_provenance_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_atomic_fact_provenance_rows(material_contract)


def build_atomic_fact_provenance_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for fact_record in material_contract.get("fact_index", []) or []:
        provenance = dict(fact_record.get("provenance", {}) or {})
        supporting_units = list(provenance.get("supporting_units", []) or [])
        rows.append(
            {
                "document_id": str(fact_record.get("document_id") or "").strip(),
                "filename": str(fact_record.get("filename") or "").strip(),
                "fact_key": str(fact_record.get("fact_key") or "").strip(),
                "fact_value": fact_record.get("fact_value"),
                "has_unit_provenance": len(supporting_units) > 0,
                "supporting_unit_count": int(provenance.get("supporting_unit_count", len(supporting_units)) or 0),
                "supporting_units": supporting_units,
            }
        )
    return rows


def build_atomic_fact_signal_alignment_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_atomic_fact_signal_alignment_rows(material_contract)


def build_atomic_fact_signal_alignment_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    signal_index = list(material_contract.get("fact_signal_index", []) or [])
    fact_index = list(material_contract.get("fact_index", []) or [])

    extracted_by_document: dict[str, dict[str, str]] = {}
    for fact_record in fact_index:
        document_id = str(fact_record.get("document_id") or "").strip()
        fact_key = str(fact_record.get("fact_key") or "").strip()
        if not document_id or not fact_key:
            continue
        extracted_by_document.setdefault(document_id, {})[fact_key] = _normalize_fact_value(fact_record.get("fact_value"))

    grouped_signals: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for signal in signal_index:
        document_id = str(signal.get("document_id") or "").strip()
        fact_key = str(signal.get("fact_key") or "").strip()
        if not document_id or not fact_key:
            continue
        grouped_signals.setdefault((document_id, fact_key), []).append(signal)

    rows: list[dict[str, Any]] = []
    for (document_id, fact_key), signals in sorted(grouped_signals.items()):
        filename = str(signals[0].get("filename") or document_id).strip()
        signal_values = _sorted_distinct_values(signal.get("fact_value") for signal in signals)
        extracted_value = extracted_by_document.get(document_id, {}).get(fact_key, "")
        rows.append(
            {
                "document_id": document_id,
                "filename": filename,
                "fact_key": fact_key,
                "signal_value_candidates": signal_values,
                "signal_count": len(signals),
                "extracted_fact_value": extracted_value,
                "is_aligned": bool(extracted_value) and extracted_value in signal_values,
            }
        )

    return rows


def build_intra_document_fact_signal_consistency_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_intra_document_fact_signal_consistency_rows(material_contract)


def build_intra_document_fact_signal_consistency_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    signal_index = list(material_contract.get("fact_signal_index", []) or [])
    grouped_signals: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for signal in signal_index:
        document_id = str(signal.get("document_id") or "").strip()
        fact_key = str(signal.get("fact_key") or "").strip()
        if not document_id or not fact_key:
            continue
        grouped_signals.setdefault((document_id, fact_key), []).append(signal)

    rows: list[dict[str, Any]] = []
    for (document_id, fact_key), signals in sorted(grouped_signals.items()):
        filename = str(signals[0].get("filename") or document_id).strip()
        signal_values = _sorted_distinct_values(signal.get("fact_value") for signal in signals)
        rows.append(
            {
                "document_id": document_id,
                "filename": filename,
                "fact_key": fact_key,
                "signal_count": len(signals),
                "distinct_signal_value_count": len(signal_values),
                "signal_value_candidates": signal_values,
                "is_consistent": len(signal_values) <= 1,
            }
        )

    return rows


def build_atomic_fact_support_quality_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_atomic_fact_support_quality_rows(material_contract)


def build_atomic_fact_support_quality_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for fact_record in material_contract.get("fact_index", []) or []:
        provenance = dict(fact_record.get("provenance", {}) or {})
        supporting_units = list(provenance.get("supporting_units", []) or [])
        support_roles = _sorted_distinct_values(unit.get("unit_role") for unit in supporting_units)
        support_sources = _sorted_distinct_values(unit.get("source_type") for unit in supporting_units)
        has_content_bearing_support = any(
            _is_content_bearing_fact_support_role(
                str(unit.get("source_type") or "").strip(),
                str(unit.get("unit_role") or "").strip(),
            )
            for unit in supporting_units
        )
        rows.append(
            {
                "document_id": str(fact_record.get("document_id") or "").strip(),
                "filename": str(fact_record.get("filename") or "").strip(),
                "fact_key": str(fact_record.get("fact_key") or "").strip(),
                "fact_value": fact_record.get("fact_value"),
                "supporting_unit_count": len(supporting_units),
                "support_source_types": support_sources,
                "support_unit_roles": support_roles,
                "has_content_bearing_support": has_content_bearing_support,
                "has_context_only_support": bool(supporting_units) and not has_content_bearing_support,
            }
        )
    return rows


def build_non_text_asset_coverage_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_non_text_asset_coverage_rows(material_contract)


def build_non_text_asset_coverage_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    evidence_index = list(material_contract.get("evidence_index", []) or [])
    unit_index = list(material_contract.get("unit_index", []) or [])

    evidence_by_key: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
    for evidence in evidence_index:
        key = (
            str(evidence.get("document_id") or "").strip(),
            str(evidence.get("source_type") or "").strip(),
            str(evidence.get("source_id") or "").strip(),
        )
        evidence_by_key.setdefault(key, []).append(evidence)

    units_by_key: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
    for unit in unit_index:
        key = (
            str(unit.get("document_id") or "").strip(),
            str(unit.get("source_type") or "").strip(),
            str(unit.get("source_id") or "").strip(),
        )
        units_by_key.setdefault(key, []).append(unit)

    rows: list[dict[str, Any]] = []
    for document in documents:
        document_id = str(document.get("document_id") or "").strip()
        filename = str(document.get("filename") or document_id).strip()
        structure_refs = dict(document.get("structure_refs", {}) or {})

        for source_type, refs_key in (("table", "table_refs"), ("image", "image_refs")):
            for source_id in structure_refs.get(refs_key, []) or []:
                normalized_source_id = str(source_id or "").strip()
                key = (document_id, source_type, normalized_source_id)
                evidence_records = list(evidence_by_key.get(key, []))
                unit_records = list(units_by_key.get(key, []))
                nonempty_unit_count = sum(1 for unit in unit_records if str(unit.get("text") or "").strip())
                fact_eligible_unit_count = sum(
                    1 for unit in unit_records if bool(unit.get("fact_extraction_eligible", False))
                )
                segment_count = sum(int(record.get("segment_count", 0) or 0) for record in evidence_records)
                coverage_ready = (
                    len(evidence_records) > 0
                    and nonempty_unit_count > 0
                    and (source_type != "table" or fact_eligible_unit_count > 0)
                )
                rows.append(
                    {
                        "document_id": document_id,
                        "filename": filename,
                        "source_type": source_type,
                        "source_id": normalized_source_id,
                        "evidence_count": len(evidence_records),
                        "unit_count": len(unit_records),
                        "nonempty_unit_count": nonempty_unit_count,
                        "fact_eligible_unit_count": fact_eligible_unit_count,
                        "segment_count": segment_count,
                        "coverage_ready": coverage_ready,
                    }
                )

    return rows


def build_section_anchor_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_section_anchor_rows(material_contract)


def build_section_anchor_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    section_index = list(material_contract.get("section_index", []) or [])

    section_rows_by_document: dict[str, list[dict[str, Any]]] = {}
    for row in section_index:
        document_id = str(row.get("document_id") or "").strip()
        section_rows_by_document.setdefault(document_id, []).append(row)

    rows: list[dict[str, Any]] = []
    for document in documents:
        document_id = str(document.get("document_id") or "").strip()
        filename = str(document.get("filename") or document_id).strip()
        classification = dict(document.get("classification", {}) or {})
        summary = dict(document.get("summary", {}) or {})
        anchored_rows = section_rows_by_document.get(document_id, [])
        module_label = str(classification.get("module_label") or "").strip()
        outline_index_count = int(summary.get("outline_index_count", 0) or 0)
        anchored_evidence_count = int(summary.get("section_anchored_evidence_count", 0) or 0)
        anchored_unit_count = int(summary.get("section_anchored_unit_count", 0) or 0)
        content_evidence_count = int(summary.get("content_evidence_count", 0) or 0)
        content_unit_count = int(summary.get("content_unit_count", 0) or 0)
        anchor_ready = bool(module_label) and (outline_index_count > 0 or len(anchored_rows) > 0)
        rows.append(
            {
                "document_id": document_id,
                "filename": filename,
                "module_label": module_label,
                "section_anchor_count": len(anchored_rows),
                "outline_index_count": outline_index_count,
                "section_anchored_evidence_count": anchored_evidence_count,
                "section_anchored_unit_count": anchored_unit_count,
                "content_evidence_count": content_evidence_count,
                "content_unit_count": content_unit_count,
                "anchor_ready": anchor_ready,
            }
        )
    return rows


def build_toc_body_alignment_rows_from_documents(
    parsed_documents: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    material_contract = build_material_review_contract(parsed_documents)
    return build_toc_body_alignment_rows(material_contract)


def build_toc_body_alignment_rows(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    navigation_index = list(material_contract.get("navigation_index", []) or [])
    paragraph_index = list(material_contract.get("paragraph_index", []) or [])
    section_tree = list(material_contract.get("section_tree", []) or [])

    toc_sequence_contexts: list[dict[str, Any]] = []
    all_toc_entry_details_by_document: dict[str, dict[str, dict[str, Any]]] = {}
    all_toc_outline_labels_by_document: dict[str, dict[str, str]] = {}
    all_toc_root_outline_keys_by_document: dict[str, set[str]] = {}
    all_toc_root_outline_labels_by_document: dict[str, dict[str, str]] = {}
    for sequence in navigation_index:
        document_id = str(sequence.get("document_id") or "").strip()
        if not document_id:
            continue
        sequence_id = str(sequence.get("toc_sequence_id") or "").strip()
        toc_outline_keys: set[str] = set()
        toc_outline_labels: dict[str, str] = {}
        toc_root_outline_keys: set[str] = set()
        toc_root_outline_labels: dict[str, str] = {}
        toc_direct_child_keys_by_root: dict[str, set[str]] = {}
        toc_bounded_subtree_keys_by_root: dict[str, set[str]] = {}
        toc_entry_details_lookup: dict[str, dict[str, Any]] = {}
        toc_path_entry_details: list[dict[str, Any]] = []
        entry_by_index = {
            int(entry.get("sequence_entry_index", 0) or 0): entry
            for entry in sequence.get("entries", []) or []
            if int(entry.get("sequence_entry_index", 0) or 0) > 0
        }
        entry_path_cache: dict[int, dict[str, Any]] = {}

        def _resolve_entry_path_details(entry: dict[str, Any]) -> dict[str, Any]:
            entry_index = int(entry.get("sequence_entry_index", 0) or 0)
            if entry_index > 0 and entry_index in entry_path_cache:
                return entry_path_cache[entry_index]

            outline_index = str(entry.get("outline_index") or "").strip()
            text = str(entry.get("text") or "").strip()
            normalized_outline_index = _normalize_outline_comparison_key(outline_index)
            explicit_parent_outline_index = str(entry.get("outline_parent_index") or "").strip() or None
            explicit_parent_normalized_outline_index = _normalize_outline_comparison_key(explicit_parent_outline_index)
            expected_parent_outline_index = explicit_parent_outline_index
            parent_entry_index = int(entry.get("parent_sequence_entry_index", 0) or 0)
            parent_entry = entry_by_index.get(parent_entry_index)
            parent_entry_outline_index = str(parent_entry.get("outline_index") or "").strip() if parent_entry else ""
            parent_entry_normalized_outline_index = _normalize_outline_comparison_key(parent_entry_outline_index)

            def _root_outline_key(candidate_outline_index: str | None) -> str | None:
                normalized_candidate = _normalize_outline_comparison_key(candidate_outline_index)
                if not normalized_candidate:
                    return None
                return normalized_candidate.split(".", 1)[0]

            use_parent_entry = bool(parent_entry) and (
                not explicit_parent_normalized_outline_index
                or parent_entry_normalized_outline_index == explicit_parent_normalized_outline_index
            )
            if use_parent_entry and parent_entry:
                parent_details = _resolve_entry_path_details(parent_entry)
                outline_path_segments = [
                    *list(parent_details.get("outline_path_segments", []) or []),
                    *( [outline_index] if outline_index else [] ),
                ]
                text_path_segments = [
                    *list(parent_details.get("text_path_segments", []) or []),
                    *( [text] if text else [] ),
                ]
                parent_outline_index = str(parent_entry.get("outline_index") or "").strip() or None
                parent_normalized_outline_index = _normalize_outline_comparison_key(parent_outline_index)
                root_outline_index = parent_details.get("root_outline_index")
                root_normalized_outline_index = parent_details.get("root_normalized_outline_index")
            else:
                outline_path_segments = [
                    *( [explicit_parent_outline_index] if explicit_parent_outline_index else [] ),
                    *( [outline_index] if outline_index else [] ),
                ]
                text_path_segments = [text] if text else []
                parent_outline_index = explicit_parent_outline_index
                parent_normalized_outline_index = explicit_parent_normalized_outline_index or None
                root_outline_index = explicit_parent_outline_index or outline_index or None
                root_normalized_outline_index = (
                    _root_outline_key(explicit_parent_outline_index)
                    or _root_outline_key(outline_index)
                    or normalized_outline_index
                    or None
                )

            details = {
                "root_outline_index": root_outline_index,
                "root_normalized_outline_index": root_normalized_outline_index,
                "parent_outline_index": parent_outline_index,
                "parent_normalized_outline_index": parent_normalized_outline_index,
                "expected_parent_outline_index": expected_parent_outline_index,
                "outline_index": outline_index or None,
                "normalized_outline_index": normalized_outline_index or None,
                "outline_path_segments": outline_path_segments,
                "text_path_segments": text_path_segments,
                "outline_path": " > ".join(outline_path_segments) if outline_path_segments else None,
                "text_path": " > ".join(text_path_segments) if text_path_segments else None,
                "text": text or None,
                "page_locator_value": _coerce_int(entry.get("page_locator_value"))
                or _coerce_int(entry.get("page_locator")),
                "navigation_page": _coerce_int(entry.get("page")),
                "level": _coerce_int(entry.get("level")),
                "sequence_entry_index": entry_index or None,
            }
            if entry_index > 0:
                entry_path_cache[entry_index] = details
            return details

        for entry in sequence.get("entries", []) or []:
            _resolve_entry_path_details(entry)

        duplicate_outline_counts: dict[str, int] = {}
        for details in entry_path_cache.values():
            key = str(details.get("normalized_outline_index") or "").strip()
            if key:
                duplicate_outline_counts[key] = duplicate_outline_counts.get(key, 0) + 1

        for entry in sequence.get("entries", []) or []:
            outline_index = str(entry.get("outline_index") or "").strip()
            entry_details = _with_toc_path_qualified_comparison_keys(
                _resolve_entry_path_details(entry),
                duplicate_outline_counts,
            )
            normalized_key = str(entry_details.get("normalized_outline_index") or "").strip()
            if entry_details.get("text") and _coerce_int(entry_details.get("page_locator_value")) is not None:
                toc_path_entry_details.append(entry_details)
            if not normalized_key:
                continue
            toc_entry_details_lookup.setdefault(normalized_key, entry_details)
            all_toc_entry_details_by_document.setdefault(document_id, {}).setdefault(normalized_key, entry_details)
            toc_outline_keys.add(normalized_key)
            toc_outline_labels.setdefault(normalized_key, outline_index)
            implied_root_outline_key = str(entry_details.get("root_normalized_outline_index") or "").strip()
            implied_root_outline_label = str(entry_details.get("root_outline_index") or implied_root_outline_key).strip()
            if implied_root_outline_key:
                toc_root_outline_keys.add(implied_root_outline_key)
                if implied_root_outline_label:
                    toc_root_outline_labels.setdefault(implied_root_outline_key, implied_root_outline_label)
            explicit_parent_outline_index = str(entry_details.get("parent_normalized_outline_index") or "").strip()
            is_root_entry = (
                entry.get("parent_sequence_entry_index") is None
                and not str(entry.get("parent_toc_id") or "").strip()
                and not explicit_parent_outline_index
            ) or int(entry.get("level", 0) or 0) <= 1
            if is_root_entry:
                toc_root_outline_keys.add(normalized_key)
                toc_root_outline_labels.setdefault(normalized_key, outline_index)
                continue
            parent_entry_index = int(entry.get("parent_sequence_entry_index", 0) or 0)
            parent_entry = entry_by_index.get(parent_entry_index)
            parent_outline_key = explicit_parent_outline_index or None
            parent_is_root_entry = bool(parent_outline_key and implied_root_outline_key and parent_outline_key == implied_root_outline_key)
            if parent_entry and not parent_outline_key:
                parent_outline_key = _normalize_outline_comparison_key(parent_entry.get("outline_index"))
                parent_is_root_entry = (
                    parent_entry.get("parent_sequence_entry_index") is None
                    and not str(parent_entry.get("parent_toc_id") or "").strip()
                ) or int(parent_entry.get("level", 0) or 0) <= 1
            if not parent_outline_key:
                continue
            if parent_is_root_entry:
                toc_direct_child_keys_by_root.setdefault(parent_outline_key, set()).add(normalized_key)
                toc_bounded_subtree_keys_by_root.setdefault(parent_outline_key, set()).add(normalized_key)
                continue

            if implied_root_outline_key:
                toc_bounded_subtree_keys_by_root.setdefault(implied_root_outline_key, set()).add(normalized_key)
            ancestor_entry = parent_entry
            ancestor_depth = 1
            while ancestor_depth < 3:
                ancestor_parent_index = int(ancestor_entry.get("parent_sequence_entry_index", 0) or 0)
                ancestor_parent = entry_by_index.get(ancestor_parent_index)
                if not ancestor_parent:
                    break
                ancestor_parent_outline_key = _normalize_outline_comparison_key(ancestor_parent.get("outline_index"))
                if not ancestor_parent_outline_key:
                    break
                ancestor_parent_is_root = (
                    ancestor_parent.get("parent_sequence_entry_index") is None
                    and not str(ancestor_parent.get("parent_toc_id") or "").strip()
                ) or int(ancestor_parent.get("level", 0) or 0) <= 1
                if ancestor_parent_is_root:
                    toc_bounded_subtree_keys_by_root.setdefault(ancestor_parent_outline_key, set()).add(normalized_key)
                    break
                ancestor_entry = ancestor_parent
                ancestor_depth += 1

        toc_sequence_contexts.append(
            {
                "document_id": document_id,
                "toc_sequence_id": sequence_id or None,
                "title": sequence.get("title"),
                "pages": list(sequence.get("pages", []) or []),
                "page_span": list(sequence.get("page_span", []) or []),
                "toc_outline_keys": toc_outline_keys,
                "toc_outline_labels": toc_outline_labels,
                "toc_root_outline_keys": toc_root_outline_keys,
                "toc_root_outline_labels": toc_root_outline_labels,
                "toc_direct_child_keys_by_root": toc_direct_child_keys_by_root,
                "toc_bounded_subtree_keys_by_root": toc_bounded_subtree_keys_by_root,
                "toc_entry_details": toc_entry_details_lookup,
                "toc_path_entry_details": toc_path_entry_details,
            }
        )
        for key, label in toc_outline_labels.items():
            all_toc_outline_labels_by_document.setdefault(document_id, {}).setdefault(key, label)
        all_toc_root_outline_keys_by_document.setdefault(document_id, set()).update(toc_root_outline_keys)
        for key, label in toc_root_outline_labels.items():
            all_toc_root_outline_labels_by_document.setdefault(document_id, {}).setdefault(key, label)

    body_outline_keys_by_document: dict[str, set[str]] = {}
    body_outline_labels_by_document: dict[str, dict[str, str]] = {}
    body_outline_page_values_by_document: dict[str, dict[str, list[int]]] = {}
    body_outline_heading_page_values_by_document: dict[str, dict[str, list[int]]] = {}
    body_outline_heading_title_pages_by_document: dict[str, dict[str, list[dict[str, Any]]]] = {}
    body_text_page_values_by_document: dict[str, dict[str, list[int]]] = {}
    toc_confirmed_body_heading_pages_by_document: dict[str, dict[str, list[int]]] = {}
    toc_confirmed_body_heading_labels_by_document: dict[str, dict[str, str]] = {}
    for row in paragraph_index:
        document_id = str(row.get("document_id") or "").strip()
        outline_index = str(row.get("outline_index") or "").strip()
        normalized_key = _normalize_outline_comparison_key(outline_index)
        if not document_id:
            continue
        page_span = list(row.get("page_span", [None, None]))
        page_start = _coerce_int(page_span[0] if len(page_span) > 0 else None)
        if normalized_key:
            body_outline_keys_by_document.setdefault(document_id, set()).add(normalized_key)
            body_outline_labels_by_document.setdefault(document_id, {}).setdefault(normalized_key, outline_index)
            if page_start is not None and page_start > 0:
                body_outline_page_values_by_document.setdefault(document_id, {}).setdefault(normalized_key, []).append(page_start)
                paragraph_kind = str(row.get("paragraph_kind") or "").strip().lower()
                if paragraph_kind in {"heading", "section_heading"}:
                    body_outline_heading_page_values_by_document.setdefault(document_id, {}).setdefault(
                        normalized_key, []
                    ).append(page_start)
                    body_outline_heading_title_pages_by_document.setdefault(document_id, {}).setdefault(
                        normalized_key, []
                    ).append(
                        {
                            "page": page_start,
                            "title": _resolve_body_heading_title(row),
                        }
                    )
        text_key = _normalize_heading_title_for_comparison(row.get("text"))
        if text_key and page_start is not None and page_start > 0:
            body_text_page_values_by_document.setdefault(document_id, {}).setdefault(text_key, []).append(page_start)
        toc_confirmed_heading = _resolve_toc_confirmed_body_heading(
            row,
            all_toc_entry_details_by_document.get(document_id, {}),
        )
        if not toc_confirmed_heading:
            continue
        confirmed_key = str(toc_confirmed_heading.get("normalized_outline_index") or "").strip()
        confirmed_label = str(toc_confirmed_heading.get("outline_index") or confirmed_key).strip()
        confirmed_page = _coerce_int(toc_confirmed_heading.get("page"))
        if not confirmed_key or confirmed_page is None or confirmed_page <= 0:
            continue
        body_outline_keys_by_document.setdefault(document_id, set()).add(confirmed_key)
        body_outline_labels_by_document.setdefault(document_id, {}).setdefault(confirmed_key, confirmed_label)
        body_outline_page_values_by_document.setdefault(document_id, {}).setdefault(confirmed_key, []).append(confirmed_page)
        body_outline_heading_page_values_by_document.setdefault(document_id, {}).setdefault(
            confirmed_key, []
        ).append(confirmed_page)
        body_outline_heading_title_pages_by_document.setdefault(document_id, {}).setdefault(
            confirmed_key, []
        ).append(
            {
                "page": confirmed_page,
                "title": str(toc_confirmed_heading.get("title") or "").strip(),
            }
        )
        toc_confirmed_body_heading_pages_by_document.setdefault(document_id, {}).setdefault(
            confirmed_key, []
        ).append(confirmed_page)
        toc_confirmed_body_heading_labels_by_document.setdefault(document_id, {}).setdefault(
            confirmed_key,
            confirmed_label,
        )

    body_root_outline_keys_by_document: dict[str, set[str]] = {}
    body_root_outline_labels_by_document: dict[str, dict[str, str]] = {}
    body_root_page_spans_by_document: dict[str, dict[str, list[Any]]] = {}
    body_direct_child_keys_by_document_root: dict[str, dict[str, set[str]]] = {}
    body_bounded_subtree_keys_by_document_root: dict[str, dict[str, set[str]]] = {}
    body_direct_child_page_values_by_document_root: dict[str, dict[str, list[int]]] = {}
    for node in section_tree:
        document_id = str(node.get("document_id") or "").strip()
        outline_index = str(node.get("outline_index") or "").strip()
        normalized_key = _normalize_outline_comparison_key(outline_index)
        if not document_id or not normalized_key:
            continue
        body_root_outline_keys_by_document.setdefault(document_id, set()).add(normalized_key)
        body_root_outline_labels_by_document.setdefault(document_id, {}).setdefault(normalized_key, outline_index)
        body_root_page_spans_by_document.setdefault(document_id, {})[normalized_key] = list(node.get("page_span", [None, None]))
        for child in node.get("children", []) or []:
            child_outline_key = _normalize_outline_comparison_key(child.get("outline_index"))
            if not child_outline_key:
                continue
            child_page_span = list(child.get("page_span", [None, None]))
            child_page_start = _coerce_int(child_page_span[0] if len(child_page_span) > 0 else None)
            if child_page_start is not None and child_page_start > 0:
                body_direct_child_page_values_by_document_root.setdefault(document_id, {}).setdefault(
                    normalized_key, []
                ).append(child_page_start)
            body_direct_child_keys_by_document_root.setdefault(document_id, {}).setdefault(normalized_key, set()).add(
                child_outline_key
            )
            body_bounded_subtree_keys_by_document_root.setdefault(document_id, {}).setdefault(normalized_key, set()).add(
                child_outline_key
            )
            for grandchild in child.get("children", []) or []:
                grandchild_outline_key = _normalize_outline_comparison_key(grandchild.get("outline_index"))
                if not grandchild_outline_key:
                    continue
                body_bounded_subtree_keys_by_document_root.setdefault(document_id, {}).setdefault(
                    normalized_key, set()
                ).add(grandchild_outline_key)
                for great_grandchild in grandchild.get("children", []) or []:
                    great_grandchild_outline_key = _normalize_outline_comparison_key(great_grandchild.get("outline_index"))
                    if not great_grandchild_outline_key:
                        continue
                    body_bounded_subtree_keys_by_document_root.setdefault(document_id, {}).setdefault(
                        normalized_key, set()
                    ).add(great_grandchild_outline_key)

    for document_id, confirmed_pages_by_key in toc_confirmed_body_heading_pages_by_document.items():
        toc_entry_details_lookup = all_toc_entry_details_by_document.get(document_id, {})
        for confirmed_key, confirmed_pages in confirmed_pages_by_key.items():
            details = dict(toc_entry_details_lookup.get(confirmed_key, {}) or {})
            root_key = str(details.get("root_normalized_outline_index") or "").strip()
            parent_key = str(details.get("parent_normalized_outline_index") or "").strip()
            label = (
                toc_confirmed_body_heading_labels_by_document.get(document_id, {}).get(confirmed_key)
                or all_toc_outline_labels_by_document.get(document_id, {}).get(confirmed_key)
                or confirmed_key
            )
            if confirmed_key in all_toc_root_outline_keys_by_document.get(document_id, set()):
                body_root_outline_keys_by_document.setdefault(document_id, set()).add(confirmed_key)
                body_root_outline_labels_by_document.setdefault(document_id, {}).setdefault(confirmed_key, label)
                toc_page = _coerce_int(details.get("page_locator_value"))
                existing_span = list(body_root_page_spans_by_document.get(document_id, {}).get(confirmed_key, [None, None]))
                existing_start = _coerce_int(existing_span[0] if len(existing_span) > 0 else None)
                existing_end = _coerce_int(existing_span[1] if len(existing_span) > 1 else None)
                confirmed_start = _select_best_body_anchor_page(toc_page, confirmed_pages, existing_start)
                if confirmed_start is not None and confirmed_start > 0:
                    body_root_page_spans_by_document.setdefault(document_id, {})[confirmed_key] = [
                        confirmed_start,
                        existing_end if existing_end is not None and existing_end >= confirmed_start else confirmed_start,
                    ]
            if root_key and confirmed_key != root_key:
                body_bounded_subtree_keys_by_document_root.setdefault(document_id, {}).setdefault(root_key, set()).add(
                    confirmed_key
                )
                if parent_key == root_key:
                    body_direct_child_keys_by_document_root.setdefault(document_id, {}).setdefault(root_key, set()).add(
                        confirmed_key
                    )
                    body_direct_child_page_values_by_document_root.setdefault(document_id, {}).setdefault(
                        root_key, []
                    ).extend(_dedupe_positive_page_values(confirmed_pages))

    rows: list[dict[str, Any]] = []
    for document in documents:
        document_id = str(document.get("document_id") or "").strip()
        filename = str(document.get("filename") or document_id).strip()
        body_outline_keys = sorted(body_outline_keys_by_document.get(document_id, set()))
        body_root_outline_keys = sorted(body_root_outline_keys_by_document.get(document_id, set()))
        selected_toc_context, _excluded_toc_contexts = _select_document_toc_sequence_context(
            document_id,
            toc_sequence_contexts,
            set(body_outline_keys),
            set(body_root_outline_keys),
            body_outline_page_values_by_document.get(document_id, {}),
            body_outline_heading_page_values_by_document.get(document_id, {}),
            body_outline_heading_title_pages_by_document.get(document_id, {}),
            body_root_page_spans_by_document.get(document_id, {}),
        )
        toc_outline_labels_by_document = {
            document_id: dict(selected_toc_context.get("toc_outline_labels", {}) or {})
        }
        toc_root_outline_labels_by_document = {
            document_id: dict(selected_toc_context.get("toc_root_outline_labels", {}) or {})
        }
        toc_entry_details_by_document = {
            document_id: dict(selected_toc_context.get("toc_entry_details", {}) or {})
        }
        toc_direct_child_keys_by_document_root = {
            document_id: dict(selected_toc_context.get("toc_direct_child_keys_by_root", {}) or {})
        }
        toc_bounded_subtree_keys_by_document_root = {
            document_id: dict(selected_toc_context.get("toc_bounded_subtree_keys_by_root", {}) or {})
        }
        toc_path_entry_details_by_document = {
            document_id: list(selected_toc_context.get("toc_path_entry_details", []) or [])
        }
        toc_outline_keys = sorted(set(selected_toc_context.get("toc_outline_keys", set()) or set()))
        raw_toc_root_outline_keys = sorted(set(selected_toc_context.get("toc_root_outline_keys", set()) or set()))
        effective_toc_root_outline_keys: set[str] = set()
        effective_toc_root_outline_labels: dict[str, str] = {}
        for root_key in raw_toc_root_outline_keys:
            resolved_root_key = root_key
            resolved_root_label = (
                toc_root_outline_labels_by_document.get(document_id, {}).get(root_key)
                or toc_outline_labels_by_document.get(document_id, {}).get(root_key)
                or root_key
            )
            for ancestor_key in _candidate_parent_outline_keys(root_key):
                if ancestor_key in body_root_outline_keys or ancestor_key in toc_outline_keys:
                    resolved_root_key = ancestor_key
                    resolved_root_label = (
                        toc_root_outline_labels_by_document.get(document_id, {}).get(ancestor_key)
                        or toc_outline_labels_by_document.get(document_id, {}).get(ancestor_key)
                        or (f"{ancestor_key}.0" if "." not in ancestor_key else ancestor_key)
                    )
                    break
            effective_toc_root_outline_keys.add(resolved_root_key)
            effective_toc_root_outline_labels.setdefault(resolved_root_key, resolved_root_label)
        toc_root_outline_keys = sorted(effective_toc_root_outline_keys)
        matched_outline_keys = sorted(set(toc_outline_keys) & set(body_outline_keys))
        missing_body_outline_keys = sorted(set(toc_outline_keys) - set(body_outline_keys))
        extra_body_outline_keys = sorted(set(body_outline_keys) - set(toc_outline_keys))
        matched_root_outline_keys = sorted(set(toc_root_outline_keys) & set(body_root_outline_keys))
        missing_body_root_outline_keys = sorted(set(toc_root_outline_keys) - set(body_root_outline_keys))
        extra_body_root_outline_keys = sorted(set(body_root_outline_keys) - set(toc_root_outline_keys))
        comparable_root_pages: list[dict[str, Any]] = []
        for root_key in matched_root_outline_keys:
            toc_entry_page_value = _coerce_int(
                toc_root_outline_labels_by_document.get(document_id, {}).get(root_key) and None
            )
            toc_navigation_page: int | None = None
            for sequence in navigation_index:
                if str(sequence.get("document_id") or "").strip() != document_id:
                    continue
                for entry in sequence.get("entries", []) or []:
                    if _normalize_outline_comparison_key(entry.get("outline_index")) != root_key:
                        continue
                    is_root_entry = (
                        entry.get("parent_sequence_entry_index") is None
                        and not str(entry.get("parent_toc_id") or "").strip()
                    ) or int(entry.get("level", 0) or 0) <= 1
                    if not is_root_entry:
                        continue
                    toc_entry_page_value = _coerce_int(entry.get("page_locator_value"))
                    if toc_entry_page_value is None:
                        toc_entry_page_value = _coerce_int(entry.get("page_locator"))
                    toc_navigation_page = _coerce_int(entry.get("page"))
                    break
                if toc_entry_page_value is not None:
                    break
            body_page_span = list(body_root_page_spans_by_document.get(document_id, {}).get(root_key, [None, None]))
            body_page_start = _coerce_int(body_page_span[0] if len(body_page_span) > 0 else None)
            body_page_end = _coerce_int(body_page_span[1] if len(body_page_span) > 1 else None)
            descendant_page_candidates: list[int] = []
            for outline_key, page_values in body_outline_page_values_by_document.get(document_id, {}).items():
                if outline_key == root_key or not str(outline_key).startswith(f"{root_key}."):
                    continue
                descendant_page_candidates.extend(list(page_values or []))
            root_heading_page_values = list(
                body_outline_heading_page_values_by_document.get(document_id, {}).get(root_key, []) or []
            )
            root_heading_title_page_values = list(
                body_outline_heading_title_pages_by_document.get(document_id, {}).get(root_key, []) or []
            )
            root_outline_page_values = list(body_outline_page_values_by_document.get(document_id, {}).get(root_key, []) or [])
            direct_child_page_values = list(
                body_direct_child_page_values_by_document_root.get(document_id, {}).get(root_key, []) or []
            )
            toc_root_details = dict(toc_entry_details_by_document.get(document_id, {}).get(root_key, {}) or {})
            toc_root_title = _resolve_toc_entry_title(toc_root_details)
            compatible_root_heading_page_values = _resolve_compatible_heading_page_values(
                root_heading_title_page_values,
                toc_root_title,
            )
            root_non_heading_page_values = [
                page
                for page in root_outline_page_values
                if page not in set(_dedupe_positive_page_values(root_heading_page_values))
            ]
            body_page_start = _select_best_body_anchor_page(
                toc_entry_page_value,
                (
                    compatible_root_heading_page_values
                    if compatible_root_heading_page_values
                    else direct_child_page_values
                    + descendant_page_candidates
                    + root_non_heading_page_values
                    + ([] if direct_child_page_values or descendant_page_candidates or root_non_heading_page_values else root_heading_page_values)
                ),
                body_page_start,
            )
            if toc_entry_page_value is None or body_page_start is None or body_page_end is None:
                continue
            comparable_root_pages.append(
                {
                    "outline_key": root_key,
                    "toc_navigation_page": toc_navigation_page,
                    "toc_page_locator_value": toc_entry_page_value,
                    "body_anchor_page_start": body_page_start,
                    "body_page_span": [body_page_start, body_page_end],
                }
            )
        comparable_root_pages = sorted(
            comparable_root_pages,
            key=lambda item: (
                int(item["toc_page_locator_value"]),
                str(item["outline_key"]),
            ),
        )
        toc_root_page_order = [
            item["outline_key"]
            for item in sorted(
                comparable_root_pages,
                key=lambda item: (
                    int(item["toc_page_locator_value"]),
                    str(item["outline_key"]),
                ),
            )
        ]
        body_root_page_order = [
            item["outline_key"]
            for item in sorted(
                comparable_root_pages,
                key=lambda item: (
                    int(item["body_anchor_page_start"]),
                    str(item["outline_key"]),
                ),
            )
        ]
        root_page_offset_values = [
            int(item["body_anchor_page_start"]) - int(item["toc_page_locator_value"])
            for item in comparable_root_pages
        ]
        root_page_order_required = len(comparable_root_pages) >= 2
        root_page_order_ready = (not root_page_order_required) or toc_root_page_order == body_root_page_order
        root_page_offset_required = len(comparable_root_pages) >= 2
        root_page_offset_ready = (not root_page_offset_required) or len(set(root_page_offset_values)) <= 1
        projected_root_page_values = (
            [
                int(item["toc_page_locator_value"]) + int(root_page_offset_values[0])
                for item in comparable_root_pages
            ]
            if comparable_root_pages and root_page_offset_ready
            else []
        )
        root_page_span_ready = True
        toc_order_index_lookup = {
            outline_key: index + 1
            for index, outline_key in enumerate(toc_root_page_order)
        }
        body_order_index_lookup = {
            outline_key: index + 1
            for index, outline_key in enumerate(body_root_page_order)
        }
        root_page_alignment_rows: list[dict[str, Any]] = []
        for index, item in enumerate(comparable_root_pages):
            outline_key = str(item["outline_key"])
            root_page_alignment_rows.append(
                {
                    "outline_index": toc_root_outline_labels_by_document.get(document_id, {}).get(outline_key, outline_key),
                    "normalized_outline_index": outline_key,
                    "toc_navigation_page": item.get("toc_navigation_page"),
                    "toc_page_locator_value": int(item["toc_page_locator_value"]),
                    "body_page_start": int(item["body_page_span"][0]),
                    "body_page_end": int(item["body_page_span"][1]),
                    "body_anchor_page_start": int(item["body_anchor_page_start"]),
                    "projected_page": projected_root_page_values[index] if index < len(projected_root_page_values) else None,
                    "offset": root_page_offset_values[index] if index < len(root_page_offset_values) else None,
                    "toc_order_index": toc_order_index_lookup.get(outline_key),
                    "body_order_index": body_order_index_lookup.get(outline_key),
                    "order_conflict": (
                        not root_page_order_ready
                        and toc_order_index_lookup.get(outline_key) != body_order_index_lookup.get(outline_key)
                    ),
                    "offset_conflict": not root_page_offset_ready,
                    "span_conflict": False,
                }
            )
        toc_direct_child_keys: set[str] = set()
        matched_direct_child_keys: set[str] = set()
        missing_body_direct_child_keys: set[str] = set()
        for root_key in matched_root_outline_keys:
            toc_children = set(toc_direct_child_keys_by_document_root.get(document_id, {}).get(root_key, set()))
            body_children = set(body_direct_child_keys_by_document_root.get(document_id, {}).get(root_key, set()))
            toc_direct_child_keys.update(toc_children)
            matched_direct_child_keys.update(toc_children & body_children)
            missing_body_direct_child_keys.update(toc_children - body_children)
        direct_child_coverage_ratio = (
            round(len(matched_direct_child_keys) / len(toc_direct_child_keys), 4)
            if len(toc_direct_child_keys) > 0
            else None
        )
        direct_child_coverage_ready = len(toc_direct_child_keys) == 0 or direct_child_coverage_ratio == 1.0
        missing_body_direct_child_path_rows = _build_missing_toc_outline_path_rows(
            document_id,
            missing_body_direct_child_keys,
            toc_entry_details_by_document,
            toc_outline_labels_by_document,
            toc_root_outline_labels_by_document,
            body_outline_labels_by_document,
            body_outline_page_values_by_document,
            body_outline_heading_page_values_by_document,
            body_root_page_spans_by_document,
        )
        toc_bounded_subtree_keys: set[str] = set()
        matched_bounded_subtree_keys: set[str] = set()
        missing_body_bounded_subtree_keys: set[str] = set()
        for root_key in matched_root_outline_keys:
            toc_subtree_keys = set(toc_bounded_subtree_keys_by_document_root.get(document_id, {}).get(root_key, set()))
            body_subtree_keys = set(body_bounded_subtree_keys_by_document_root.get(document_id, {}).get(root_key, set()))
            toc_bounded_subtree_keys.update(toc_subtree_keys)
            matched_bounded_subtree_keys.update(toc_subtree_keys & body_subtree_keys)
            missing_body_bounded_subtree_keys.update(toc_subtree_keys - body_subtree_keys)
        bounded_subtree_coverage_ratio = (
            round(len(matched_bounded_subtree_keys) / len(toc_bounded_subtree_keys), 4)
            if len(toc_bounded_subtree_keys) > 0
            else None
        )
        bounded_subtree_coverage_ready = len(toc_bounded_subtree_keys) == 0 or bounded_subtree_coverage_ratio == 1.0
        missing_body_bounded_subtree_path_rows = _build_missing_toc_outline_path_rows(
            document_id,
            missing_body_bounded_subtree_keys,
            toc_entry_details_by_document,
            toc_outline_labels_by_document,
            toc_root_outline_labels_by_document,
            body_outline_labels_by_document,
            body_outline_page_values_by_document,
            body_outline_heading_page_values_by_document,
            body_root_page_spans_by_document,
        )
        toc_body_alignment_path_rows = _build_toc_body_alignment_path_rows(
            document_id,
            toc_path_entry_details_by_document.get(document_id, []),
            toc_entry_details_by_document,
            toc_outline_labels_by_document,
            toc_root_outline_labels_by_document,
            body_outline_labels_by_document,
            body_outline_page_values_by_document,
            body_outline_heading_page_values_by_document,
            body_text_page_values_by_document,
            body_root_page_spans_by_document,
        )
        overall_alignment_ready = len(toc_outline_keys) > 0 and len(body_outline_keys) > 0 and len(matched_outline_keys) > 0
        root_outline_coverage_ratio = (
            round(len(matched_root_outline_keys) / len(toc_root_outline_keys), 4)
            if len(toc_root_outline_keys) > 0
            else None
        )
        root_alignment_required = len(toc_root_outline_keys) > 0 and len(body_root_outline_keys) > 0
        root_alignment_ready = (not root_alignment_required) or root_outline_coverage_ratio == 1.0
        rows.append(
            {
                "document_id": document_id,
                "filename": filename,
                "toc_sequence_id": selected_toc_context.get("toc_sequence_id"),
                "toc_sequence_ids": list(selected_toc_context.get("toc_sequence_ids", []) or []),
                "toc_sequence_titles": list(selected_toc_context.get("toc_sequence_titles", []) or []),
                "toc_sequence_pages": list(selected_toc_context.get("toc_sequence_pages", []) or []),
                "toc_sequence_selection": selected_toc_context.get("toc_sequence_selection"),
                "toc_sequence_alignment_scores": list(
                    selected_toc_context.get("toc_sequence_alignment_scores", []) or []
                ),
                "excluded_toc_sequence_count": int(selected_toc_context.get("excluded_toc_sequence_count", 0) or 0),
                "excluded_toc_sequence_ids": list(selected_toc_context.get("excluded_toc_sequence_ids", []) or []),
                "toc_outline_count": len(toc_outline_keys),
                "toc_root_outline_count": len(toc_root_outline_keys),
                "body_outline_count": len(body_outline_keys),
                "body_root_outline_count": len(body_root_outline_keys),
                "matched_outline_count": len(matched_outline_keys),
                "matched_root_outline_count": len(matched_root_outline_keys),
                "root_outline_coverage_ratio": root_outline_coverage_ratio,
                "comparable_root_page_count": len(comparable_root_pages),
                "toc_direct_child_count": len(toc_direct_child_keys),
                "matched_direct_child_count": len(matched_direct_child_keys),
                "direct_child_coverage_ratio": direct_child_coverage_ratio,
                "toc_bounded_subtree_count": len(toc_bounded_subtree_keys),
                "matched_bounded_subtree_count": len(matched_bounded_subtree_keys),
                "bounded_subtree_coverage_ratio": bounded_subtree_coverage_ratio,
                "missing_body_outline_count": len(missing_body_outline_keys),
                "missing_body_root_outline_count": len(missing_body_root_outline_keys),
                "extra_body_outline_count": len(extra_body_outline_keys),
                "extra_body_root_outline_count": len(extra_body_root_outline_keys),
                "matched_outline_keys": matched_outline_keys,
                "matched_root_outline_keys": matched_root_outline_keys,
                "comparable_root_page_outline_keys": [item["outline_key"] for item in comparable_root_pages],
                "toc_root_page_order_keys": toc_root_page_order,
                "body_root_page_order_keys": body_root_page_order,
                "root_page_offset_values": root_page_offset_values,
                "projected_root_page_values": projected_root_page_values,
                "root_page_alignment_rows": root_page_alignment_rows,
                "missing_body_direct_child_outline_indices": [
                    body_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in sorted(missing_body_direct_child_keys)
                ],
                "missing_body_direct_child_path_rows": missing_body_direct_child_path_rows,
                "missing_body_bounded_subtree_outline_indices": [
                    body_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in sorted(missing_body_bounded_subtree_keys)
                ],
                "missing_body_bounded_subtree_path_rows": missing_body_bounded_subtree_path_rows,
                "toc_body_alignment_path_rows": toc_body_alignment_path_rows,
                "toc_outline_indices": [
                    toc_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in toc_outline_keys
                ],
                "toc_root_outline_indices": [
                    toc_root_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in toc_root_outline_keys
                ],
                "body_outline_indices": [
                    body_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in body_outline_keys
                ],
                "body_root_outline_indices": [
                    body_root_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in body_root_outline_keys
                ],
                "missing_body_outline_indices": [
                    toc_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in missing_body_outline_keys
                ],
                "missing_body_root_outline_indices": [
                    effective_toc_root_outline_labels.get(key, key)
                    for key in missing_body_root_outline_keys
                ],
                "extra_body_outline_indices": [
                    body_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in extra_body_outline_keys
                ],
                "extra_body_root_outline_indices": [
                    body_root_outline_labels_by_document.get(document_id, {}).get(key, key)
                    for key in extra_body_root_outline_keys
                ],
                "overall_alignment_ready": overall_alignment_ready,
                "root_alignment_ready": root_alignment_ready,
                "root_page_order_ready": root_page_order_ready,
                "root_page_offset_ready": root_page_offset_ready,
                "root_page_span_ready": root_page_span_ready,
                "direct_child_coverage_ready": direct_child_coverage_ready,
                "bounded_subtree_coverage_ready": bounded_subtree_coverage_ready,
                "alignment_ready": (
                    overall_alignment_ready
                    and root_alignment_ready
                    and root_page_order_ready
                    and root_page_offset_ready
                    and direct_child_coverage_ready
                    and bounded_subtree_coverage_ready
                ),
            }
        )
    return rows


def _build_toc_body_alignment_path_rows(
    document_id: str,
    toc_entry_details: list[dict[str, Any]],
    toc_entry_details_by_document: dict[str, dict[str, dict[str, Any]]],
    toc_outline_labels_by_document: dict[str, dict[str, str]],
    toc_root_outline_labels_by_document: dict[str, dict[str, str]],
    body_outline_labels_by_document: dict[str, dict[str, str]],
    body_outline_page_values_by_document: dict[str, dict[str, list[int]]],
    body_outline_heading_page_values_by_document: dict[str, dict[str, list[int]]],
    body_text_page_values_by_document: dict[str, dict[str, list[int]]],
    body_root_page_spans_by_document: dict[str, dict[str, list[Any]]],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    entry_details_lookup = toc_entry_details_by_document.get(document_id, {})
    outline_label_lookup = toc_outline_labels_by_document.get(document_id, {})
    root_outline_label_lookup = toc_root_outline_labels_by_document.get(document_id, {})
    body_outline_label_lookup = body_outline_labels_by_document.get(document_id, {})
    body_outline_page_lookup = body_outline_page_values_by_document.get(document_id, {})
    body_outline_heading_page_lookup = body_outline_heading_page_values_by_document.get(document_id, {})
    body_text_page_lookup = body_text_page_values_by_document.get(document_id, {})
    body_root_page_span_lookup = body_root_page_spans_by_document.get(document_id, {})

    for details in _sort_toc_entry_details_by_path(toc_entry_details):
        details = dict(details or {})
        outline_key = str(details.get("normalized_outline_index") or "").strip()
        root_normalized_outline_index = str(details.get("root_normalized_outline_index") or "").strip() or None
        parent_normalized_outline_index = str(details.get("parent_normalized_outline_index") or "").strip() or None
        normalized_outline_index = outline_key or None
        page_locator_value = _coerce_int(details.get("page_locator_value"))

        heading_pages = list(body_outline_heading_page_lookup.get(outline_key, []) or []) if outline_key else []
        outline_pages = list(body_outline_page_lookup.get(outline_key, []) or []) if outline_key else []
        root_span = list(body_root_page_span_lookup.get(outline_key, []) or []) if outline_key else []
        title_pages = _resolve_body_title_anchor_pages(
            details,
            body_text_page_lookup,
            page_locator_value,
        )
        root_page_start = _coerce_int(root_span[0] if len(root_span) > 0 else None)
        body_anchor_page = _select_best_body_anchor_page(
            page_locator_value,
            [*heading_pages, *outline_pages] if heading_pages else [*outline_pages, *title_pages],
            root_page_start,
        )
        has_body_match = body_anchor_page is not None and body_anchor_page > 0
        body_anchor_kind = None
        body_anchor_outline_index = None
        alignment_status = "missing"
        if has_body_match:
            body_anchor_outline_index = body_outline_label_lookup.get(
                outline_key,
                outline_label_lookup.get(outline_key, outline_key),
            )
            if heading_pages:
                body_anchor_kind = "heading"
            elif outline_pages:
                body_anchor_kind = "body"
            elif title_pages:
                body_anchor_kind = "title"
            else:
                body_anchor_kind = "root"
            alignment_status = "matched"
        else:
            nearest_outline_index, nearest_page = _resolve_nearest_body_anchor_for_missing_outline(
                normalized_outline_index,
                body_outline_page_lookup,
                body_outline_heading_page_lookup,
                body_root_page_span_lookup,
                body_outline_label_lookup,
            )
            if nearest_page is not None and nearest_page > 0:
                body_anchor_outline_index = nearest_outline_index
                body_anchor_page = nearest_page
                body_anchor_kind = "nearest_parent"
                alignment_status = "nearest_parent"

        rows.append(
            {
                "root_outline_index": (
                    str(details.get("root_outline_index") or "").strip()
                    or root_outline_label_lookup.get(root_normalized_outline_index or "", root_normalized_outline_index)
                ),
                "root_normalized_outline_index": root_normalized_outline_index,
                "parent_outline_index": (
                    str(details.get("parent_outline_index") or "").strip()
                    or outline_label_lookup.get(parent_normalized_outline_index or "", parent_normalized_outline_index)
                ),
                "parent_normalized_outline_index": parent_normalized_outline_index,
                "outline_index": (
                    str(details.get("outline_index") or "").strip()
                    or outline_label_lookup.get(normalized_outline_index or "", normalized_outline_index)
                ),
                "normalized_outline_index": normalized_outline_index,
                "outline_path": details.get("outline_path"),
                "text_path": details.get("text_path"),
                "page_locator_value": page_locator_value,
                "navigation_page": _coerce_int(details.get("navigation_page")),
                "level": _coerce_int(details.get("level")),
                "body_anchor_outline_index": body_anchor_outline_index,
                "body_anchor_page": body_anchor_page,
                "body_anchor_kind": body_anchor_kind,
                "alignment_status": alignment_status,
                "page_offset": (
                    int(body_anchor_page) - int(page_locator_value)
                    if alignment_status == "matched"
                    and body_anchor_page is not None
                    and page_locator_value is not None
                    else None
                ),
                "has_body_match": has_body_match,
            }
        )
    return rows


def _sort_toc_outline_keys_by_path(
    toc_outline_keys: set[str],
    entry_details_lookup: dict[str, dict[str, Any]],
) -> list[str]:
    return sorted(
        toc_outline_keys,
        key=lambda outline_key: (
            _coerce_int(entry_details_lookup.get(outline_key, {}).get("navigation_page")) or 0,
            _coerce_int(entry_details_lookup.get(outline_key, {}).get("page_locator_value")) or 0,
            _coerce_int(entry_details_lookup.get(outline_key, {}).get("level")) or 0,
            _outline_path_sort_key(entry_details_lookup.get(outline_key, {}).get("outline_path") or outline_key),
            outline_key,
        ),
    )


def _sort_toc_entry_details_by_path(toc_entry_details: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(
        list(toc_entry_details or []),
        key=lambda details: (
            _coerce_int(details.get("navigation_page")) or 0,
            _coerce_int(details.get("page_locator_value")) or 0,
            _coerce_int(details.get("level")) or 0,
            _coerce_int(details.get("sequence_entry_index")) or 0,
            _outline_path_sort_key(details.get("outline_path") or details.get("text_path") or details.get("text")),
        ),
    )


def _outline_path_sort_key(value: Any) -> tuple[Any, ...]:
    normalized_path = str(value or "").replace(">", ".")
    tokens: list[Any] = []
    for token in re.split(r"[^0-9A-Za-z]+", normalized_path):
        if not token:
            continue
        tokens.append(int(token) if token.isdigit() else token.lower())
    return tuple(tokens)


def _resolve_body_title_anchor_pages(
    details: dict[str, Any],
    body_text_page_lookup: dict[str, list[int]],
    page_locator_value: int | None,
) -> list[int]:
    title = _resolve_toc_entry_title(details)
    title_key = _normalize_heading_title_for_comparison(title)
    if not title_key:
        return []
    candidate_pages = _dedupe_positive_page_values(body_text_page_lookup.get(title_key, []) or [])
    if page_locator_value is None:
        return candidate_pages
    return [page for page in candidate_pages if abs(page - page_locator_value) <= 2]


def _build_missing_toc_outline_path_rows(
    document_id: str,
    missing_outline_keys: set[str],
    toc_entry_details_by_document: dict[str, dict[str, dict[str, Any]]],
    toc_outline_labels_by_document: dict[str, dict[str, str]],
    toc_root_outline_labels_by_document: dict[str, dict[str, str]],
    body_outline_labels_by_document: dict[str, dict[str, str]],
    body_outline_page_values_by_document: dict[str, dict[str, list[int]]],
    body_outline_heading_page_values_by_document: dict[str, dict[str, list[int]]],
    body_root_page_spans_by_document: dict[str, dict[str, list[Any]]],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    entry_details_lookup = toc_entry_details_by_document.get(document_id, {})
    outline_label_lookup = toc_outline_labels_by_document.get(document_id, {})
    root_outline_label_lookup = toc_root_outline_labels_by_document.get(document_id, {})
    body_outline_label_lookup = body_outline_labels_by_document.get(document_id, {})
    body_outline_page_lookup = body_outline_page_values_by_document.get(document_id, {})
    body_outline_heading_page_lookup = body_outline_heading_page_values_by_document.get(document_id, {})
    body_root_page_span_lookup = body_root_page_spans_by_document.get(document_id, {})

    for outline_key in sorted(missing_outline_keys):
        details = dict(entry_details_lookup.get(outline_key, {}) or {})
        root_normalized_outline_index = str(details.get("root_normalized_outline_index") or "").strip() or None
        parent_normalized_outline_index = str(details.get("parent_normalized_outline_index") or "").strip() or None
        normalized_outline_index = str(details.get("normalized_outline_index") or outline_key).strip() or None
        nearest_body_anchor_outline_index, nearest_body_anchor_page = _resolve_nearest_body_anchor_for_missing_outline(
            normalized_outline_index,
            body_outline_page_lookup,
            body_outline_heading_page_lookup,
            body_root_page_span_lookup,
            body_outline_label_lookup,
        )
        rows.append(
            {
                "root_outline_index": (
                    str(details.get("root_outline_index") or "").strip()
                    or root_outline_label_lookup.get(root_normalized_outline_index or "", root_normalized_outline_index)
                ),
                "root_normalized_outline_index": root_normalized_outline_index,
                "parent_outline_index": (
                    str(details.get("parent_outline_index") or "").strip()
                    or outline_label_lookup.get(parent_normalized_outline_index or "", parent_normalized_outline_index)
                ),
                "parent_normalized_outline_index": parent_normalized_outline_index,
                "outline_index": (
                    str(details.get("outline_index") or "").strip()
                    or outline_label_lookup.get(normalized_outline_index or "", normalized_outline_index)
                ),
                "normalized_outline_index": normalized_outline_index,
                "outline_path": details.get("outline_path"),
                "text_path": details.get("text_path"),
                "page_locator_value": _coerce_int(details.get("page_locator_value")),
                "navigation_page": _coerce_int(details.get("navigation_page")),
                "level": _coerce_int(details.get("level")),
                "nearest_body_anchor_outline_index": nearest_body_anchor_outline_index,
                "nearest_body_anchor_page": nearest_body_anchor_page,
            }
        )
    return rows


def _candidate_parent_outline_keys(outline_index: str | None) -> list[str]:
    candidate = str(outline_index or "").strip()
    if not candidate:
        return []
    segments = [segment for segment in candidate.split(".") if segment]
    if len(segments) <= 1:
        return []

    parents: list[str] = []
    seen: set[str] = set()

    def _append(value: str | None) -> None:
        normalized = str(value or "").strip()
        if not normalized or normalized in seen or normalized == candidate:
            return
        parents.append(normalized)
        seen.add(normalized)

    for depth in range(len(segments) - 1, 0, -1):
        prefix_segments = segments[:depth]
        prefix = ".".join(prefix_segments)
        _append(prefix)
        if len(prefix_segments) == 2 and prefix_segments[1] != "0":
            _append(f"{prefix_segments[0]}.0")
            _append(prefix_segments[0])

    return parents


def _resolve_toc_confirmed_body_heading(
    paragraph: dict[str, Any],
    toc_entry_details_lookup: dict[str, dict[str, Any]],
) -> dict[str, Any] | None:
    text = str(paragraph.get("text") or "").strip()
    if not text:
        return None
    marker = parse_outline_heading(text)
    if marker is None:
        return None
    outline_index = marker.raw_marker
    title = marker.title
    normalized_outline_index = normalize_outline_marker(outline_index)
    if not normalized_outline_index or (not title and not _is_appendix_outline_index(outline_index)):
        return None
    details = dict(toc_entry_details_lookup.get(normalized_outline_index, {}) or {})
    if not details:
        details = _resolve_path_qualified_toc_body_heading_details(
            normalized_outline_index,
            title,
            paragraph,
            toc_entry_details_lookup,
        )
    if not details:
        return None
    toc_title = _resolve_toc_entry_title(details)
    appendix_heading_outline_only = _is_appendix_outline_index(outline_index) and not title
    if toc_title and not _heading_titles_are_compatible(title, toc_title) and not appendix_heading_outline_only:
        details = _resolve_path_qualified_toc_body_heading_details(
            normalized_outline_index,
            title,
            paragraph,
            toc_entry_details_lookup,
        )
        if not details:
            return None
        toc_title = _resolve_toc_entry_title(details)
        if toc_title and not _heading_titles_are_compatible(title, toc_title):
            return None
    page_span = list(paragraph.get("page_span", [None, None]) or [None, None])
    page = _coerce_int(paragraph.get("page")) or _coerce_int(page_span[0] if page_span else None)
    if page is None or page <= 0:
        return None
    toc_page_locator_value = _coerce_int(details.get("page_locator_value"))
    if toc_page_locator_value is not None and abs(page - toc_page_locator_value) > 2:
        return None
    return {
        "outline_index": outline_index,
        "normalized_outline_index": str(details.get("normalized_outline_index") or normalized_outline_index).strip(),
        "title": title,
        "page": page,
    }


def _is_appendix_outline_index(value: Any) -> bool:
    return bool(re.fullmatch(r"APPENDIX\s+[A-Z]+", str(value or "").strip(), re.IGNORECASE))


def _resolve_path_qualified_toc_body_heading_details(
    normalized_outline_index: str,
    title: str,
    paragraph: dict[str, Any],
    toc_entry_details_lookup: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    page_span = list(paragraph.get("page_span", [None, None]) or [None, None])
    page = _coerce_int(paragraph.get("page")) or _coerce_int(page_span[0] if page_span else None)
    candidates: list[dict[str, Any]] = []
    for key, details in toc_entry_details_lookup.items():
        details = dict(details or {})
        if not str(key or "").endswith(f".{normalized_outline_index}"):
            continue
        toc_title = _resolve_toc_entry_title(details)
        if toc_title and not _heading_titles_are_compatible(title, toc_title):
            continue
        toc_page_locator_value = _coerce_int(details.get("page_locator_value"))
        if page is not None and toc_page_locator_value is not None and abs(page - toc_page_locator_value) > 2:
            continue
        candidates.append(details)
    if not candidates:
        return {}
    if page is None:
        return candidates[0]
    return min(
        candidates,
        key=lambda details: (
            abs(page - (_coerce_int(details.get("page_locator_value")) or page)),
            _coerce_int(details.get("sequence_entry_index")) or 0,
        ),
    )


def _resolve_toc_entry_title(details: dict[str, Any]) -> str:
    text = str(details.get("text") or "").strip()
    if text:
        return text
    text_path_segments = [
        str(segment or "").strip()
        for segment in list(details.get("text_path_segments", []) or [])
        if str(segment or "").strip()
    ]
    return text_path_segments[-1] if text_path_segments else ""


def _resolve_body_heading_title(paragraph: dict[str, Any]) -> str:
    section_title = str(paragraph.get("section_title") or "").strip()
    if section_title:
        return section_title
    text = str(paragraph.get("text") or "").strip()
    marker = parse_outline_heading(text)
    if marker is not None:
        return marker.title
    return text


def _resolve_compatible_heading_page_values(
    heading_title_pages: list[dict[str, Any]],
    toc_title: str,
) -> list[int]:
    if not str(toc_title or "").strip():
        return _dedupe_positive_page_values([item.get("page") for item in heading_title_pages])
    return _dedupe_positive_page_values(
        [
            item.get("page")
            for item in heading_title_pages
            if _heading_titles_are_compatible(str(item.get("title") or "").strip(), toc_title)
        ]
    )


def _heading_titles_are_compatible(body_title: str, toc_title: str) -> bool:
    return outline_titles_compatible(body_title, toc_title)


def _normalize_heading_title_for_comparison(value: str) -> str:
    return "".join(character.lower() for character in str(value or "") if character.isalnum())


def _split_heading_title_tokens(value: str) -> list[str]:
    return [
        token.lower()
        for token in re.findall(r"[A-Za-z0-9]+|[\u4e00-\u9fff]", str(value or ""))
        if token.strip()
    ]


def _resolve_nearest_body_anchor_for_missing_outline(
    normalized_outline_index: str | None,
    body_outline_page_lookup: dict[str, list[int]],
    body_outline_heading_page_lookup: dict[str, list[int]],
    body_root_page_span_lookup: dict[str, list[Any]],
    body_outline_label_lookup: dict[str, str],
) -> tuple[str | None, int | None]:
    for ancestor_key in _candidate_parent_outline_keys(normalized_outline_index):
        candidate_pages = _dedupe_positive_page_values(
            list(body_outline_heading_page_lookup.get(ancestor_key, []) or [])
            + list(body_outline_page_lookup.get(ancestor_key, []) or [])
        )
        if candidate_pages:
            return body_outline_label_lookup.get(ancestor_key, ancestor_key), candidate_pages[0]
        root_span = list(body_root_page_span_lookup.get(ancestor_key, []) or [])
        root_page_start = _coerce_int(root_span[0] if len(root_span) > 0 else None)
        if root_page_start is not None and root_page_start > 0:
            return body_outline_label_lookup.get(ancestor_key, ancestor_key), root_page_start
    return None, None


def _rule_result_to_payload(rule_result: RuleResult) -> dict[str, Any]:
    payload = {
        "rule_id": rule_result.rule_id,
        "category": rule_result.category,
        "status": rule_result.status,
        "message": rule_result.message,
    }
    if rule_result.citation:
        payload["citation"] = rule_result.citation
    if rule_result.scope:
        payload["scope"] = rule_result.scope
    if rule_result.scope_status:
        payload["scope_status"] = rule_result.scope_status
    if rule_result.details:
        payload["details"] = dict(rule_result.details)
    return payload


def _build_risk_payloads(
    rule_results: list[RuleResult],
) -> list[dict[str, Any]]:
    risks: list[dict[str, Any]] = []

    for rule_result in rule_results:
        if rule_result.status not in {"fail", "warn"}:
            continue
        severity = "high" if rule_result.category == "hard" and rule_result.status == "fail" else "medium"
        risk_payload = {
            "risk_id": f"RULE-{rule_result.rule_id}",
            "severity": severity,
            "reason": rule_result.message,
        }
        if rule_result.citation:
            risk_payload["citation"] = rule_result.citation
        if rule_result.details:
            risk_payload["details"] = dict(rule_result.details)
        risks.append(risk_payload)

    return risks


def _normalize_fact_value(value: Any) -> str:
    return " ".join(str(value or "").split()).strip()


def _sorted_distinct_values(values: Any) -> list[str]:
    normalized_values = {
        _normalize_fact_value(value)
        for value in values
        if _normalize_fact_value(value)
    }
    return sorted(normalized_values)


def _dedupe_preserve_order_strings(values: list[str]) -> list[str]:
    deduped: list[str] = []
    seen: set[str] = set()
    for value in values:
        normalized = str(value or "").strip()
        if not normalized or normalized in seen:
            continue
        deduped.append(normalized)
        seen.add(normalized)
    return deduped


def _normalize_xml_name_for_rules(value: Any) -> str:
    return "".join(ch for ch in str(value or "").strip().lower() if ch.isalnum())


def _normalize_outline_comparison_key(outline_index: Any) -> str:
    return normalize_outline_marker(outline_index)


def _coerce_int(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    candidate = str(value or "").strip()
    if not candidate:
        return None
    if candidate.isdigit():
        return int(candidate)
    return None


def _dedupe_positive_page_values(values: list[Any]) -> list[int]:
    normalized: list[int] = []
    seen: set[int] = set()
    for value in values:
        page = _coerce_int(value)
        if page is None or page <= 0 or page in seen:
            continue
        seen.add(page)
        normalized.append(page)
    return normalized


def _select_best_body_anchor_page(
    toc_page_locator_value: int | None,
    candidate_pages: list[Any],
    fallback_page: int | None,
) -> int | None:
    normalized_candidates = _dedupe_positive_page_values(candidate_pages)
    if not normalized_candidates:
        return fallback_page
    if toc_page_locator_value is None:
        return min(normalized_candidates)
    return min(
        normalized_candidates,
        key=lambda page: (
            abs(page - toc_page_locator_value),
            0 if page >= toc_page_locator_value else 1,
            page,
        ),
    )


def _merge_toc_sequence_contexts(
    document_id: str,
    contexts: list[dict[str, Any]],
) -> dict[str, Any]:
    toc_outline_keys: set[str] = set()
    toc_outline_labels: dict[str, str] = {}
    toc_root_outline_keys: set[str] = set()
    toc_root_outline_labels: dict[str, str] = {}
    toc_direct_child_keys_by_root: dict[str, set[str]] = {}
    toc_bounded_subtree_keys_by_root: dict[str, set[str]] = {}
    toc_entry_details: dict[str, dict[str, Any]] = {}
    toc_path_entry_details: list[dict[str, Any]] = []
    sequence_ids: list[str] = []
    titles: list[str] = []
    pages: list[int] = []

    for context in contexts:
        sequence_id = str(context.get("toc_sequence_id") or "").strip()
        if sequence_id and sequence_id not in sequence_ids:
            sequence_ids.append(sequence_id)
        title = str(context.get("title") or "").strip()
        if title and title not in titles:
            titles.append(title)
        for page in list(context.get("pages", []) or []):
            coerced_page = _coerce_int(page)
            if coerced_page is not None and coerced_page > 0 and coerced_page not in pages:
                pages.append(coerced_page)
        toc_outline_keys.update(set(context.get("toc_outline_keys", set()) or set()))
        toc_root_outline_keys.update(set(context.get("toc_root_outline_keys", set()) or set()))
        for key, label in dict(context.get("toc_outline_labels", {}) or {}).items():
            toc_outline_labels.setdefault(str(key), str(label))
        for key, label in dict(context.get("toc_root_outline_labels", {}) or {}).items():
            toc_root_outline_labels.setdefault(str(key), str(label))
        for key, values in dict(context.get("toc_direct_child_keys_by_root", {}) or {}).items():
            toc_direct_child_keys_by_root.setdefault(str(key), set()).update(set(values or set()))
        for key, values in dict(context.get("toc_bounded_subtree_keys_by_root", {}) or {}).items():
            toc_bounded_subtree_keys_by_root.setdefault(str(key), set()).update(set(values or set()))
        for key, details in dict(context.get("toc_entry_details", {}) or {}).items():
            toc_entry_details.setdefault(str(key), dict(details or {}))
        toc_path_entry_details.extend(list(context.get("toc_path_entry_details", []) or []))

    return {
        "document_id": document_id,
        "toc_sequence_id": sequence_ids[0] if len(sequence_ids) == 1 else None,
        "toc_sequence_ids": sequence_ids,
        "toc_sequence_titles": titles,
        "toc_sequence_pages": sorted(pages),
        "toc_outline_keys": toc_outline_keys,
        "toc_outline_labels": toc_outline_labels,
        "toc_root_outline_keys": toc_root_outline_keys,
        "toc_root_outline_labels": toc_root_outline_labels,
        "toc_direct_child_keys_by_root": toc_direct_child_keys_by_root,
        "toc_bounded_subtree_keys_by_root": toc_bounded_subtree_keys_by_root,
        "toc_entry_details": toc_entry_details,
        "toc_path_entry_details": toc_path_entry_details,
    }


def _with_toc_path_qualified_comparison_keys(
    details: dict[str, Any],
    duplicate_outline_counts: dict[str, int],
) -> dict[str, Any]:
    normalized = str(details.get("normalized_outline_index") or "").strip()
    parent = str(details.get("parent_normalized_outline_index") or "").strip()
    if not normalized or not parent or int(duplicate_outline_counts.get(normalized, 0) or 0) <= 1:
        return details
    qualified = f"{parent}.{normalized}"
    updated = dict(details)
    updated["normalized_outline_index"] = qualified
    updated["path_qualified_outline_index"] = qualified
    return updated


def _score_toc_sequence_context_for_body_alignment(
    context: dict[str, Any],
    body_outline_keys: set[str],
    body_root_outline_keys: set[str],
    body_outline_page_lookup: dict[str, list[int]],
    body_outline_heading_page_lookup: dict[str, list[int]],
    body_outline_heading_title_page_lookup: dict[str, list[dict[str, Any]]],
    body_root_page_span_lookup: dict[str, list[Any]],
) -> dict[str, Any]:
    toc_outline_keys = set(context.get("toc_outline_keys", set()) or set())
    toc_root_outline_keys = set(context.get("toc_root_outline_keys", set()) or set())
    matched_outline_keys = toc_outline_keys & set(body_outline_keys)
    matched_root_outline_keys = toc_root_outline_keys & set(body_root_outline_keys)
    comparable_offsets: list[int] = []
    for root_key in sorted(matched_root_outline_keys):
        details = dict(dict(context.get("toc_entry_details", {}) or {}).get(root_key, {}) or {})
        toc_page = _coerce_int(details.get("page_locator_value"))
        toc_title = _resolve_toc_entry_title(details)
        body_span = list(body_root_page_span_lookup.get(root_key, []) or [])
        body_start = _coerce_int(body_span[0] if body_span else None)
        compatible_heading_pages = _resolve_compatible_heading_page_values(
            list(body_outline_heading_title_page_lookup.get(root_key, []) or []),
            toc_title,
        )
        body_start = _select_best_body_anchor_page(
            toc_page,
            [
                *(
                    compatible_heading_pages
                    if compatible_heading_pages
                    else list(body_outline_heading_page_lookup.get(root_key, []) or [])
                ),
                *list(body_outline_page_lookup.get(root_key, []) or []),
            ],
            body_start,
        )
        if toc_page is not None and body_start is not None:
            comparable_offsets.append(int(body_start) - int(toc_page))
    stable_offset = len(comparable_offsets) >= 2 and len(set(comparable_offsets)) == 1
    return {
        "toc_sequence_id": context.get("toc_sequence_id"),
        "toc_outline_count": len(toc_outline_keys),
        "toc_root_outline_count": len(toc_root_outline_keys),
        "matched_outline_count": len(matched_outline_keys),
        "matched_root_outline_count": len(matched_root_outline_keys),
        "root_coverage_ratio": (
            round(len(matched_root_outline_keys) / len(toc_root_outline_keys), 4)
            if toc_root_outline_keys
            else None
        ),
        "matched_outline_ratio": (
            round(len(matched_outline_keys) / len(toc_outline_keys), 4)
            if toc_outline_keys
            else 0.0
        ),
        "comparable_root_offset_count": len(comparable_offsets),
        "root_page_offset_values": comparable_offsets,
        "stable_root_page_offset": stable_offset,
    }


def _select_document_toc_sequence_context(
    document_id: str,
    contexts: list[dict[str, Any]],
    body_outline_keys: set[str],
    body_root_outline_keys: set[str],
    body_outline_page_lookup: dict[str, list[int]],
    body_outline_heading_page_lookup: dict[str, list[int]],
    body_outline_heading_title_page_lookup: dict[str, list[dict[str, Any]]],
    body_root_page_span_lookup: dict[str, list[Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    document_contexts = [
        context
        for context in contexts
        if str(context.get("document_id") or "").strip() == document_id
    ]
    if not document_contexts:
        return _merge_toc_sequence_contexts(document_id, []), []
    if len(document_contexts) == 1:
        selected = _merge_toc_sequence_contexts(document_id, document_contexts)
        selected["toc_sequence_selection"] = "single_sequence"
        selected["excluded_toc_sequence_count"] = 0
        selected["excluded_toc_sequence_ids"] = []
        return selected, []

    scored_contexts: list[tuple[tuple[Any, ...], dict[str, Any], dict[str, Any]]] = []
    for order, context in enumerate(document_contexts):
        score = _score_toc_sequence_context_for_body_alignment(
            context,
            body_outline_keys,
            body_root_outline_keys,
            body_outline_page_lookup,
            body_outline_heading_page_lookup,
            body_outline_heading_title_page_lookup,
            body_root_page_span_lookup,
        )
        sort_key = (
            1 if score["matched_root_outline_count"] >= 2 and score["stable_root_page_offset"] else 0,
            score["matched_root_outline_count"],
            score["matched_outline_count"],
            score["matched_outline_ratio"],
            -min([
                _coerce_int(page) or 999999
                for page in list(context.get("pages", []) or [])
            ] or [999999]),
            -order,
        )
        scored_contexts.append((sort_key, context, score))
    scored_contexts.sort(key=lambda item: item[0], reverse=True)
    best_sort_key, best_context, best_score = scored_contexts[0]
    has_discriminating_body_evidence = (
        int(best_score.get("matched_root_outline_count", 0) or 0) >= 2
        or (
            int(best_score.get("matched_root_outline_count", 0) or 0) >= 1
            and int(best_score.get("matched_outline_count", 0) or 0) >= 2
        )
    )
    selected_contexts = [best_context] if has_discriminating_body_evidence else document_contexts
    selected = _merge_toc_sequence_contexts(document_id, selected_contexts)
    selected["toc_sequence_selection"] = (
        "body_aligned_primary_sequence" if has_discriminating_body_evidence else "all_sequences_no_primary_evidence"
    )
    selected["toc_sequence_alignment_scores"] = [score for _, _, score in scored_contexts]
    excluded_contexts = [context for context in document_contexts if context not in selected_contexts]
    selected["excluded_toc_sequence_count"] = len(excluded_contexts)
    selected["excluded_toc_sequence_ids"] = [
        str(context.get("toc_sequence_id") or "").strip()
        for context in excluded_contexts
        if str(context.get("toc_sequence_id") or "").strip()
    ]
    return selected, excluded_contexts


def _is_content_bearing_fact_support_role(source_type: str, unit_role: str) -> bool:
    normalized_source_type = str(source_type or "").strip().lower()
    normalized_unit_role = str(unit_role or "").strip().lower()
    if normalized_source_type == "text":
        return normalized_unit_role == "body"
    if normalized_source_type == "table":
        return normalized_unit_role == "row"
    if normalized_source_type == "image":
        return normalized_unit_role in {"embedded_text", "caption"}
    return False


def _load_ctd_requirement_record() -> dict[str, Any]:
    return _load_requirement_record(_CTD_REQUIREMENT_ID)


def _load_requirement_record(requirement_id: str) -> dict[str, Any]:
    normalized_requirement_id = str(requirement_id or "").strip()
    if not normalized_requirement_id:
        return {}
    for path in _REQUIREMENT_MATRIX_PATHS:
        if not path.exists():
            continue
        payload = json.loads(path.read_text(encoding="utf-8"))
        for requirement in payload.get("requirements", []) or []:
            if str(requirement.get("requirement_id") or "").strip() == normalized_requirement_id:
                return dict(requirement)
    return {}


def _load_regulation_clause_metadata(citation_anchor: str) -> dict[str, str]:
    global _REGULATION_CLAUSE_METADATA_LOOKUP
    normalized_citation_anchor = str(citation_anchor or "").strip()
    if not normalized_citation_anchor:
        return {}
    if _REGULATION_CLAUSE_METADATA_LOOKUP is None:
        lookup: dict[str, dict[str, str]] = {}
        clause_paths = sorted(_REGULATION_NORMALIZED_ROOT.glob("*.clauses.json"))
        for clause_path in clause_paths:
            if not clause_path.exists():
                continue
            payload = json.loads(clause_path.read_text(encoding="utf-8"))
            for clause in payload.get("clauses", []) or []:
                clause_citation_anchor = str(((clause.get("source_locator") or {}).get("citation_anchor")) or "").strip()
                if not clause_citation_anchor:
                    continue
                severity = str(clause.get("severity") or "").strip()
                if not severity:
                    normalized_text = str(clause.get("normalized_text") or "").strip()
                    for candidate in ("错误", "警告", "提示信息"):
                        if normalized_text.endswith(candidate):
                            severity = candidate
                            break
                lookup[clause_citation_anchor] = {
                    "source_clause_id": str(clause.get("clause_id") or "").strip(),
                    "regulation_id": str(clause.get("regulation_id") or "").strip(),
                    "regulation_title": str(clause.get("regulation_title") or "").strip(),
                    "heading": str(clause.get("heading") or "").strip(),
                    "severity": severity,
                }
        _REGULATION_CLAUSE_METADATA_LOOKUP = lookup
    return dict((_REGULATION_CLAUSE_METADATA_LOOKUP or {}).get(normalized_citation_anchor) or {})


def _build_document_search_corpus(
    document: dict[str, Any],
    evidence_rows: list[dict[str, Any]],
) -> str:
    parts = [
        str(document.get("filename") or "").strip(),
        str(document.get("source_path") or "").strip(),
    ]
    for row in evidence_rows[:12]:
        parts.append(str(row.get("content_text") or "").strip())
    return "\n".join(part for part in parts if part).strip()


def _collect_documents_by_pattern(
    material_contract: dict[str, Any],
    *,
    signal_pattern: re.Pattern[str],
) -> list[dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    evidence_index = list(material_contract.get("evidence_index", []) or [])
    section_index = list(material_contract.get("section_index", []) or [])
    evidence_rows_by_document: dict[str, list[dict[str, Any]]] = {}
    for row in evidence_index:
        document_id = str(row.get("document_id") or "").strip()
        evidence_rows_by_document.setdefault(document_id, []).append(dict(row))
    section_rows_by_document: dict[str, list[dict[str, Any]]] = {}
    for row in section_index:
        document_id = str(row.get("document_id") or "").strip()
        section_rows_by_document.setdefault(document_id, []).append(dict(row))

    matched_documents: list[dict[str, Any]] = []
    for document in documents:
        document_id = str(document.get("document_id") or "").strip()
        filename = str(document.get("filename") or document_id or "unknown-document").strip()
        evidence_rows = list(evidence_rows_by_document.get(document_id, []))
        search_corpus = _build_document_search_corpus(document, evidence_rows)
        if not search_corpus or not signal_pattern.search(search_corpus):
            continue
        classification = dict(document.get("classification", {}) or {})
        section_rows = list(section_rows_by_document.get(document_id, []))
        matched_documents.append(
            {
                "document_id": document_id,
                "filename": filename,
                "module_label": str(classification.get("module_label") or "").strip(),
                "signal_hits": [
                    str(item).strip()
                    for item in classification.get("signal_hits", []) or []
                    if str(item).strip()
                ],
                "evidence_refs": _dedupe_preserve_order_strings(
                    [
                        str(row.get("evidence_id") or "").strip()
                        for row in evidence_rows
                        if str(row.get("evidence_id") or "").strip()
                    ]
                ),
                "section_refs": [
                    {
                        "module_label": row.get("module_label"),
                        "outline_index": row.get("outline_index"),
                        "section_title": row.get("section_title"),
                        "page_span": list(row.get("page_span", []) or []),
                    }
                    for row in section_rows
                ],
            }
        )
    return matched_documents


_MATERIAL_ROLE_PATTERNS: dict[str, re.Pattern[str]] = {
    "general_registration_dossier": _GENERAL_REGISTRATION_DOSSIER_PATTERN,
    "clinical_trial_materials": _CLINICAL_TRIAL_SIGNAL_PATTERN,
    "reference_sample_materials": _REFERENCE_SAMPLE_SIGNAL_PATTERN,
    "api_supporting_materials": _API_SUPPORTING_PATTERN,
    "certificate_or_license_materials": _CERTIFICATE_OR_LICENSE_PATTERN,
    "quality_standard_materials": _QUALITY_STANDARD_PATTERN,
    "nonclinical_study_materials": _NONCLINICAL_STUDY_PATTERN,
}


def _collect_documents_by_material_role(
    material_contract: dict[str, Any],
    role_name: str,
) -> list[dict[str, Any]]:
    pattern = _MATERIAL_ROLE_PATTERNS.get(str(role_name or "").strip())
    if pattern is None:
        return []
    return _collect_documents_by_pattern(material_contract, signal_pattern=pattern)


def _build_clause_requirement_details(
    *,
    citation_anchor: str,
    match_strength: str,
    matched_documents: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "source_clause_id": str(citation_anchor or "").replace("#", ":"),
        "citation_anchor": citation_anchor,
        "match_strength": match_strength,
        "matched_documents": matched_documents,
    }


def _build_requirement_details(
    requirement: dict[str, Any],
    *,
    fallback_requirement_id: str,
    fallback_citation_anchor: str,
    match_strength: str,
    matched_documents: list[dict[str, Any]],
    extra_details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    from core.regulation_provenance import build_requirement_provenance

    resolved_citation_anchor = str(requirement.get("citation_anchor") or fallback_citation_anchor).strip()
    clause_metadata = _load_regulation_clause_metadata(resolved_citation_anchor)
    source_clause_id = str(requirement.get("source_clause_id") or "").strip()
    if not source_clause_id:
        source_clause_id = str(clause_metadata.get("source_clause_id") or "").strip()
    if not source_clause_id and resolved_citation_anchor:
        source_clause_id = resolved_citation_anchor.replace("#", ":")
    details = {
        "requirement_id": str(requirement.get("requirement_id") or fallback_requirement_id).strip(),
        "source_clause_id": source_clause_id,
        "citation_anchor": resolved_citation_anchor,
        "match_strength": match_strength,
        "matched_documents": matched_documents,
        "regulatory_provenance": build_requirement_provenance(
            requirement,
            fallback_requirement_id=fallback_requirement_id,
            fallback_citation_anchor=fallback_citation_anchor,
        ),
    }
    if details["requirement_id"] in {
        _ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_ID,
        _ECTD_CROSS_APPLICATION_REFERENCE_REQUIREMENT_ID,
    }:
        details["file_reuse_contract"] = build_ectd_file_reuse_contract()
    requirement_id = details["requirement_id"]
    if (
        resolved_citation_anchor == "cn_ectd_technical_specification#sec_3_4"
        or requirement_id.startswith("cn_ectd_validation_standard:req_pdf_")
        or requirement_id == _ECTD_VALIDATION_STANDARD_LONG_PDF_BOOKMARKS_REQUIREMENT_ID
        or requirement_id == _ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_REQUIREMENT_ID
    ):
        details["pdf_presentation_contract"] = build_ectd_pdf_presentation_contract()
    regulation_severity = str(clause_metadata.get("severity") or "").strip()
    if regulation_severity:
        details["regulation_severity"] = regulation_severity
    if extra_details:
        details.update(dict(extra_details))
    return details


def _collect_ectd_submission_metadata_documents(
    material_contract: dict[str, Any],
) -> list[dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    collected: list[dict[str, Any]] = []
    for document in documents:
        ectd_metadata = dict(document.get("ectd_submission_metadata", {}) or {})
        if not ectd_metadata:
            continue
        summary = dict(document.get("summary", {}) or {})
        collected.append(
            {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
                "page_count": int(summary.get("page_count", 0) or 0),
                "outline_index_count": int(summary.get("outline_index_count", 0) or 0),
                "toc_sequence_count": int(summary.get("toc_sequence_count", 0) or 0),
                "ectd_submission_metadata": ectd_metadata,
            }
        )
    return collected


def _is_stf_xml_source_path(source_path: str) -> bool:
    normalized_path = str(source_path or "").strip().replace("\\", "/").lower()
    if not normalized_path:
        return False
    return "/m4/42" in normalized_path or "/m5/53" in normalized_path


def _is_stf_xml_filename(filename: str) -> bool:
    normalized_filename = str(filename or "").strip().lower()
    if not normalized_filename.endswith(".xml"):
        return False
    if normalized_filename in {
        "index.xml",
        "cn-regional.xml",
        "valid-values.xml",
        "depend-apt-rat-sqt.xml",
    }:
        return False
    if normalized_filename.startswith("cv-"):
        return False
    return True


def _collect_ectd_stf_xml_documents(material_contract: dict[str, Any]) -> list[dict[str, Any]]:
    stf_documents: list[dict[str, Any]] = []
    for document in _collect_ectd_submission_metadata_documents(material_contract):
        filename = str(document.get("filename") or "").strip()
        source_path = str(document.get("source_path") or "").strip()
        if not _is_stf_xml_filename(filename) or not _is_stf_xml_source_path(source_path):
            continue
        ectd_metadata = dict(document.get("ectd_submission_metadata") or {})
        element_records = list(ectd_metadata.get("ectd_element_records") or [])
        attribute_records = list(ectd_metadata.get("ectd_attribute_records") or [])
        if not element_records and not attribute_records:
            continue
        stf_documents.append(
            {
                **document,
                "ectd_element_records": element_records,
                "ectd_attribute_records": attribute_records,
            }
        )
    return stf_documents


def _collect_ectd_stf_xml_validation_documents(material_contract: dict[str, Any]) -> list[dict[str, Any]]:
    stf_documents: list[dict[str, Any]] = []
    for document in _collect_ectd_submission_metadata_documents(material_contract):
        filename = str(document.get("filename") or "").strip()
        source_path = str(document.get("source_path") or "").strip()
        if not _is_stf_xml_filename(filename) or not _is_stf_xml_source_path(source_path):
            continue
        ectd_metadata = dict(document.get("ectd_submission_metadata") or {})
        if not ectd_metadata:
            continue
        stf_documents.append(
            {
                **document,
                "ectd_element_records": list(ectd_metadata.get("ectd_element_records") or []),
                "ectd_attribute_records": list(ectd_metadata.get("ectd_attribute_records") or []),
            }
        )
    return stf_documents


def _is_stf_like_xml_document(element_records: list[dict[str, Any]]) -> bool:
    normalized_element_names = {
        _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
        for record in element_records
    }
    return bool(
        "study" in normalized_element_names
        or "studyidentifier" in normalized_element_names
        or "doccontent" in normalized_element_names
        or "filetag" in normalized_element_names
    )


def _collect_ectd_stf_like_xml_documents(material_contract: dict[str, Any]) -> list[dict[str, Any]]:
    stf_documents: list[dict[str, Any]] = []
    for document in _collect_ectd_submission_metadata_documents(material_contract):
        filename = str(document.get("filename") or "").strip()
        if not _is_stf_xml_filename(filename):
            continue
        ectd_metadata = dict(document.get("ectd_submission_metadata") or {})
        element_records = list(ectd_metadata.get("ectd_element_records") or [])
        attribute_records = list(ectd_metadata.get("ectd_attribute_records") or [])
        if not _is_stf_like_xml_document(element_records):
            continue
        stf_documents.append(
            {
                **document,
                "ectd_element_records": element_records,
                "ectd_attribute_records": attribute_records,
            }
        )
    return stf_documents


def _classify_ectd_stf_directory_location(source_path: str) -> tuple[str, str]:
    normalized_path = str(source_path or "").strip().replace("\\", "/").lower()
    if not normalized_path:
        return "unknown", "missing_source_path"
    comparable_path = f"/{normalized_path.lstrip('/')}"

    if "/m4/" in comparable_path:
        if "/m4/42" in comparable_path or "/m4/4-2" in comparable_path:
            return "allowed", "module_4_2"
        return "invalid", "module_4_outside_4_2"

    if "/m5/" in comparable_path:
        if any(marker in comparable_path for marker in _ECTD_STF_DISALLOWED_M5_SECTION_MARKERS):
            return "invalid", "module_5_outside_5_3_1_to_5_3_5"
        if any(marker in comparable_path for marker in _ECTD_STF_ALLOWED_M5_SECTION_MARKERS):
            return "allowed", "module_5_3_1_to_5_3_5"
        return "unknown", "module_5_section_not_classified"

    if any(marker in comparable_path for marker in ("/m1/", "/m2/", "/m3/", "/util/")):
        return "invalid", "outside_module_4_2_or_module_5_3_1_to_5_3_5"

    return "unknown", "module_path_not_classified"


def _build_material_contract_document_lookup(material_contract: dict[str, Any]) -> dict[str, dict[str, Any]]:
    documents = list(material_contract.get("documents", []) or [])
    return {
        str(document.get("document_id") or "").strip(): dict(document)
        for document in documents
        if str(document.get("document_id") or "").strip()
    }


def _load_attachment_12_bundle() -> dict[str, Any]:
    if not _ECTD_ATTACHMENT_12_BUNDLE_PATH.exists():
        return {}
    try:
        payload = json.loads(_ECTD_ATTACHMENT_12_BUNDLE_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if str(payload.get("bundle_id") or "").strip() != "cn_ectd_attachment_1_2":
        return {}
    return payload


def _build_authoritative_cv_lookup() -> tuple[dict[str, set[str]], list[dict[str, Any]]]:
    bundle = _load_attachment_12_bundle()
    lookup: dict[str, set[str]] = {}
    matched_documents: list[dict[str, Any]] = []
    for record in bundle.get("controlled_vocabularies", []) or []:
        vocabulary_name = str(record.get("controlled_vocabulary_name") or "").strip()
        values = {
            str(item or "").strip()
            for item in (record.get("values") or [])
            if str(item or "").strip()
        }
        if not vocabulary_name or not values:
            continue
        lookup[vocabulary_name] = values
        matched_documents.append(
            {
                "document_id": f"authoritative-bundle:{vocabulary_name}",
                "filename": str(record.get("filename") or "").strip(),
                "source_path": str(record.get("source_path") or "").strip(),
                "module_label": "AUTH",
                "authoritative_bundle_source": True,
            }
        )
    return lookup, matched_documents


def _build_authoritative_type_triplets() -> tuple[set[tuple[str, str, str]], list[dict[str, Any]]]:
    bundle = _load_attachment_12_bundle()
    dependency_matrix = dict(bundle.get("dependency_matrix") or {})
    triplets: set[tuple[str, str, str]] = set()
    for row in dependency_matrix.get("rows", []) or []:
        application_type = str((row or {}).get("application_type") or "").strip()
        regulatory_activity_type = str((row or {}).get("regulatory_activity_type") or "").strip()
        sequence_type = str((row or {}).get("sequence_type") or "").strip()
        if application_type and regulatory_activity_type and sequence_type:
            triplets.add((application_type, regulatory_activity_type, sequence_type))
    if not triplets:
        return set(), []
    return triplets, [
        {
            "document_id": "authoritative-bundle:depend-apt-rat-sqt",
            "filename": str(dependency_matrix.get("filename") or "").strip(),
            "source_path": str(dependency_matrix.get("source_path") or "").strip(),
            "module_label": "AUTH",
            "authoritative_bundle_source": True,
        }
    ]


