def _build_authoritative_module1_parent_lookup() -> tuple[dict[str, str], list[dict[str, Any]]]:
    bundle = _load_attachment_14_bundle()
    element_to_section: dict[str, str] = {}
    section_to_element: dict[str, str] = {}
    for record in bundle.get("records", []) or []:
        element = str(record.get("element") or "").strip()
        section_no = str(record.get("section_no") or "").strip()
        if not element or not section_no:
            continue
        element_to_section[element] = section_no
        section_to_element[section_no] = element

    lookup: dict[str, str] = {}
    for element, section_no in element_to_section.items():
        parts = [part for part in section_no.split(".") if part]
        if len(parts) <= 2:
            continue
        for depth in range(len(parts) - 1, 1, -1):
            candidate_section = ".".join(parts[:depth])
            parent_element = section_to_element.get(candidate_section)
            if not parent_element:
                continue
            lookup[element] = parent_element
            break

    if not lookup:
        return {}, []
    return lookup, [
        {
            "document_id": "authoritative-bundle:attachment-1-4",
            "filename": "cn_ectd_attachment_1_4.module1_structure_bundle.json",
            "source_path": str(_ECTD_ATTACHMENT_14_BUNDLE_PATH),
            "module_label": "AUTH",
            "authoritative_bundle_source": True,
        }
    ]


