def _parent_xml_pointer(pointer: str) -> str:
    candidate = str(pointer or "").strip()
    if "/" not in candidate:
        return ""
    return candidate.rsplit("/", 1)[0]


def _collect_ectd_sequence_package_contexts(material_contract: dict[str, Any]) -> list[dict[str, Any]]:
    submission_scope = dict(material_contract.get("submission_scope", {}) or {})
    project_context = dict(submission_scope.get("ectd_project_context", {}) or {})
    document_lookup = _build_material_contract_document_lookup(material_contract)
    contexts: list[dict[str, Any]] = []
    for package in list(project_context.get("sequence_packages", []) or []):
        payload = dict(package or {})
        document_ids = [
            str(document_id or "").strip()
            for document_id in payload.get("document_ids", []) or []
            if str(document_id or "").strip()
        ]
        payload["matched_documents"] = [
            document_lookup[document_id]
            for document_id in document_ids
            if document_id in document_lookup
        ]
        contexts.append(payload)
    return contexts


