def _evaluate_ectd_pdf_hyperlink_action_whitelist_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []

    for document, summary, filename, _source_path in _iter_validation_standard_applicable_pdf_documents(material_contract):
        action_kinds = [
            str(item).strip()
            for item in list(summary.get("pdf_link_action_kinds", []) or [])
            if str(item).strip()
        ]
        action_pages = [
            int(item)
            for item in list(summary.get("pdf_link_action_pages", []) or [])
            if str(item).strip().isdigit()
        ]
        page_records = [
            {
                "page": int(record.get("page", 0) or 0),
                "link_action_kinds": [
                    str(kind).strip()
                    for kind in list(record.get("link_action_kinds", []) or [])
                    if str(kind).strip()
                ],
            }
            for record in list(summary.get("pdf_link_action_page_records", []) or [])
            if isinstance(record, dict)
        ]
        disallowed_action_kinds = [
            kind for kind in action_kinds if kind not in _ECTD_VALIDATION_STANDARD_ALLOWED_PDF_HYPERLINK_ACTION_KINDS
        ]
        matched_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": filename,
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
            "page_count": int(summary.get("page_count", 0) or 0),
            "pdf_link_action_kinds": action_kinds,
            "pdf_link_action_pages": action_pages,
            "pdf_link_action_page_records": page_records,
            "disallowed_link_action_kinds": disallowed_action_kinds,
        }
        applicable_documents.append(matched_document)
        if disallowed_action_kinds:
            failing_documents.append(matched_document)

    if not applicable_documents:
        scope_evidence = _collect_validation_standard_pdf_scope_evidence(material_contract)
        return (
            "na",
            "No confirmed IND/eCTD submission PDF documents required hyperlink-action checks under the validation standard.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_ACTION_WHITELIST_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_ACTION_WHITELIST_CITATION,
                match_strength="submission_scope_not_established" if scope_evidence else "not_applicable",
                matched_documents=[],
                extra_details=(
                    {
                        "applicability_reason": (
                            "Parsed PDF documents were not confirmed as IND/eCTD submission PDFs, so submission "
                            "PDF hyperlink-action hard rules were not applied."
                        ),
                        "scope_evidence": scope_evidence,
                    }
                    if scope_evidence
                    else None
                ),
            ),
        )

    if failing_documents:
        for failing_document in failing_documents:
            page_records = list(failing_document.get("pdf_link_action_page_records", []) or [])
            page_candidates = [
                int(record.get("page", 0) or 0)
                for record in page_records
                if any(
                    str(kind).strip() not in _ECTD_VALIDATION_STANDARD_ALLOWED_PDF_HYPERLINK_ACTION_KINDS
                    for kind in list(record.get("link_action_kinds", []) or [])
                )
            ]
            if not page_candidates:
                page_candidates = [
                    int(page)
                    for page in list(failing_document.get("pdf_link_action_pages", []) or [])
                    if isinstance(page, int) and page > 0
                ]
            if page_candidates:
                failing_document["jump_page"] = sorted(page_candidates)[0]
        return (
            "fail",
            "Detected PDF hyperlink actions outside the validation-standard whitelist (`GoTo`, `GoToR`, `Launch`).",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_ACTION_WHITELIST_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_ACTION_WHITELIST_CITATION,
                match_strength="pdf_disallowed_hyperlink_action_detected",
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated hyperlink action whitelist for {len(applicable_documents)} applicable PDF document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_ACTION_WHITELIST_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_ACTION_WHITELIST_CITATION,
            match_strength="pdf_hyperlink_actions_whitelisted",
            matched_documents=applicable_documents,
        ),
    )


