def _evaluate_ectd_pdf_hyperlink_single_action_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []

    for document, summary, filename, _source_path in _iter_validation_standard_applicable_pdf_documents(material_contract):
        page_count = int(summary.get("page_count", 0) or 0)
        pdf_is_readable = bool(summary.get("pdf_is_readable", True))
        if page_count <= 0 or not pdf_is_readable:
            continue
        multiple_action_count = int(summary.get("pdf_link_multiple_action_count", 0) or 0)
        multiple_action_xrefs = [
            int(item)
            for item in list(summary.get("pdf_link_multiple_action_xrefs", []) or [])
            if str(item).strip().isdigit()
        ]
        matched_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": filename,
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
            "page_count": page_count,
            "pdf_link_multiple_action_evidence_available": bool(
                summary.get("pdf_link_multiple_action_evidence_available")
            ),
            "pdf_link_multiple_action_count": multiple_action_count,
            "pdf_link_multiple_action_xrefs": multiple_action_xrefs,
        }
        if not matched_document["pdf_link_multiple_action_evidence_available"]:
            prerequisite_documents.append(matched_document)
            continue
        applicable_documents.append(matched_document)
        if multiple_action_count > 0:
            failing_documents.append(matched_document)

    if failing_documents:
        return (
            "warn",
            "Detected PDF hyperlink annotations with explicit `/Next` action chains under the validation-standard single-action requirement.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_SINGLE_ACTION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_SINGLE_ACTION_CITATION,
                match_strength="pdf_hyperlink_multiple_actions_detected",
                matched_documents=failing_documents,
                extra_details={"prerequisite_documents": prerequisite_documents},
            ),
        )

    if applicable_documents:
        return (
            "pass",
            f"Validated single-action hyperlink evidence for {len(applicable_documents)} applicable PDF document(s).",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_SINGLE_ACTION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_SINGLE_ACTION_CITATION,
                match_strength="pdf_hyperlink_single_actions",
                matched_documents=applicable_documents,
                extra_details={"prerequisite_documents": prerequisite_documents},
            ),
        )

    return (
        "na",
        "No readable non-exempt PDF documents with hyperlink multiple-action metadata were available for single-action checks.",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_SINGLE_ACTION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_HYPERLINK_SINGLE_ACTION_CITATION,
            match_strength="not_applicable",
            matched_documents=[],
            extra_details={"prerequisite_documents": prerequisite_documents},
        ),
    )


