def _pdf_non_inherit_zoom_details(summary: dict[str, Any], metadata_key: str) -> list[dict[str, Any]]:
    details: list[dict[str, Any]] = []
    for item in list(summary.get(metadata_key, []) or []):
        if not isinstance(item, dict):
            continue
        detail = {
            "xref": int(item.get("xref", 0) or 0),
            "reason": str(item.get("reason") or "").strip(),
            "destination_source": str(item.get("destination_source") or "").strip(),
            "destination": str(item.get("destination") or "").strip(),
            "destination_kind": str(item.get("destination_kind") or "").strip(),
        }
        zoom = str(item.get("zoom") or "").strip()
        if zoom:
            detail["zoom"] = zoom
        details.append(detail)
    return details


