def _normalize_pdf_font_name(font_name: str) -> str:
    normalized = str(font_name or "").strip().lstrip("/")
    if "+" in normalized:
        normalized = normalized.split("+", 1)[1]
    normalized = normalized.replace("#20", " ")
    normalized = re.sub(r"\s+", "", normalized)
    return normalized.lower()


def _is_standard_pdf_font(record: dict[str, Any]) -> bool:
    candidates = [
        str(record.get("base_font") or ""),
        str(record.get("resource_name") or ""),
    ]
    return any(
        _normalize_pdf_font_name(candidate) in _ECTD_VALIDATION_STANDARD_PDF_STANDARD_FONT_NAMES
        for candidate in candidates
        if str(candidate or "").strip()
    )


def _evaluate_ectd_pdf_font_embedding_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []

    for document, summary, filename, _source_path in _iter_validation_standard_applicable_pdf_documents(material_contract):
        page_count = int(summary.get("page_count", 0) or 0)
        pdf_is_readable = bool(summary.get("pdf_is_readable", True))
        if page_count <= 0 or not pdf_is_readable:
            continue

        font_records = [
            record
            for record in list(summary.get("pdf_font_records", []) or [])
            if isinstance(record, dict)
        ]
        matched_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": filename,
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
            "page_count": page_count,
            "pdf_font_count": int(summary.get("pdf_font_count", len(font_records)) or 0),
            "pdf_font_embedding_evidence_available": bool(
                summary.get("pdf_font_embedding_evidence_available")
            ),
            "non_embedded_non_standard_fonts": [],
            "non_embedded_non_standard_font_records": [],
        }
        if not matched_document["pdf_font_embedding_evidence_available"]:
            prerequisite_documents.append(matched_document)
            continue

        non_embedded_non_standard_fonts: list[str] = []
        non_embedded_non_standard_font_records: list[dict[str, Any]] = []
        for record in font_records:
            base_font = str(record.get("base_font") or "").strip()
            resource_name = str(record.get("resource_name") or "").strip()
            font_label = base_font or resource_name
            if not font_label:
                continue
            if bool(record.get("is_embedded")):
                continue
            if _is_standard_pdf_font(record):
                continue
            if font_label not in non_embedded_non_standard_fonts:
                non_embedded_non_standard_fonts.append(font_label)
            page_numbers = sorted(
                {
                    int(page_number)
                    for page_number in list(record.get("page_numbers", []) or [])
                    if str(page_number).strip().isdigit() and int(page_number) > 0
                }
            )
            non_embedded_non_standard_font_records.append(
                {
                    "font_label": font_label,
                    "base_font": base_font,
                    "resource_name": resource_name,
                    "font_type": str(record.get("font_type") or "").strip(),
                    "xref": int(record.get("xref", 0) or 0),
                    "is_embedded": bool(record.get("is_embedded")),
                    "font_file_kind": str(record.get("font_file_kind") or "").strip(),
                    "page_numbers": page_numbers,
                }
            )

        matched_document["non_embedded_non_standard_fonts"] = non_embedded_non_standard_fonts
        matched_document["non_embedded_non_standard_font_records"] = non_embedded_non_standard_font_records
        font_page_candidates = [
            page_number
            for font_record in non_embedded_non_standard_font_records
            for page_number in list(font_record.get("page_numbers", []) or [])
            if isinstance(page_number, int) and page_number > 0
        ]
        if font_page_candidates:
            matched_document["jump_page"] = sorted(font_page_candidates)[0]
        applicable_documents.append(matched_document)
        if non_embedded_non_standard_fonts:
            failing_documents.append(matched_document)

    if failing_documents:
        return (
            "warn",
            "Detected non-exempt PDF documents that use non-standard fonts without embedded font programs.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_FONT_EMBEDDING_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_FONT_EMBEDDING_CITATION,
                match_strength="pdf_non_standard_fonts_not_embedded",
                matched_documents=failing_documents,
                extra_details={"prerequisite_documents": prerequisite_documents},
            ),
        )

    if applicable_documents:
        return (
            "pass",
            f"Validated non-standard font embedding evidence for {len(applicable_documents)} applicable PDF document(s).",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_FONT_EMBEDDING_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_FONT_EMBEDDING_CITATION,
                match_strength="pdf_non_standard_fonts_embedded",
                matched_documents=applicable_documents,
                extra_details={"prerequisite_documents": prerequisite_documents},
            ),
        )

    return (
        "na",
        "No readable non-exempt PDF documents with font embedding metadata were available for font checks.",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_PDF_FONT_EMBEDDING_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_PDF_FONT_EMBEDDING_CITATION,
            match_strength="not_applicable",
            matched_documents=[],
            extra_details={"prerequisite_documents": prerequisite_documents},
        ),
    )


