def _pdf_external_file_link_target_uses_relative_path(target: str) -> bool:
    normalized_target = str(target or "").strip()
    if not normalized_target:
        return False

    decoded_target = unquote(normalized_target).strip().replace("\\", "/")
    if not decoded_target or "://" in decoded_target:
        return False
    if decoded_target.startswith("//"):
        return False
    if re.match(r"^[a-zA-Z]:[^/]", decoded_target):
        return False
    if PurePosixPath(decoded_target).is_absolute():
        return False
    if PureWindowsPath(decoded_target).is_absolute():
        return False
    return True


