def _evaluate_ectd_validation_standard_related_sequence_format_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_REQUIREMENT_ID)
    applicable_documents = _collect_ectd_validation_standard_regional_related_sequence_documents(material_contract)
    extra_details = {"required_related_sequence_pattern": "^[0-9]{4}$"}

    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml envelope metadata was available, so validation-standard related-sequence format checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        sequence_number = str(document.get("ectd_sequence_number") or "").strip()
        related_sequence = str(document.get("ectd_related_sequence") or "").strip()
        related_sequence_issues: list[str] = []
        if not _ECTD_SEQUENCE_NUMBER_PATTERN.match(related_sequence):
            related_sequence_issues.append("invalid_related_sequence_format")
        elif not _ECTD_SEQUENCE_NUMBER_PATTERN.match(sequence_number):
            related_sequence_issues.append("invalid_current_sequence_format")
        elif int(related_sequence) > int(sequence_number):
            related_sequence_issues.append("related_sequence_after_current_sequence")

        if related_sequence_issues:
            failing_documents.append(
                {
                    **document,
                    "related_sequence_issues": related_sequence_issues,
                }
            )

    if failing_documents:
        issue_kinds = {
            issue
            for document in failing_documents
            for issue in list(document.get("related_sequence_issues") or [])
        }
        if issue_kinds == {"invalid_related_sequence_format"}:
            match_strength = "regional_related_sequence_missing_or_invalid"
        elif issue_kinds == {"related_sequence_after_current_sequence"}:
            match_strength = "regional_related_sequence_after_current_sequence"
        elif issue_kinds == {"invalid_current_sequence_format"}:
            match_strength = "regional_current_sequence_missing_or_invalid"
        else:
            match_strength = "regional_related_sequence_invalid_or_after_current"
        return (
            "fail",
            "Detected cn-regional.xml related-sequence values that are not four digits or are after the current sequence-number.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_CITATION,
                match_strength=match_strength,
                matched_documents=failing_documents,
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated related-sequence four-digit format and ordering for {len(applicable_documents)} cn-regional.xml envelope record(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_FORMAT_CITATION,
            match_strength="regional_related_sequence_four_digits_not_after_current",
            matched_documents=applicable_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_validation_standard_related_sequence_non_self_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_REQUIREMENT_ID)
    applicable_documents = _collect_ectd_validation_standard_related_sequence_documents(
        material_contract,
        sequence_type_codes=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_TYPE_CODES,
    )
    extra_details = {
        "non_self_reference_sequence_type_codes": sorted(
            _ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_TYPE_CODES
        ),
    }

    if not applicable_documents:
        return (
            "na",
            "No comparable cn-regional.xml related-sequence metadata for non-initial/non-reformat sequence types was available.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )

    failing_documents = [
        document
        for document in applicable_documents
        if document["ectd_related_sequence"] == document["ectd_sequence_number"]
    ]
    if failing_documents:
        return (
            "fail",
            "Detected non-initial/non-reformat cn-regional.xml sequence types whose related-sequence equals the current sequence-number.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_CITATION,
                match_strength="non_initial_or_reformat_sequence_self_references_related_sequence",
                matched_documents=failing_documents,
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated related-sequence differs from sequence-number for {len(applicable_documents)} non-initial/non-reformat cn-regional.xml envelope record(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_RELATED_SEQUENCE_NON_SELF_CITATION,
            match_strength="non_initial_or_reformat_sequence_references_different_sequence",
            matched_documents=applicable_documents,
            extra_details=extra_details,
        ),
    )


