def _evaluate_append_not_append_leaf_requirement(
    material_contract: dict[str, Any],
    *,
    filename: str,
    match_prefix: str,
    requirement_id: str,
    citation_anchor: str,
    skip_stf_append_leafs: bool,
) -> tuple[str, str, dict[str, Any]]:
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, filename)
    if not lifecycle_documents:
        return (
            "na",
            f"No {filename} documents were available, so append-on-append lifecycle graph checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_lifecycle_graph_operations": [],
                    "invalid_lifecycle_graph_operations": [],
                    "unresolved_lifecycle_graph_prerequisites": [],
                },
            ),
        )

    leafs_by_target, _, sequence_numbers_by_application = _collect_index_lifecycle_graph_edges(lifecycle_documents)
    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_operations: list[dict[str, Any]] = []
    invalid_operations: list[dict[str, Any]] = []
    unresolved_prerequisites: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        summarized_document = _summarize_ectd_lifecycle_document(document)
        document_checked_operations: list[dict[str, Any]] = []
        document_invalid_operations: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            if _normalize_ectd_leaf_operation(record.get("operation")) != "append":
                continue
            if skip_stf_append_leafs and _is_stf_append_leaf(record):
                continue
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            if not modified_file_href:
                continue
            resolved_target_path = _resolve_ectd_lifecycle_target_path(sequence_root, modified_file_href)
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, modified_file_href)
            if not target_key or resolved_target_path is None:
                unresolved_prerequisites.append(
                    _index_lifecycle_graph_prerequisite(
                        document=document,
                        record=record,
                        sequence_root=sequence_root,
                        target_key=target_key,
                        reason="modified_file_target_path_unresolvable",
                    )
                )
                continue
            target_sequence_root = _ectd_known_sequence_root_for_resolved_path(sequence_root, resolved_target_path)
            target_leafs = leafs_by_target.get(target_key, [])
            if target_sequence_root is None or not target_leafs:
                unresolved_prerequisites.append(
                    _index_lifecycle_graph_prerequisite(
                        document=document,
                        record=record,
                        sequence_root=sequence_root,
                        target_key=target_key,
                        reason="target_leaf_lifecycle_metadata_missing",
                    )
                )
                continue
            if not _index_lifecycle_graph_has_complete_prior_sequence_evidence(
                sequence_root=sequence_root,
                target_sequence_root=target_sequence_root,
                sequence_numbers_by_application=sequence_numbers_by_application,
            ):
                unresolved_prerequisites.append(
                    _index_lifecycle_graph_prerequisite(
                        document=document,
                        record=record,
                        sequence_root=sequence_root,
                        target_key=target_key,
                        reason="complete_prior_sequence_lifecycle_evidence_required",
                    )
                )
                continue
            current_operation = _summarize_ectd_lifecycle_graph_operation(
                document,
                record,
                sequence_root=sequence_root,
                target_key=target_key,
            )
            target_append_leafs = [leaf for leaf in target_leafs if leaf.get("operation") == "append"]
            checked_operation = {
                **current_operation,
                "target_append_leaf_count": len(target_append_leafs),
            }
            document_checked_operations.append(checked_operation)
            checked_operations.append(checked_operation)
            if target_append_leafs:
                invalid_operation = {
                    **checked_operation,
                    "target_append_leaf": target_append_leafs[-1],
                    "target_append_leafs": target_append_leafs,
                }
                document_invalid_operations.append(invalid_operation)
                invalid_operations.append(invalid_operation)

        if not document_checked_operations:
            continue
        applicable_documents.append(
            {**summarized_document, "checked_lifecycle_graph_operations": document_checked_operations}
        )
        if document_invalid_operations:
            failing_documents.append(
                {**summarized_document, "invalid_lifecycle_graph_operations": document_invalid_operations}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            f"No {filename} append operations had complete prior lifecycle graph evidence for append-on-append checks.",
            _build_requirement_details(
                {},
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_lifecycle_graph_operations": [],
                    "invalid_lifecycle_graph_operations": [],
                    "unresolved_lifecycle_graph_prerequisites": unresolved_prerequisites,
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            f"Detected {filename} append operations targeting a leaf whose operation is append.",
            _build_requirement_details(
                {},
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength=f"{match_prefix}_append_targets_append_leaf",
                matched_documents=failing_documents,
                extra_details={
                    "checked_lifecycle_graph_operations": checked_operations,
                    "invalid_lifecycle_graph_operations": invalid_operations,
                    "unresolved_lifecycle_graph_prerequisites": unresolved_prerequisites,
                },
            ),
        )

    return (
        "pass",
        f"Validated {len(checked_operations)} {filename} append operation(s) against append-on-append lifecycle evidence.",
        _build_requirement_details(
            {},
            fallback_requirement_id=requirement_id,
            fallback_citation_anchor=citation_anchor,
            match_strength=f"{match_prefix}_append_does_not_target_append_leaf",
            matched_documents=passing_documents,
            extra_details={
                "checked_lifecycle_graph_operations": checked_operations,
                "invalid_lifecycle_graph_operations": [],
                "unresolved_lifecycle_graph_prerequisites": unresolved_prerequisites,
            },
        ),
    )


