def _evaluate_ectd_index_stf_append_latest_leaf_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    if not lifecycle_documents:
        return (
            "na",
            "No index.xml documents were available, so STF append latest-version checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_lifecycle_graph_operations": [],
                    "invalid_lifecycle_graph_operations": [],
                    "unresolved_lifecycle_graph_prerequisites": [],
                },
            ),
        )

    leafs_by_target, operation_edges_by_target, sequence_numbers_by_application = _collect_index_lifecycle_graph_edges(
        lifecycle_documents
    )
    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_operations: list[dict[str, Any]] = []
    invalid_operations: list[dict[str, Any]] = []
    unresolved_prerequisites: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        summarized_document = _summarize_ectd_lifecycle_document(document)
        document_checked_operations: list[dict[str, Any]] = []
        document_invalid_operations: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            if _normalize_ectd_leaf_operation(record.get("operation")) != "append" or not _is_stf_append_leaf(record):
                continue
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            if not modified_file_href:
                continue
            resolved_target_path = _resolve_ectd_lifecycle_target_path(sequence_root, modified_file_href)
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, modified_file_href)
            if not target_key or resolved_target_path is None:
                unresolved_prerequisites.append(
                    _index_lifecycle_graph_prerequisite(
                        document=document,
                        record=record,
                        sequence_root=sequence_root,
                        target_key=target_key,
                        reason="modified_file_target_path_unresolvable",
                    )
                )
                continue
            target_sequence_root = _ectd_known_sequence_root_for_resolved_path(sequence_root, resolved_target_path)
            if target_sequence_root is None or not leafs_by_target.get(target_key):
                unresolved_prerequisites.append(
                    _index_lifecycle_graph_prerequisite(
                        document=document,
                        record=record,
                        sequence_root=sequence_root,
                        target_key=target_key,
                        reason="target_leaf_lifecycle_metadata_missing",
                    )
                )
                continue
            if not _index_lifecycle_graph_has_complete_prior_sequence_evidence(
                sequence_root=sequence_root,
                target_sequence_root=target_sequence_root,
                sequence_numbers_by_application=sequence_numbers_by_application,
            ):
                unresolved_prerequisites.append(
                    _index_lifecycle_graph_prerequisite(
                        document=document,
                        record=record,
                        sequence_root=sequence_root,
                        target_key=target_key,
                        reason="complete_prior_sequence_lifecycle_evidence_required",
                    )
                )
                continue
            current_operation = _summarize_ectd_lifecycle_graph_operation(
                document,
                record,
                sequence_root=sequence_root,
                target_key=target_key,
            )
            current_sequence_number_value = current_operation.get("sequence_number_value")
            prior_latest_changing_operations = [
                edge
                for edge in operation_edges_by_target.get(target_key, [])
                if edge.get("operation") in {"replace", "append"}
                and isinstance(edge.get("sequence_number_value"), int)
                and isinstance(current_sequence_number_value, int)
                and edge["sequence_number_value"] < current_sequence_number_value
            ]
            checked_operation = {
                **current_operation,
                "prior_latest_changing_operation_count": len(prior_latest_changing_operations),
            }
            document_checked_operations.append(checked_operation)
            checked_operations.append(checked_operation)
            if prior_latest_changing_operations:
                invalid_operation = {
                    **checked_operation,
                    "latest_prior_operation": prior_latest_changing_operations[-1],
                    "prior_latest_changing_operations": prior_latest_changing_operations,
                }
                document_invalid_operations.append(invalid_operation)
                invalid_operations.append(invalid_operation)

        if not document_checked_operations:
            continue
        applicable_documents.append(
            {**summarized_document, "checked_lifecycle_graph_operations": document_checked_operations}
        )
        if document_invalid_operations:
            failing_documents.append(
                {**summarized_document, "invalid_lifecycle_graph_operations": document_invalid_operations}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No STF index.xml append operations had complete prior lifecycle graph evidence for latest-version checks.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_lifecycle_graph_operations": [],
                    "invalid_lifecycle_graph_operations": [],
                    "unresolved_lifecycle_graph_prerequisites": unresolved_prerequisites,
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected STF index.xml append operations whose modified-file target is not the latest known lifecycle leaf.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_CITATION,
                match_strength="index_stf_append_targets_non_latest_leaf",
                matched_documents=failing_documents,
                extra_details={
                    "checked_lifecycle_graph_operations": checked_operations,
                    "invalid_lifecycle_graph_operations": invalid_operations,
                    "unresolved_lifecycle_graph_prerequisites": unresolved_prerequisites,
                },
            ),
        )

    return (
        "pass",
        f"Validated {len(checked_operations)} STF index.xml append operation(s) against latest-version lifecycle evidence.",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_STF_APPEND_LATEST_LEAF_CITATION,
            match_strength="index_stf_append_targets_latest_leaf",
            matched_documents=passing_documents,
            extra_details={
                "checked_lifecycle_graph_operations": checked_operations,
                "invalid_lifecycle_graph_operations": [],
                "unresolved_lifecycle_graph_prerequisites": unresolved_prerequisites,
            },
        ),
    )


def _evaluate_ectd_stf_append_modified_file_target_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_REQUIREMENT_ID)
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    if not lifecycle_documents:
        return (
            "na",
            "No index.xml documents were available, so STF append modified-file target checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_stf_append_modified_file_targets": [],
                    "invalid_stf_append_modified_file_targets": [],
                    "stf_append_modified_file_prerequisites": [],
                },
            ),
        )

    leafs_by_target, _, _ = _collect_index_lifecycle_graph_edges(lifecycle_documents)
    applicable_documents: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_targets: list[dict[str, Any]] = []
    invalid_targets: list[dict[str, Any]] = []
    prerequisite_targets: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        summarized_document = _summarize_ectd_lifecycle_document(document)
        document_checked_targets: list[dict[str, Any]] = []
        document_invalid_targets: list[dict[str, Any]] = []
        document_prerequisites: list[dict[str, Any]] = []

        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            if _normalize_ectd_leaf_operation(record.get("operation")) != "append":
                continue
            if not _is_stf_append_leaf(record):
                continue

            modified_file_href = str(record.get("modified_file_href") or "").strip()
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, modified_file_href)
            base_target = {
                **_summarize_ectd_lifecycle_graph_operation(
                    document,
                    record,
                    sequence_root=sequence_root,
                    target_key=target_key,
                ),
                "current_href": str(record.get("href") or "").strip(),
                "modified_file_href": modified_file_href,
            }
            if not modified_file_href or not target_key:
                prerequisite = {**base_target, "prerequisite": "modified_file_target_path_unresolvable"}
                document_prerequisites.append(prerequisite)
                prerequisite_targets.append(prerequisite)
                continue

            target_leafs = leafs_by_target.get(target_key, [])
            if not target_leafs:
                prerequisite = {**base_target, "prerequisite": "target_leaf_lifecycle_metadata_missing"}
                document_prerequisites.append(prerequisite)
                prerequisite_targets.append(prerequisite)
                continue

            target_leaf_hrefs = _dedupe_preserve_order_strings(
                str(leaf.get("href") or "").strip()
                for leaf in target_leafs
                if str(leaf.get("href") or "").strip()
            )
            target_stf_leafs = [leaf for leaf in target_leafs if bool(leaf.get("is_stf_append_leaf"))]
            target_non_stf_leafs = [leaf for leaf in target_leafs if not bool(leaf.get("is_stf_append_leaf"))]
            checked_target = {
                **base_target,
                "target_leaf_hrefs": target_leaf_hrefs,
                "target_stf_leaf_count": len(target_stf_leafs),
                "target_non_stf_leaf_count": len(target_non_stf_leafs),
            }

            if target_stf_leafs and target_non_stf_leafs:
                prerequisite = {
                    **checked_target,
                    "prerequisite": "target_leaf_stf_classification_ambiguous",
                }
                document_prerequisites.append(prerequisite)
                prerequisite_targets.append(prerequisite)
                continue

            document_checked_targets.append(checked_target)
            checked_targets.append(checked_target)
            if not target_stf_leafs:
                document_invalid_targets.append(checked_target)
                invalid_targets.append(checked_target)

        if not document_checked_targets and not document_prerequisites:
            continue
        applicable_documents.append(
            {
                **summarized_document,
                "checked_stf_append_modified_file_targets": document_checked_targets,
                "stf_append_modified_file_prerequisites": document_prerequisites,
            }
        )
        if document_invalid_targets:
            warning_documents.append(
                {**summarized_document, "invalid_stf_append_modified_file_targets": document_invalid_targets}
            )
        elif document_checked_targets:
            passing_documents.append(summarized_document)

    extra_details = {
        "checked_stf_append_modified_file_targets": checked_targets,
        "invalid_stf_append_modified_file_targets": invalid_targets,
        "stf_append_modified_file_prerequisites": prerequisite_targets,
    }

    if warning_documents:
        return (
            "warn",
            "Detected STF append operations whose modified-file target is not classified as another STF leaf.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_CITATION,
                match_strength="stf_append_modified_file_not_stf_leaf",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )

    if checked_targets:
        return (
            "pass",
            f"Validated {len(checked_targets)} STF append modified-file target(s) as STF leafs.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_CITATION,
                match_strength="stf_append_modified_file_targets_stf_leaf",
                matched_documents=passing_documents,
                extra_details=extra_details,
            ),
        )

    return (
        "na",
        "No STF append modified-file targets could be classified from local index.xml lifecycle evidence.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_APPEND_MODIFIED_FILE_CITATION,
            match_strength="stf_append_modified_file_target_prerequisite_missing",
            matched_documents=applicable_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_replace_append_checksum_difference_for_filename(
    material_contract: dict[str, Any],
    *,
    filename: str,
    requirement_id: str,
    citation_anchor: str,
    scope_label: str,
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(requirement_id)
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, filename)
    if not lifecycle_documents:
        return (
            "na",
            f"No {filename} documents were available, so replace/append checksum-difference checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "compared_modified_file_checksum_pairs": [],
                    "reused_modified_file_checksums": [],
                },
            ),
        )

    prior_leafs_by_target: dict[str, dict[str, Any]] = {}
    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            href = str(record.get("href") or "").strip()
            checksum = _normalize_ectd_checksum_value(record.get("checksum"))
            if not href or not checksum:
                continue
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, href)
            if not target_key or target_key in prior_leafs_by_target:
                continue
            prior_leafs_by_target[target_key] = {
                **_summarize_ectd_lifecycle_leaf(record),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": source_path,
                "resolved_href_path": target_key,
            }

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    compared_pairs: list[dict[str, Any]] = []
    reused_modified_file_checksums: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        document_compared_pairs: list[dict[str, Any]] = []
        document_reused_pairs: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            operation = _normalize_ectd_leaf_operation(record.get("operation"))
            if operation not in {"replace", "append"}:
                continue
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            current_checksum = _normalize_ectd_checksum_value(record.get("checksum"))
            if not modified_file_href or not current_checksum:
                continue
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, modified_file_href)
            prior_leaf = prior_leafs_by_target.get(target_key)
            if prior_leaf is None:
                continue
            modified_file_checksum = _normalize_ectd_checksum_value(prior_leaf.get("checksum"))
            if not modified_file_checksum:
                continue
            pair = {
                **_summarize_ectd_lifecycle_leaf(record),
                "current_href": str(record.get("href") or "").strip(),
                "current_checksum_type": _normalize_ectd_checksum_type(record.get("checksum_type")),
                "current_checksum": current_checksum,
                "modified_file_href": modified_file_href,
                "modified_file_checksum_type": _normalize_ectd_checksum_type(prior_leaf.get("checksum_type")),
                "modified_file_checksum": modified_file_checksum,
                "modified_leaf_href": str(prior_leaf.get("href") or "").strip(),
                "resolved_modified_file_path": target_key,
            }
            document_compared_pairs.append(pair)
            compared_pairs.append(pair)
            if current_checksum == modified_file_checksum:
                document_reused_pairs.append(pair)
                reused_modified_file_checksums.append(pair)

        if not document_compared_pairs:
            continue

        summarized_document = _summarize_ectd_lifecycle_document(document)
        applicable_documents.append(
            {**summarized_document, "compared_modified_file_checksum_pairs": document_compared_pairs}
        )
        if document_reused_pairs:
            failing_documents.append(
                {**summarized_document, "reused_modified_file_checksums": document_reused_pairs}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            f"No {filename} replace/append leaf records could be matched to prior modified-file checksums.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "compared_modified_file_checksum_pairs": [],
                    "reused_modified_file_checksums": [],
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            f"Detected {filename} replace/append leafs whose checksum is identical to the modified-file leaf checksum.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength=f"{scope_label}_replace_append_checksum_reuses_modified_file",
                matched_documents=failing_documents,
                extra_details={
                    "compared_modified_file_checksum_pairs": compared_pairs,
                    "reused_modified_file_checksums": reused_modified_file_checksums,
                },
            ),
        )

    return (
        "pass",
        f"Validated checksum difference for {len(compared_pairs)} {filename} replace/append modified-file pair(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=requirement_id,
            fallback_citation_anchor=citation_anchor,
            match_strength=f"{scope_label}_replace_append_checksum_differs_from_modified_file",
            matched_documents=passing_documents,
            extra_details={
                "compared_modified_file_checksum_pairs": compared_pairs,
                "reused_modified_file_checksums": [],
            },
        ),
    )


