def _evaluate_ectd_file_single_operation_for_filename(
    material_contract: dict[str, Any],
    *,
    filename: str,
    requirement_id: str,
    citation_anchor: str,
    scope_label: str,
) -> tuple[str, str, dict[str, Any]]:
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, filename)
    if not lifecycle_documents:
        return (
            "na",
            f"No {filename} documents were available, so lifecycle file-operation checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        target_groups: dict[str, dict[str, Any]] = {}
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            operation = _normalize_ectd_leaf_operation(record.get("operation"))
            if operation not in {"new", "replace", "delete", "append"}:
                continue
            target_href = _ectd_lifecycle_operation_target_href(record)
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, target_href)
            if not target_key:
                continue
            group = target_groups.setdefault(
                target_key,
                {
                    "target_href": target_href,
                    "resolved_target_path": target_key,
                    "operations": set(),
                    "leafs": [],
                },
            )
            group["operations"].add(operation)
            group["leafs"].append(_summarize_ectd_lifecycle_leaf(record))

        if not target_groups:
            continue

        summarized_document = _summarize_ectd_lifecycle_document(document)
        applicable_documents.append(summarized_document)
        conflicting_file_operations = [
            {
                "target_href": str(group.get("target_href") or "").strip(),
                "resolved_target_path": str(group.get("resolved_target_path") or "").strip(),
                "operations": sorted(group.get("operations") or []),
                "leafs": list(group.get("leafs") or []),
            }
            for group in target_groups.values()
            if len(group.get("operations") or []) > 1
        ]
        if conflicting_file_operations:
            failing_documents.append(
                {**summarized_document, "conflicting_file_operations": conflicting_file_operations}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            f"No {filename} lifecycle leaf records with resolvable operation targets were available.",
            _build_requirement_details(
                {},
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        return (
            "fail",
            f"Detected {filename} lifecycle file targets that correspond to multiple operations within the same sequence.",
            _build_requirement_details(
                {},
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength=f"{scope_label}_lifecycle_file_multiple_operations",
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated one operation per {filename} lifecycle file target for {len(passing_documents)} document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=requirement_id,
            fallback_citation_anchor=citation_anchor,
            match_strength=f"{scope_label}_lifecycle_file_single_operation_per_sequence",
            matched_documents=passing_documents,
        ),
    )


