def _evaluate_ectd_initial_sequence_index_leafs_new_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    sequence_packages = _collect_ectd_sequence_package_contexts(material_contract)
    if not sequence_packages:
        return (
            "na",
            "No eCTD sequence-package context was available, so initial-sequence index lifecycle checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_packages: list[dict[str, Any]] = []
    failing_packages: list[dict[str, Any]] = []
    passing_packages: list[dict[str, Any]] = []
    for package in sequence_packages:
        sequence_number = str(package.get("sequence_number") or "").strip()
        if sequence_number != "0000":
            continue
        index_document = next(
            (
                document
                for document in list(package.get("matched_documents") or [])
                if str(document.get("filename") or "").strip().lower() == "index.xml"
            ),
            None,
        )
        if index_document is None:
            continue
        lifecycle_records = [
            dict(record or {})
            for record in list(((index_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_lifecycle_records")) or [])
        ]
        if not lifecycle_records:
            continue

        package_record = {
            "document_id": str(package.get("sequence_package_id") or "").strip(),
            "filename": str(index_document.get("filename") or "").strip(),
            "source_path": str(index_document.get("source_path") or "").strip(),
            "module_label": str(((index_document.get("classification") or {}).get("module_label")) or "").strip(),
            "sequence_number": sequence_number,
            "sequence_type": str(package.get("sequence_type") or "").strip(),
        }
        applicable_packages.append(package_record)

        non_new_initial_leafs = [
            _summarize_ectd_lifecycle_leaf(record)
            for record in lifecycle_records
            if _normalize_ectd_leaf_operation(record.get("operation")) != "new"
        ]
        if non_new_initial_leafs:
            failing_packages.append({**package_record, "non_new_initial_leafs": non_new_initial_leafs})
            continue
        passing_packages.append(package_record)

    if not applicable_packages:
        return (
            "na",
            "No initial-sequence index.xml lifecycle records were available, so initial-sequence lifecycle checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_packages:
        return (
            "fail",
            "Detected initial-sequence index leaf records whose operation is not 'new'.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_CITATION,
                match_strength="initial_sequence_index_leaf_not_new",
                matched_documents=failing_packages,
            ),
        )

    return (
        "pass",
        f"Validated operation=new for {len(passing_packages)} initial-sequence index.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_INDEX_LEAFS_NEW_CITATION,
            match_strength="initial_sequence_index_leafs_new",
            matched_documents=passing_packages,
        ),
    )


def _resolve_ectd_lifecycle_target_path(sequence_root: Path | None, href: Any) -> Path | None:
    normalized_href = unquote(str(href or "").strip()).replace("\\", "/")
    if not normalized_href or "://" in normalized_href or sequence_root is None:
        return None
    try:
        return (sequence_root / normalized_href).resolve()
    except OSError:
        return None


def _ectd_known_sequence_root_for_resolved_path(sequence_root: Path | None, resolved_path: Path | None) -> Path | None:
    if sequence_root is None or resolved_path is None:
        return None
    application_root = _find_ectd_application_root_for_path(sequence_root)
    if application_root is None:
        return sequence_root if sequence_root.exists() else None
    try:
        relative_parts = resolved_path.relative_to(application_root).parts
    except ValueError:
        return None
    if not relative_parts:
        return None
    candidate_sequence_root = application_root / relative_parts[0]
    return candidate_sequence_root if candidate_sequence_root.exists() else None


def _evaluate_ectd_index_modified_file_target_exists_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    if not lifecycle_documents:
        return (
            "na",
            "No index.xml documents were available, so modified-file target-existence checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_modified_file_targets": [],
                    "unresolved_modified_file_target_prerequisites": [],
                },
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_targets: list[dict[str, Any]] = []
    unresolved_prerequisites: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        document_checked_targets: list[dict[str, Any]] = []
        missing_modified_file_targets: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            if not modified_file_href:
                continue
            resolved_path = _resolve_ectd_lifecycle_target_path(sequence_root, modified_file_href)
            known_sequence_root = _ectd_known_sequence_root_for_resolved_path(sequence_root, resolved_path)
            target_detail = {
                **_summarize_ectd_lifecycle_leaf(record),
                "modified_file_href": modified_file_href,
                "resolved_modified_file_path": str(resolved_path) if resolved_path is not None else "",
                "known_sequence_root": str(known_sequence_root) if known_sequence_root is not None else "",
            }
            if resolved_path is None or known_sequence_root is None:
                unresolved_prerequisites.append(
                    {
                        **target_detail,
                        "prerequisite": "target_sequence_package_not_available",
                    }
                )
                continue
            document_checked_targets.append(target_detail)
            checked_targets.append(target_detail)
            if not resolved_path.exists():
                missing_modified_file_targets.append(target_detail)

        if not document_checked_targets:
            continue

        summarized_document = _summarize_ectd_lifecycle_document(document)
        applicable_documents.append({**summarized_document, "checked_modified_file_targets": document_checked_targets})
        if missing_modified_file_targets:
            failing_documents.append(
                {**summarized_document, "missing_modified_file_targets": missing_modified_file_targets}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No index.xml modified-file targets could be checked against an available sequence package.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_modified_file_targets": [],
                    "unresolved_modified_file_target_prerequisites": unresolved_prerequisites,
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected index.xml modified-file targets that do not exist in an available sequence package.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_CITATION,
                match_strength="index_modified_file_target_missing",
                matched_documents=failing_documents,
                extra_details={
                    "checked_modified_file_targets": checked_targets,
                    "unresolved_modified_file_target_prerequisites": unresolved_prerequisites,
                },
            ),
        )

    return (
        "pass",
        f"Validated {len(checked_targets)} index.xml modified-file target(s) against available sequence packages.",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_MODIFIED_FILE_TARGET_EXISTS_CITATION,
            match_strength="index_modified_file_targets_exist",
            matched_documents=passing_documents,
            extra_details={
                "checked_modified_file_targets": checked_targets,
                "unresolved_modified_file_target_prerequisites": unresolved_prerequisites,
            },
        ),
    )


def _ectd_relative_forward_slash_path_issues(path_value: Any) -> list[str]:
    raw_path = str(path_value or "").strip()
    if not raw_path:
        return []
    decoded_path = unquote(raw_path)
    issues: list[str] = []
    if "\\" in decoded_path:
        issues.append("backslash")
    if "://" in decoded_path or re.match(r"^[A-Za-z][A-Za-z0-9+.-]*:", decoded_path):
        issues.append("absolute_path")
    else:
        try:
            if PurePosixPath(decoded_path).is_absolute() or PureWindowsPath(decoded_path).is_absolute():
                issues.append("absolute_path")
        except (TypeError, ValueError):
            issues.append("invalid_path")
    return issues


def _evaluate_ectd_index_leaf_path_relative_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    if not lifecycle_documents:
        return (
            "na",
            "No index.xml documents were available, so leaf path-reference checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        checked_path_count = 0
        invalid_leaf_paths: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            for path_kind, path_value in (
                ("href", record.get("href")),
                ("modified-file", record.get("modified_file_href")),
            ):
                raw_path = str(path_value or "").strip()
                if not raw_path:
                    continue
                checked_path_count += 1
                issues = _ectd_relative_forward_slash_path_issues(raw_path)
                if issues:
                    invalid_leaf_paths.append(
                        {
                            **_summarize_ectd_lifecycle_leaf(record),
                            "path_kind": path_kind,
                            "path_value": raw_path,
                            "issues": issues,
                        }
                    )

        if checked_path_count <= 0:
            continue

        summarized_document = _summarize_ectd_lifecycle_document(document)
        applicable_documents.append({**summarized_document, "checked_path_count": checked_path_count})
        if invalid_leaf_paths:
            failing_documents.append({**summarized_document, "invalid_leaf_paths": invalid_leaf_paths})
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No index.xml href or modified-file path values were available, so path-reference checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected index.xml leaf path references that are absolute or use backslashes.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_CITATION,
                match_strength="index_leaf_path_not_relative_forward_slash",
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated relative forward-slash index.xml leaf path references for {len(passing_documents)} document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_PATH_RELATIVE_CITATION,
            match_strength="index_leaf_paths_relative_forward_slash",
            matched_documents=passing_documents,
        ),
    )


def _evaluate_ectd_regional_file_single_operation_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    cn_regional_documents = _collect_cn_regional_lifecycle_documents(material_contract)
    if not cn_regional_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so regional file-operation checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for document in cn_regional_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        target_groups: dict[str, dict[str, Any]] = {}
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            operation = _normalize_ectd_leaf_operation(record.get("operation"))
            if operation not in {"new", "replace", "delete", "append"}:
                continue
            target_href = _ectd_lifecycle_operation_target_href(record)
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, target_href)
            if not target_key:
                continue
            group = target_groups.setdefault(
                target_key,
                {
                    "target_href": target_href,
                    "resolved_target_path": target_key,
                    "operations": set(),
                    "leafs": [],
                },
            )
            group["operations"].add(operation)
            group["leafs"].append(_summarize_ectd_lifecycle_leaf(record))

        if not target_groups:
            continue

        summarized_document = _summarize_ectd_lifecycle_document(document)
        applicable_documents.append(summarized_document)
        conflicting_file_operations = [
            {
                "target_href": str(group.get("target_href") or "").strip(),
                "resolved_target_path": str(group.get("resolved_target_path") or "").strip(),
                "operations": sorted(group.get("operations") or []),
                "leafs": list(group.get("leafs") or []),
            }
            for group in target_groups.values()
            if len(group.get("operations") or []) > 1
        ]
        if conflicting_file_operations:
            failing_documents.append(
                {**summarized_document, "conflicting_file_operations": conflicting_file_operations}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No regional lifecycle leaf records with resolvable operation targets were available, so file-operation checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected regional lifecycle file targets that correspond to multiple operations within the same sequence.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_CITATION,
                match_strength="regional_lifecycle_file_multiple_operations",
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated one operation per regional lifecycle file target for {len(passing_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_FILE_SINGLE_OPERATION_CITATION,
            match_strength="regional_lifecycle_file_single_operation_per_sequence",
            matched_documents=passing_documents,
        ),
    )


