def _evaluate_ectd_initial_sequence_regional_leafs_new_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    sequence_packages = _collect_ectd_sequence_package_contexts(material_contract)
    if not sequence_packages:
        return (
            "na",
            "No eCTD sequence-package context was available, so initial-sequence regional lifecycle checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_packages: list[dict[str, Any]] = []
    failing_packages: list[dict[str, Any]] = []
    passing_packages: list[dict[str, Any]] = []
    for package in sequence_packages:
        sequence_number = str(package.get("sequence_number") or "").strip()
        if sequence_number != "0000":
            continue
        cn_regional_document = next(
            (
                document
                for document in list(package.get("matched_documents") or [])
                if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
            ),
            None,
        )
        if cn_regional_document is None:
            continue
        lifecycle_records = [
            dict(record or {})
            for record in list(((cn_regional_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_lifecycle_records")) or [])
        ]
        if not lifecycle_records:
            continue

        package_record = {
            "document_id": str(package.get("sequence_package_id") or "").strip(),
            "filename": str(cn_regional_document.get("filename") or "").strip(),
            "source_path": str(cn_regional_document.get("source_path") or "").strip(),
            "module_label": str(((cn_regional_document.get("classification") or {}).get("module_label")) or "").strip(),
            "sequence_number": sequence_number,
            "sequence_type": str(package.get("sequence_type") or "").strip(),
        }
        applicable_packages.append(package_record)

        non_new_initial_leafs = [
            _summarize_ectd_lifecycle_leaf(record)
            for record in lifecycle_records
            if _normalize_ectd_leaf_operation(record.get("operation")) != "new"
        ]
        if non_new_initial_leafs:
            failing_packages.append({**package_record, "non_new_initial_leafs": non_new_initial_leafs})
            continue
        passing_packages.append(package_record)

    if not applicable_packages:
        return (
            "na",
            "No initial-sequence cn-regional.xml lifecycle records were available, so initial-sequence lifecycle checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_packages:
        return (
            "fail",
            "Detected initial-sequence regional leaf records whose operation is not 'new'.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_CITATION,
                match_strength="initial_sequence_regional_leaf_not_new",
                matched_documents=failing_packages,
            ),
        )

    return (
        "pass",
        f"Validated operation=new for {len(passing_packages)} initial-sequence cn-regional.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_SEQUENCE_REGIONAL_LEAFS_NEW_CITATION,
            match_strength="initial_sequence_regional_leafs_new",
            matched_documents=passing_packages,
        ),
    )


def _evaluate_ectd_index_delete_leaf_title_match_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    index_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    if not index_documents:
        return (
            "na",
            "No index.xml documents were available, so delete leaf title lifecycle checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    prior_leaf_titles_by_target: dict[str, dict[str, str]] = {}
    for document in index_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            href = str(record.get("href") or "").strip()
            title = str(record.get("leaf_title") or "").strip()
            if not href or not title:
                continue
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, href)
            if not target_key or target_key in prior_leaf_titles_by_target:
                continue
            prior_leaf_titles_by_target[target_key] = {
                "modified_leaf_title": title,
                "modified_leaf_href": href,
                "modified_leaf_pointer": str(record.get("leaf_pointer") or "").strip(),
            }

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for document in index_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        comparable_delete_leafs: list[dict[str, Any]] = []
        delete_leaf_title_mismatches: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            if _normalize_ectd_leaf_operation(record.get("operation")) != "delete":
                continue
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            delete_leaf_title = str(record.get("leaf_title") or "").strip()
            if not modified_file_href or not delete_leaf_title:
                continue
            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, modified_file_href)
            prior_leaf = prior_leaf_titles_by_target.get(target_key)
            if prior_leaf is None:
                continue
            comparable_delete_leafs.append(_summarize_ectd_lifecycle_leaf(record))
            modified_leaf_title = str(prior_leaf.get("modified_leaf_title") or "").strip()
            if delete_leaf_title != modified_leaf_title:
                delete_leaf_title_mismatches.append(
                    {
                        **_summarize_ectd_lifecycle_leaf(record),
                        "delete_leaf_title": delete_leaf_title,
                        "modified_leaf_title": modified_leaf_title,
                        "modified_leaf_href": str(prior_leaf.get("modified_leaf_href") or "").strip(),
                        "resolved_modified_file_path": target_key,
                    }
                )

        if not comparable_delete_leafs:
            continue

        summarized_document = _summarize_ectd_lifecycle_document(document)
        applicable_documents.append({**summarized_document, "comparable_delete_leafs": comparable_delete_leafs})
        if delete_leaf_title_mismatches:
            failing_documents.append(
                {**summarized_document, "delete_leaf_title_mismatches": delete_leaf_title_mismatches}
            )
            continue
        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No index delete leaf records could be matched to a prior modified-file leaf title, so delete-title checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected index delete leaf titles that differ from the titles of the leafs being deleted.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_CITATION,
                match_strength="index_delete_leaf_title_mismatch",
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated delete leaf title continuity for {len(passing_documents)} index.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_DELETE_LEAF_TITLE_MATCH_CITATION,
            match_strength="index_delete_leaf_title_matches_modified_file",
            matched_documents=passing_documents,
        ),
    )


