def _evaluate_ectd_regional_cn_element_leaf_descendant_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID)
    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so regional cn-element leaf-descendant checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_cn_elements": [],
                    "violating_cn_elements": [],
                },
            ),
        )

    checked_cn_elements: list[dict[str, Any]] = []
    violating_cn_elements: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        if not nodes:
            continue

        node_lookup = {
            str(node.get("pointer") or "").strip(): dict(node)
            for node in nodes
            if str(node.get("pointer") or "").strip()
        }
        content_pointers = {
            str(node.get("pointer") or "").strip()
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "cn-content"
            and str(node.get("pointer") or "").strip()
        }
        if not content_pointers:
            continue

        def _is_under_cn_content(pointer: str) -> bool:
            candidate = str(pointer or "").strip()
            while candidate:
                if candidate in content_pointers:
                    return True
                candidate = _parent_xml_pointer(candidate)
            return False

        leaf_pointers = [
            str(node.get("pointer") or "").strip()
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "leaf"
            and str(node.get("pointer") or "").strip()
        ]
        document_checked_elements: list[dict[str, Any]] = []
        document_violations: list[dict[str, Any]] = []
        for node in nodes:
            element = str(node.get("local_tag") or "").strip()
            pointer = str(node.get("pointer") or "").strip()
            if not element or not pointer:
                continue
            if not _ECTD_REGIONAL_CN_CONTENT_ELEMENT_PATTERN.match(element):
                continue
            if not _is_under_cn_content(pointer):
                continue

            parent_pointer = _parent_xml_pointer(pointer)
            parent_element = str((node_lookup.get(parent_pointer) or {}).get("local_tag") or "").strip()
            leaf_descendant_count = sum(
                1
                for leaf_pointer in leaf_pointers
                if leaf_pointer.startswith(f"{pointer}/")
            )
            checked_row = {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "element": element,
                "pointer": pointer,
                "parent_element": parent_element,
                "leaf_descendant_count": leaf_descendant_count,
            }
            document_checked_elements.append(checked_row)
            checked_cn_elements.append(checked_row)
            if leaf_descendant_count == 0:
                document_violations.append(checked_row)
                violating_cn_elements.append(checked_row)

        if document_violations:
            failing_documents.append(
                {
                    **document,
                    "checked_cn_elements": document_checked_elements,
                    "violating_cn_elements": document_violations,
                }
            )

    matched_documents = applicable_documents
    if not checked_cn_elements:
        return (
            "na",
            "No cn-content module elements with names beginning cn-[number] were found, so regional cn-element leaf-descendant checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_CITATION,
                match_strength="not_applicable",
                matched_documents=matched_documents,
                extra_details={
                    "checked_cn_elements": [],
                    "violating_cn_elements": [],
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected cn-regional.xml cn-content elements whose subtree does not contain any leaf element.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_CITATION,
                match_strength="regional_cn_element_missing_leaf_descendant",
                matched_documents=failing_documents,
                extra_details={
                    "checked_cn_elements": checked_cn_elements,
                    "violating_cn_elements": violating_cn_elements,
                },
            ),
        )

    return (
        "pass",
        f"Validated leaf-descendant presence for {len(checked_cn_elements)} cn-regional.xml cn-content element(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_CN_ELEMENT_LEAF_DESCENDANT_CITATION,
            match_strength="regional_cn_elements_have_leaf_descendants",
            matched_documents=matched_documents,
            extra_details={
                "checked_cn_elements": checked_cn_elements,
                "violating_cn_elements": [],
            },
        ),
    )


def _evaluate_ectd_module1_single_file_element_leaf_count_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(
        _ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_REQUIREMENT_ID
    )
    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so module-1 single-file element leaf-count checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "advisory_element_names": sorted(_ECTD_MODULE1_SINGLE_FILE_ELEMENT_NAMES),
                    "checked_module1_elements": [],
                    "violating_module1_elements": [],
                },
            ),
        )

    checked_module1_elements: list[dict[str, Any]] = []
    violating_module1_elements: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        if not nodes:
            continue

        node_lookup = {
            str(node.get("pointer") or "").strip(): dict(node)
            for node in nodes
            if str(node.get("pointer") or "").strip()
        }
        content_pointers = {
            str(node.get("pointer") or "").strip()
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "cn-content"
            and str(node.get("pointer") or "").strip()
        }
        if not content_pointers:
            continue

        def _is_under_cn_content(pointer: str) -> bool:
            candidate = str(pointer or "").strip()
            while candidate:
                if candidate in content_pointers:
                    return True
                candidate = _parent_xml_pointer(candidate)
            return False

        leaf_pointers = [
            str(node.get("pointer") or "").strip()
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "leaf"
            and str(node.get("pointer") or "").strip()
        ]
        document_checked_elements: list[dict[str, Any]] = []
        document_violations: list[dict[str, Any]] = []
        for node in nodes:
            element = str(node.get("local_tag") or "").strip()
            pointer = str(node.get("pointer") or "").strip()
            if not element or not pointer:
                continue
            if element not in _ECTD_MODULE1_SINGLE_FILE_ELEMENT_NAMES:
                continue
            if not _is_under_cn_content(pointer):
                continue

            parent_pointer = _parent_xml_pointer(pointer)
            parent_element = str((node_lookup.get(parent_pointer) or {}).get("local_tag") or "").strip()
            leaf_descendant_count = sum(
                1
                for leaf_pointer in leaf_pointers
                if leaf_pointer.startswith(f"{pointer}/")
            )
            checked_row = {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "element": element,
                "pointer": pointer,
                "parent_element": parent_element,
                "leaf_descendant_count": leaf_descendant_count,
            }
            document_checked_elements.append(checked_row)
            checked_module1_elements.append(checked_row)
            if leaf_descendant_count > 1:
                document_violations.append(checked_row)
                violating_module1_elements.append(checked_row)

        if document_violations:
            warning_documents.append(
                {
                    **document,
                    "checked_module1_elements": document_checked_elements,
                    "violating_module1_elements": document_violations,
                }
            )

    matched_documents = applicable_documents
    if not checked_module1_elements:
        return (
            "na",
            "No applicable module-1 elements from validation-standard 4.3.9 were found, so single-file element leaf-count checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_CITATION,
                match_strength="not_applicable",
                matched_documents=matched_documents,
                extra_details={
                    "advisory_element_names": sorted(_ECTD_MODULE1_SINGLE_FILE_ELEMENT_NAMES),
                    "checked_module1_elements": [],
                    "violating_module1_elements": [],
                },
            ),
        )

    if warning_documents:
        return (
            "warn",
            "Detected module-1 elements that contain more than one descendant leaf; validation standard 4.3.9 recommends submitting no more than one PDF under these elements.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_CITATION,
                match_strength="module1_single_file_element_multiple_leafs",
                matched_documents=warning_documents,
                extra_details={
                    "advisory_element_names": sorted(_ECTD_MODULE1_SINGLE_FILE_ELEMENT_NAMES),
                    "checked_module1_elements": checked_module1_elements,
                    "violating_module1_elements": violating_module1_elements,
                },
            ),
        )

    return (
        "pass",
        f"Validated advisory leaf-count limit for {len(checked_module1_elements)} module-1 element(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_MODULE1_SINGLE_FILE_ELEMENT_LEAF_COUNT_CITATION,
            match_strength="module1_single_file_elements_leaf_count_within_advisory_limit",
            matched_documents=matched_documents,
            extra_details={
                "advisory_element_names": sorted(_ECTD_MODULE1_SINGLE_FILE_ELEMENT_NAMES),
                "checked_module1_elements": checked_module1_elements,
                "violating_module1_elements": [],
            },
        ),
    )


def _evaluate_ectd_index_m_element_leaf_descendant_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID)
    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "index.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No index.xml documents were available, so index m-element leaf-descendant checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "checked_m_elements": [],
                    "violating_m_elements": [],
                },
            ),
        )

    checked_m_elements: list[dict[str, Any]] = []
    violating_m_elements: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        if not nodes:
            continue

        node_lookup = {
            str(node.get("pointer") or "").strip(): dict(node)
            for node in nodes
            if str(node.get("pointer") or "").strip()
        }
        leaf_pointers = [
            str(node.get("pointer") or "").strip()
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "leaf"
            and str(node.get("pointer") or "").strip()
        ]
        document_checked_elements: list[dict[str, Any]] = []
        document_violations: list[dict[str, Any]] = []
        for node in nodes:
            element = str(node.get("local_tag") or "").strip()
            pointer = str(node.get("pointer") or "").strip()
            if not element or not pointer:
                continue
            if not _ECTD_INDEX_M_ELEMENT_PATTERN.match(element):
                continue

            parent_pointer = _parent_xml_pointer(pointer)
            parent_element = str((node_lookup.get(parent_pointer) or {}).get("local_tag") or "").strip()
            leaf_descendant_count = sum(
                1
                for leaf_pointer in leaf_pointers
                if leaf_pointer.startswith(f"{pointer}/")
            )
            checked_row = {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "element": element,
                "pointer": pointer,
                "parent_element": parent_element,
                "leaf_descendant_count": leaf_descendant_count,
            }
            document_checked_elements.append(checked_row)
            checked_m_elements.append(checked_row)
            if leaf_descendant_count == 0:
                document_violations.append(checked_row)
                violating_m_elements.append(checked_row)

        if document_violations:
            failing_documents.append(
                {
                    **document,
                    "checked_m_elements": document_checked_elements,
                    "violating_m_elements": document_violations,
                }
            )

    matched_documents = applicable_documents
    if not checked_m_elements:
        return (
            "na",
            "No index.xml elements with names beginning m[number] were found, so index m-element leaf-descendant checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_CITATION,
                match_strength="not_applicable",
                matched_documents=matched_documents,
                extra_details={
                    "checked_m_elements": [],
                    "violating_m_elements": [],
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected index.xml m-elements whose subtree does not contain any leaf element.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_CITATION,
                match_strength="index_m_element_missing_leaf_descendant",
                matched_documents=failing_documents,
                extra_details={
                    "checked_m_elements": checked_m_elements,
                    "violating_m_elements": violating_m_elements,
                },
            ),
        )

    return (
        "pass",
        f"Validated leaf-descendant presence for {len(checked_m_elements)} index.xml m-element(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M_ELEMENT_LEAF_DESCENDANT_CITATION,
            match_strength="index_m_elements_have_leaf_descendants",
            matched_documents=matched_documents,
            extra_details={
                "checked_m_elements": checked_m_elements,
                "violating_m_elements": [],
            },
        ),
    )


def _evaluate_ectd_index_m1_element_present_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_REQUIREMENT_ID)
    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "index.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No index.xml documents were available, so m1 administrative element presence checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={"m1_administrative_elements": []},
            ),
        )

    matched_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    m1_elements: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        document_m1_elements = [
            {
                "document_id": document["document_id"],
                "filename": document["filename"],
                "source_path": document["source_path"],
                "element": str(node.get("local_tag") or "").strip(),
                "pointer": str(node.get("pointer") or "").strip(),
            }
            for node in nodes
            if str(node.get("local_tag") or "").strip().lower()
            == "m1-administrative-information-and-prescribing-information"
        ]
        m1_elements.extend(document_m1_elements)
        document_row = {**document, "m1_administrative_elements": document_m1_elements}
        matched_documents.append(document_row)
        if not document_m1_elements:
            failing_documents.append(document_row)

    if failing_documents:
        return (
            "fail",
            "Detected index.xml documents missing the required m1 administrative-information element.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_CITATION,
                match_strength="index_m1_administrative_element_missing",
                matched_documents=failing_documents,
                extra_details={"m1_administrative_elements": m1_elements},
            ),
        )

    return (
        "pass",
        f"Validated required m1 administrative-information element presence for {len(matched_documents)} index.xml document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_M1_ELEMENT_PRESENT_CITATION,
            match_strength="index_m1_administrative_element_present",
            matched_documents=matched_documents,
            extra_details={"m1_administrative_elements": m1_elements},
        ),
    )


def _ectd_lifecycle_position_attributes_signature(record: dict[str, Any]) -> tuple[tuple[str, str, str], ...]:
    signature: list[tuple[str, str, str]] = []
    for attribute in list(record.get("position_attributes") or []):
        normalized_name = str(attribute.get("normalized_attribute_name") or "").strip().lower()
        if normalized_name not in _ECTD_INDEX_POSITION_ATTRIBUTE_NAMES:
            continue
        signature.append(
            (
                str(attribute.get("element_local_tag") or "").strip(),
                normalized_name,
                str(attribute.get("normalized_value") or "").strip(),
            )
        )
    return tuple(sorted(signature))


def _build_ectd_index_relocation_warning(
    *,
    current_record: dict[str, Any],
    target_record: dict[str, Any],
    target_key: str,
    issue: str,
) -> dict[str, Any]:
    return {
        "issue": issue,
        "operation": _normalize_ectd_leaf_operation(current_record.get("operation")),
        "current_href": str(current_record.get("href") or "").strip(),
        "modified_file_href": str(current_record.get("modified_file_href") or "").strip(),
        "resolved_modified_file_path": target_key,
        "current_parent_local_tag": str(current_record.get("parent_local_tag") or "").strip(),
        "target_parent_local_tag": str(target_record.get("parent_local_tag") or "").strip(),
        "current_position_element_path": list(current_record.get("position_element_path") or []),
        "target_position_element_path": list(target_record.get("position_element_path") or []),
        "current_position_attributes": list(current_record.get("position_attributes") or []),
        "target_position_attributes": list(target_record.get("position_attributes") or []),
        "target_href": str(target_record.get("href") or "").strip(),
        "target_sequence_number": str(target_record.get("sequence_number") or "").strip(),
    }


def _evaluate_ectd_index_lifecycle_file_relocation_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_REQUIREMENT_ID)
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    empty_details = {
        "checked_index_lifecycle_relocation_pairs": [],
        "index_lifecycle_relocation_warnings": [],
        "index_lifecycle_relocation_prerequisites": [],
    }
    if not lifecycle_documents:
        return (
            "na",
            "No index.xml lifecycle metadata was available, so file-position relocation checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=empty_details,
            ),
        )

    leafs_by_target, _, _ = _collect_index_lifecycle_graph_edges(lifecycle_documents)
    checked_pairs: list[dict[str, Any]] = []
    relocation_warnings: list[dict[str, Any]] = []
    prerequisites: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        document_checked: list[dict[str, Any]] = []
        document_warnings: list[dict[str, Any]] = []
        document_prerequisites: list[dict[str, Any]] = []

        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            operation = _normalize_ectd_leaf_operation(record.get("operation"))
            if operation not in {"replace", "delete", "append"}:
                continue
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            if not modified_file_href:
                continue

            target_key = _normalize_ectd_lifecycle_reference_path(sequence_root, modified_file_href)
            if not target_key:
                prerequisite = _index_lifecycle_graph_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    target_key=target_key,
                    reason="modified_file_target_path_unresolvable",
                )
                document_prerequisites.append(prerequisite)
                prerequisites.append(prerequisite)
                continue

            target_records = [
                target_record
                for target_record in list(leafs_by_target.get(target_key) or [])
                if str(target_record.get("leaf_pointer") or "").strip()
                != str(record.get("leaf_pointer") or "").strip()
                or str(target_record.get("source_path") or "").strip() != source_path
            ]
            if not target_records:
                prerequisite = _index_lifecycle_graph_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    target_key=target_key,
                    reason="modified_file_target_leaf_context_unavailable",
                )
                document_prerequisites.append(prerequisite)
                prerequisites.append(prerequisite)
                continue
            if len(target_records) > 1:
                prerequisite = _index_lifecycle_graph_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    target_key=target_key,
                    reason="modified_file_target_leaf_context_not_unique",
                )
                prerequisite["candidate_target_count"] = len(target_records)
                document_prerequisites.append(prerequisite)
                prerequisites.append(prerequisite)
                continue

            target_record = target_records[0]
            current_parent = str(record.get("parent_local_tag") or "").strip()
            target_parent = str(target_record.get("parent_local_tag") or "").strip()
            if not current_parent or not target_parent:
                prerequisite = _index_lifecycle_graph_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    target_key=target_key,
                    reason="position_parent_context_unavailable",
                )
                document_prerequisites.append(prerequisite)
                prerequisites.append(prerequisite)
                continue

            current_position_path = tuple(str(item or "").strip() for item in list(record.get("position_element_path") or []) if str(item or "").strip())
            target_position_path = tuple(str(item or "").strip() for item in list(target_record.get("position_element_path") or []) if str(item or "").strip())
            current_attributes = _ectd_lifecycle_position_attributes_signature(record)
            target_attributes = _ectd_lifecycle_position_attributes_signature(target_record)
            checked_pair = {
                **_summarize_ectd_lifecycle_graph_operation(
                    document,
                    record,
                    sequence_root=sequence_root,
                    target_key=target_key,
                ),
                "target_href": str(target_record.get("href") or "").strip(),
                "target_parent_local_tag": target_parent,
                "target_sequence_number": str(target_record.get("sequence_number") or "").strip(),
                "current_position_element_path": list(current_position_path),
                "target_position_element_path": list(target_position_path),
                "current_position_attributes": list(record.get("position_attributes") or []),
                "target_position_attributes": list(target_record.get("position_attributes") or []),
            }
            checked_pairs.append(checked_pair)
            document_checked.append(checked_pair)

            issue = ""
            if current_parent != target_parent:
                issue = "parent_section_changed"
            elif current_position_path and target_position_path and current_position_path != target_position_path:
                issue = "ctd_element_path_changed"
            elif current_attributes and target_attributes and current_attributes != target_attributes:
                issue = "ectd_position_attribute_changed"

            if issue:
                warning = _build_ectd_index_relocation_warning(
                    current_record=record,
                    target_record=target_record,
                    target_key=target_key,
                    issue=issue,
                )
                relocation_warnings.append(warning)
                document_warnings.append(warning)

        if document_checked or document_warnings or document_prerequisites:
            summarized_document = {
                **_summarize_ectd_lifecycle_document(document),
                "checked_index_lifecycle_relocation_pairs": document_checked,
                "index_lifecycle_relocation_warnings": document_warnings,
                "index_lifecycle_relocation_prerequisites": document_prerequisites,
            }
            if document_warnings:
                warning_documents.append(summarized_document)
            elif document_prerequisites:
                prerequisite_documents.append(summarized_document)
            elif document_checked:
                passing_documents.append(summarized_document)

    extra_details = {
        "checked_index_lifecycle_relocation_pairs": checked_pairs,
        "index_lifecycle_relocation_warnings": relocation_warnings,
        "index_lifecycle_relocation_prerequisites": prerequisites,
    }

    if relocation_warnings:
        return (
            "warn",
            "Detected index.xml lifecycle operations that appear to relocate a modified file to a different CTD/eCTD position; review the replacement target and current leaf location.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_CITATION,
                match_strength="index_lifecycle_leaf_position_mismatch",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )

    if prerequisites:
        return (
            "warn",
            "Index.xml lifecycle operations require human review because modified-file target position context could not be determined from available package evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_CITATION,
                match_strength="index_lifecycle_relocation_requires_human_review",
                matched_documents=prerequisite_documents,
                extra_details=extra_details,
            ),
        )

    if not checked_pairs:
        return (
            "na",
            "No index.xml replace/delete/append lifecycle operations with modified-file targets were available for file-position relocation review.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated unchanged CTD/eCTD position context for {len(checked_pairs)} index.xml lifecycle modified-file pair(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_FILE_RELOCATION_CITATION,
            match_strength="index_lifecycle_leaf_position_preserved",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_content_reference_boundary_requirement(
    material_contract: dict[str, Any],
    *,
    filename: str,
    requirement_id: str,
    citation_anchor: str,
    detail_prefix: str,
    document_label: str,
    fail_match_strength: str,
    pass_match_strength: str,
    unresolved_match_strength: str,
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(requirement_id)
    checked_detail_key = f"checked_{detail_prefix}_content_references"
    invalid_detail_key = f"invalid_{detail_prefix}_content_references"
    unresolved_detail_key = f"unresolved_{detail_prefix}_content_references"
    metadata_documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in metadata_documents
        if str(document.get("filename") or "").strip().lower() == filename
        and list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
    ]
    if not applicable_documents:
        return (
            "na",
            f"No {document_label} leaf reference metadata was available, so {detail_prefix} content-reference boundary checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    checked_detail_key: [],
                    invalid_detail_key: [],
                    unresolved_detail_key: [],
                },
            ),
        )

    checked_references: list[dict[str, str]] = []
    invalid_references: list[dict[str, str]] = []
    unresolved_references: list[dict[str, str]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in applicable_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        if sequence_root is None:
            unresolved_references.append(
                {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": source_path,
                    "issue": "sequence_root_unavailable",
                }
            )
            continue
        current_application_root = sequence_root.parent
        current_application_name = str(current_application_root.name or "").strip()
        current_sequence_number = str(sequence_root.name or "").strip()
        document_checked: list[dict[str, str]] = []
        document_invalid: list[dict[str, str]] = []
        document_unresolved: list[dict[str, str]] = []

        for record in document["ectd_leaf_records"]:
            for reference_kind, reference_value in (
                ("href", record.get("href")),
                ("modified-file", record.get("modified_file_href")),
            ):
                reference = str(reference_value or "").strip()
                if not reference:
                    continue
                try:
                    resolved_path = (sequence_root / reference).resolve()
                except OSError:
                    row = {
                        "reference_kind": reference_kind,
                        "reference": reference,
                        "issue": "reference_path_unresolvable",
                    }
                    document_unresolved.append(row)
                    unresolved_references.append(row)
                    continue

                target_application_root = _find_ectd_application_root_for_path(resolved_path)
                target_sequence_root = _find_ectd_sequence_root_for_file_path(str(resolved_path))
                target_application_name = str((target_application_root.name if target_application_root else "") or "").strip()
                target_sequence_number = str((target_sequence_root.name if target_sequence_root else "") or "").strip()
                row = {
                    "reference_kind": reference_kind,
                    "reference": reference,
                    "source_application_number": current_application_name,
                    "source_sequence_number": current_sequence_number,
                    "target_application_root_name": target_application_name,
                    "target_sequence_number": target_sequence_number,
                }
                document_checked.append(row)
                checked_references.append(row)

                if (
                    target_application_name
                    and current_application_name
                    and target_application_name != current_application_name
                ):
                    violation = {**row, "issue": "cross_application_reference"}
                    document_invalid.append(violation)
                    invalid_references.append(violation)
                    continue

                if (
                    target_sequence_number
                    and current_sequence_number
                    and _ECTD_SEQUENCE_NUMBER_PATTERN.match(target_sequence_number)
                    and _ECTD_SEQUENCE_NUMBER_PATTERN.match(current_sequence_number)
                    and int(target_sequence_number) > int(current_sequence_number)
                ):
                    violation = {**row, "issue": "non_prior_sequence_reference"}
                    document_invalid.append(violation)
                    invalid_references.append(violation)

        normalized_document = {
            **document,
            checked_detail_key: document_checked,
            invalid_detail_key: document_invalid,
            unresolved_detail_key: document_unresolved,
        }
        if document_invalid:
            failing_documents.append(normalized_document)
        elif document_checked:
            passing_documents.append(normalized_document)

    extra_details = {
        checked_detail_key: checked_references,
        invalid_detail_key: invalid_references,
        unresolved_detail_key: unresolved_references,
    }

    if failing_documents:
        return (
            "fail",
            f"Detected {document_label} content references that target another application or a later sequence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength=fail_match_strength,
                matched_documents=failing_documents,
                extra_details=extra_details,
            ),
        )

    if not passing_documents:
        return (
            "na",
            f"No {document_label} content references could be resolved to sequence/application context, so content-reference boundary checks require prerequisite package evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength=unresolved_match_strength,
                matched_documents=[],
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated same-application current/prior-sequence boundaries for {len(checked_references)} {document_label} content reference(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=requirement_id,
            fallback_citation_anchor=citation_anchor,
            match_strength=pass_match_strength,
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_metadata_lifecycle_coupling_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    """
    评估eCTD元数据生命周期耦合规则

    规则: 当section的元数据属性变更时，其下的leaf文件内容必须完整更新

    Args:
        material_contract: 物料契约，包含当前序列和前序列信息

    Returns:
        (status, requirement_id, details) 元组
    """
    from core.ectd_metadata_lifecycle_validator import validate_metadata_lifecycle_coupling
    from core.ectd_metadata_extractor import extract_sequence_metadata_index

    # 获取当前序列路径
    current_sequence_path = material_contract.get("sequence_root_path")
    if not current_sequence_path:
        return (
            "na",
            _ECTD_METADATA_LIFECYCLE_COUPLING_REQUIREMENT_ID,
            {"reason": "sequence_root_path_not_available"}
        )

    # 获取前序列路径
    previous_sequence_path = material_contract.get("previous_sequence_root_path")
    if not previous_sequence_path:
        # 初始序列（0000），无前序列可比对
        return (
            "na",
            _ECTD_METADATA_LIFECYCLE_COUPLING_REQUIREMENT_ID,
            {"reason": "initial_sequence_no_previous_sequence"}
        )

    try:
        # 提取元数据索引
        previous_index = extract_sequence_metadata_index(previous_sequence_path)
        current_index = extract_sequence_metadata_index(current_sequence_path)

        # 执行验证
        validation_result = validate_metadata_lifecycle_coupling(previous_index, current_index)

        # 转换为RuleEvaluationResult格式
        if validation_result.is_fully_compliant():
            return (
                "pass",
                _ECTD_METADATA_LIFECYCLE_COUPLING_REQUIREMENT_ID,
                {
                    "total_sections_analyzed": validation_result.total_sections_analyzed,
                    "compliant_sections": validation_result.compliant_sections,
                    "sequence_transition": f"{validation_result.previous_sequence_number} → {validation_result.sequence_number}"
                }
            )
        else:
            # 构建违规详情
            violation_details = [
                {
                    "section_identifier": v.section_identifier,
                    "section_path": v.section_path,
                    "changed_attributes": v.changed_attributes,
                    "violation_type": v.violation_type,
                    "violation_message": v.violation_message,
                    "leaf_ids": v.leaf_ids
                }
                for v in validation_result.violations
            ]

            return (
                "fail",
                _ECTD_METADATA_LIFECYCLE_COUPLING_REQUIREMENT_ID,
                {
                    "total_sections_analyzed": validation_result.total_sections_analyzed,
                    "violation_count": validation_result.violation_count,
                    "compliant_sections": validation_result.compliant_sections,
                    "sequence_transition": f"{validation_result.previous_sequence_number} → {validation_result.sequence_number}",
                    "violations": violation_details
                }
            )

    except Exception as e:
        # 处理任何异常情况
        return (
            "na",
            _ECTD_METADATA_LIFECYCLE_COUPLING_REQUIREMENT_ID,
            {
                "reason": "evaluation_error",
                "error": str(e)
            }
        )


