def _evaluate_ectd_cover_letter_leaf_operation_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    cn_regional_documents = [
        document
        for document in documents
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
    ]
    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []

    for document in cn_regional_documents:
        cover_letter_records = [
            dict(record or {})
            for record in ((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
            if str((record or {}).get("parent_local_tag") or "").strip() == "cn-1-0"
        ]
        if not cover_letter_records:
            continue
        applicable_documents.append(document)

        invalid_cover_letter_leaf_operations: list[dict[str, Any]] = []
        missing_cover_letter_leaf_operations: list[dict[str, Any]] = []
        for record in cover_letter_records:
            href = str(record.get("href") or "").strip()
            operation_present = bool(record.get("operation_present"))
            operation = str(record.get("operation") or "").strip()
            if not operation_present or not operation:
                missing_cover_letter_leaf_operations.append(
                    {
                        "href": href,
                        "operation": operation,
                    }
                )
                continue
            if operation != "new":
                invalid_cover_letter_leaf_operations.append(
                    {
                        "href": href,
                        "operation": operation,
                    }
                )

        if missing_cover_letter_leaf_operations or invalid_cover_letter_leaf_operations:
            failing_documents.append(
                {
                    "document_id": str(document.get("document_id") or "").strip(),
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "module_label": str(document.get("module_label") or "").strip(),
                    "missing_cover_letter_leaf_operations": missing_cover_letter_leaf_operations,
                    "invalid_cover_letter_leaf_operations": invalid_cover_letter_leaf_operations,
                }
            )

    if not applicable_documents:
        return (
            "na",
            "No cover-letter leaf records were available, so cover-letter operation checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_COVER_LETTER_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_COVER_LETTER_OPERATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        first_failure = failing_documents[0]
        match_strength = (
            "missing_cover_letter_leaf_operation"
            if first_failure.get("missing_cover_letter_leaf_operations")
            else "invalid_cover_letter_leaf_operation"
        )
        return (
            "fail",
            "Detected cover-letter leaf records whose operation attribute is not 'new'.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_COVER_LETTER_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_COVER_LETTER_OPERATION_CITATION,
                match_strength=match_strength,
                matched_documents=failing_documents,
            ),
        )

    passing_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(document.get("module_label") or "").strip(),
        }
        for document in applicable_documents
    ]
    return (
        "pass",
        f"Validated cover-letter leaf operation=new for {len(passing_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_COVER_LETTER_OPERATION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_COVER_LETTER_OPERATION_CITATION,
            match_strength="cover_letter_leaf_operation_new",
            matched_documents=passing_documents,
        ),
    )


def _evaluate_ectd_initial_submission_application_form_leaf_operation_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    sequence_packages = _collect_ectd_sequence_package_contexts(material_contract)
    if not sequence_packages:
        return (
            "na",
            "No eCTD sequence-package context was available, so initial-submission application-form operation checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_packages: list[dict[str, Any]] = []
    failing_packages: list[dict[str, Any]] = []
    passing_packages: list[dict[str, Any]] = []

    for package in sequence_packages:
        matched_documents = list(package.get("matched_documents") or [])
        cn_regional_document = next(
            (
                document
                for document in matched_documents
                if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
            ),
            None,
        )
        if cn_regional_document is None:
            continue

        sequence_type = str(package.get("sequence_type") or "").strip().lower()
        application_form_records = [
            dict(record or {})
            for record in ((cn_regional_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
            if str((record or {}).get("parent_local_tag") or "").strip() == "cn-1-2"
        ]
        if not application_form_records or sequence_type != "cnsqt1":
            continue

        package_record = {
            "document_id": str(package.get("sequence_package_id") or "").strip(),
            "filename": str(cn_regional_document.get("filename") or "").strip(),
            "source_path": str(cn_regional_document.get("source_path") or "").strip(),
            "module_label": str(((cn_regional_document.get("classification") or {}).get("module_label")) or "").strip(),
            "sequence_number": str(package.get("sequence_number") or "").strip(),
            "sequence_type": str(package.get("sequence_type") or "").strip(),
        }
        applicable_packages.append(package_record)

        invalid_application_form_leaf_operations: list[dict[str, Any]] = []
        missing_application_form_leaf_operations: list[dict[str, Any]] = []
        for record in application_form_records:
            href = str(record.get("href") or "").strip()
            operation_present = bool(record.get("operation_present"))
            operation = str(record.get("operation") or "").strip()
            if not operation_present or not operation:
                missing_application_form_leaf_operations.append(
                    {
                        "href": href,
                        "operation": operation,
                    }
                )
                continue
            if operation != "new":
                invalid_application_form_leaf_operations.append(
                    {
                        "href": href,
                        "operation": operation,
                    }
                )

        if missing_application_form_leaf_operations or invalid_application_form_leaf_operations:
            failing_packages.append(
                {
                    **package_record,
                    "missing_application_form_leaf_operations": missing_application_form_leaf_operations,
                    "invalid_application_form_leaf_operations": invalid_application_form_leaf_operations,
                }
            )
            continue

        passing_packages.append(package_record)

    if not applicable_packages:
        return (
            "na",
            "No initial-submission application-form leaf records were available, so application-form operation checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_packages:
        first_failure = failing_packages[0]
        match_strength = (
            "missing_initial_submission_application_form_leaf_operation"
            if first_failure.get("missing_application_form_leaf_operations")
            else "invalid_initial_submission_application_form_leaf_operation"
        )
        return (
            "fail",
            "Detected initial-submission application-form leaf records whose operation attribute is not 'new'.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_CITATION,
                match_strength=match_strength,
                matched_documents=failing_packages,
            ),
        )

    return (
        "pass",
        f"Validated application-form leaf operation=new for {len(passing_packages)} initial-submission sequence package(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INITIAL_APPLICATION_FORM_OPERATION_CITATION,
            match_strength="initial_submission_application_form_leaf_operation_new",
            matched_documents=passing_packages,
        ),
    )


def _evaluate_ectd_regional_no_node_extension_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    cn_regional_documents = [
        document
        for document in documents
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
    ]
    if not cn_regional_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so regional node-extension checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_NO_NODE_EXTENSION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_NO_NODE_EXTENSION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for document in cn_regional_documents:
        node_extension_records = [
            {
                "extension_title": str(record.get("extension_title") or "").strip(),
                "parent_local_tag": str(record.get("parent_local_tag") or "").strip(),
                "parent_pointer": str(record.get("parent_pointer") or "").strip(),
                "leaf_titles": [
                    str(item or "").strip()
                    for item in list(record.get("leaf_titles") or [])
                    if str(item or "").strip()
                ],
                "leaf_hrefs": [
                    str(item or "").strip()
                    for item in list(record.get("leaf_hrefs") or [])
                    if str(item or "").strip()
                ],
            }
            for record in list(((document.get("ectd_submission_metadata") or {}).get("ectd_node_extension_records")) or [])
        ]
        summarized_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(document.get("module_label") or "").strip(),
        }
        if node_extension_records:
            failing_documents.append(
                {
                    **summarized_document,
                    "node_extension_records": node_extension_records,
                }
            )
            continue
        passing_documents.append(summarized_document)

    if failing_documents:
        return (
            "fail",
            "Detected node-extension usage inside cn-regional.xml, which is forbidden by the regional backbone validation standard.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_NO_NODE_EXTENSION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_NO_NODE_EXTENSION_CITATION,
                match_strength="regional_backbone_contains_node_extension",
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated absence of node-extension usage for {len(passing_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_NO_NODE_EXTENSION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_NO_NODE_EXTENSION_CITATION,
            match_strength="regional_backbone_has_no_node_extension",
            matched_documents=passing_documents,
        ),
    )


def _evaluate_ectd_index_leaf_title_non_empty_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    index_documents = [
        document
        for document in documents
        if str(document.get("filename") or "").strip().lower() == "index.xml"
    ]
    if not index_documents:
        return (
            "na",
            "No index.xml documents were available, so index leaf-title checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in index_documents:
        leaf_title_records = [
            dict(record or {})
            for record in list(((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_title_records")) or [])
        ]
        if not leaf_title_records:
            continue

        summarized_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(document.get("module_label") or "").strip(),
        }
        applicable_documents.append(summarized_document)

        missing_leaf_titles: list[dict[str, Any]] = []
        blank_leaf_titles: list[dict[str, Any]] = []
        for record in leaf_title_records:
            normalized_title = str(record.get("normalized_title_text") or "").strip()
            summarized_leaf = {
                "href": str(record.get("href") or "").strip(),
                "title_present": bool(record.get("title_present")),
                "raw_title_text": str(record.get("raw_title_text") or ""),
                "normalized_title_text": normalized_title,
                "leaf_pointer": str(record.get("leaf_pointer") or "").strip(),
                "parent_pointer": str(record.get("parent_pointer") or "").strip(),
                "parent_local_tag": str(record.get("parent_local_tag") or "").strip(),
            }
            if not bool(record.get("title_present")):
                missing_leaf_titles.append(summarized_leaf)
                continue
            if not normalized_title:
                blank_leaf_titles.append(summarized_leaf)

        if missing_leaf_titles or blank_leaf_titles:
            failing_documents.append(
                {
                    **summarized_document,
                    "missing_leaf_titles": missing_leaf_titles,
                    "blank_leaf_titles": blank_leaf_titles,
                }
            )
            continue

        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No index leaf-title records were available, so index leaf-title checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        first_failure = failing_documents[0]
        match_strength = (
            "missing_index_leaf_title"
            if first_failure.get("missing_leaf_titles") and not first_failure.get("blank_leaf_titles")
            else "blank_index_leaf_title"
        )
        return (
            "fail",
            "Detected index leaf records whose title is missing or empty.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_CITATION,
                match_strength=match_strength,
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated non-empty index leaf titles for {len(passing_documents)} index.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_INDEX_LEAF_TITLE_NON_EMPTY_CITATION,
            match_strength="index_leaf_titles_non_empty",
            matched_documents=passing_documents,
        ),
    )


def _evaluate_ectd_regional_leaf_title_non_empty_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    cn_regional_documents = [
        document
        for document in documents
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
    ]
    if not cn_regional_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so regional leaf-title checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in cn_regional_documents:
        leaf_title_records = [
            dict(record or {})
            for record in list(((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_title_records")) or [])
        ]
        if not leaf_title_records:
            continue

        summarized_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(document.get("module_label") or "").strip(),
        }
        applicable_documents.append(summarized_document)

        missing_leaf_titles: list[dict[str, Any]] = []
        blank_leaf_titles: list[dict[str, Any]] = []
        for record in leaf_title_records:
            normalized_title = str(record.get("normalized_title_text") or "").strip()
            summarized_leaf = {
                "href": str(record.get("href") or "").strip(),
                "title_present": bool(record.get("title_present")),
                "raw_title_text": str(record.get("raw_title_text") or ""),
                "normalized_title_text": normalized_title,
                "leaf_pointer": str(record.get("leaf_pointer") or "").strip(),
                "parent_pointer": str(record.get("parent_pointer") or "").strip(),
                "parent_local_tag": str(record.get("parent_local_tag") or "").strip(),
            }
            if not bool(record.get("title_present")):
                missing_leaf_titles.append(summarized_leaf)
                continue
            if not normalized_title:
                blank_leaf_titles.append(summarized_leaf)

        if missing_leaf_titles or blank_leaf_titles:
            failing_documents.append(
                {
                    **summarized_document,
                    "missing_leaf_titles": missing_leaf_titles,
                    "blank_leaf_titles": blank_leaf_titles,
                }
            )
            continue

        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No regional leaf-title records were available, so regional leaf-title checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if failing_documents:
        first_failure = failing_documents[0]
        match_strength = (
            "missing_regional_leaf_title"
            if first_failure.get("missing_leaf_titles") and not first_failure.get("blank_leaf_titles")
            else "blank_regional_leaf_title"
        )
        return (
            "fail",
            "Detected regional leaf records whose title is missing or empty.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_CITATION,
                match_strength=match_strength,
                matched_documents=failing_documents,
            ),
        )

    return (
        "pass",
        f"Validated non-empty regional leaf titles for {len(passing_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_NON_EMPTY_CITATION,
            match_strength="regional_leaf_titles_non_empty",
            matched_documents=passing_documents,
        ),
    )


def _evaluate_ectd_regional_leaf_title_edge_whitespace_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    cn_regional_documents = [
        document
        for document in documents
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
    ]
    if not cn_regional_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so regional leaf-title whitespace checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    applicable_documents: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in cn_regional_documents:
        leaf_title_records = [
            dict(record or {})
            for record in list(((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_title_records")) or [])
        ]
        if not leaf_title_records:
            continue

        summarized_document = {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(document.get("module_label") or "").strip(),
        }

        checkable_leaf_count = 0
        edge_whitespace_leaf_titles: list[dict[str, Any]] = []
        for record in leaf_title_records:
            if not bool(record.get("title_present")):
                continue
            raw_title = str(record.get("raw_title_text") or "")
            trimmed_title = raw_title.strip()
            if not trimmed_title:
                continue

            checkable_leaf_count += 1
            has_leading_whitespace = raw_title[:1].isspace()
            has_trailing_whitespace = raw_title[-1:].isspace()
            if not has_leading_whitespace and not has_trailing_whitespace:
                continue

            edge_whitespace_leaf_titles.append(
                {
                    "href": str(record.get("href") or "").strip(),
                    "title_present": True,
                    "raw_title_text": raw_title,
                    "normalized_title_text": trimmed_title,
                    "has_leading_whitespace": has_leading_whitespace,
                    "has_trailing_whitespace": has_trailing_whitespace,
                    "leaf_pointer": str(record.get("leaf_pointer") or "").strip(),
                    "parent_pointer": str(record.get("parent_pointer") or "").strip(),
                    "parent_local_tag": str(record.get("parent_local_tag") or "").strip(),
                }
            )

        if checkable_leaf_count <= 0:
            continue

        applicable_documents.append(summarized_document)
        if edge_whitespace_leaf_titles:
            warning_documents.append(
                {
                    **summarized_document,
                    "edge_whitespace_leaf_titles": edge_whitespace_leaf_titles,
                }
            )
            continue

        passing_documents.append(summarized_document)

    if not applicable_documents:
        return (
            "na",
            "No non-empty regional leaf-title records were available, so title edge-whitespace checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if warning_documents:
        return (
            "warn",
            "Detected regional leaf titles with leading or trailing whitespace.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_CITATION,
                match_strength="regional_leaf_title_edge_whitespace_detected",
                matched_documents=warning_documents,
            ),
        )

    return (
        "pass",
        f"Validated leaf-title edge whitespace for {len(passing_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_REGIONAL_LEAF_TITLE_EDGE_WHITESPACE_CITATION,
            match_strength="regional_leaf_title_edge_whitespace_clean",
            matched_documents=passing_documents,
        ),
    )


