def _evaluate_ectd_file_size_limit_warning_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    sequence_packages = _collect_ectd_sequence_package_contexts(material_contract)
    if not sequence_packages:
        return (
            "na",
            "No eCTD sequence-package context was available, so file-size limit checks are not applicable.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    oversize_package_records: list[dict[str, Any]] = []
    checked_package_records: list[dict[str, Any]] = []
    for package in sequence_packages:
        sequence_root = Path(str(package.get("sequence_root") or "").strip())
        if not sequence_root.exists() or not sequence_root.is_dir():
            continue

        oversize_files: list[dict[str, Any]] = []
        for candidate in sequence_root.rglob("*"):
            if not candidate.is_file():
                continue
            try:
                file_size_bytes = int(candidate.stat().st_size)
            except OSError:
                continue
            relative_path = str(candidate.relative_to(sequence_root)).replace("\\", "/").strip()
            suffix = str(candidate.suffix or "").strip().lower()
            allowed_limit_bytes = (
                _ECTD_VALIDATION_STANDARD_XPT_FILE_SIZE_LIMIT_BYTES
                if suffix == ".xpt"
                else _ECTD_VALIDATION_STANDARD_GENERAL_FILE_SIZE_LIMIT_BYTES
            )
            if file_size_bytes > allowed_limit_bytes:
                oversize_files.append(
                    {
                        "path": relative_path,
                        "file_size_bytes": file_size_bytes,
                        "allowed_limit_bytes": allowed_limit_bytes,
                        "file_extension": suffix,
                    }
                )

        matched_documents = [
            {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "module_label": str(document.get("module_label") or "").strip(),
            }
            for document in list(package.get("matched_documents") or [])
        ]
        package_record = {
            "document_id": str(package.get("sequence_package_id") or "").strip(),
            "filename": sequence_root.name,
            "source_path": str(sequence_root),
            "module_label": "",
            "matched_documents": matched_documents,
        }
        checked_package_records.append(package_record)
        if oversize_files:
            oversize_package_records.append(
                {
                    **package_record,
                    "oversize_files": oversize_files,
                }
            )

    if not checked_package_records:
        return (
            "na",
            "No resolvable eCTD package roots were available for file-size limit checks.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    if oversize_package_records:
        return (
            "warn",
            "Detected eCTD package files that exceed the validation-standard file-size limits.",
            _build_requirement_details(
                {},
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_CITATION,
                match_strength="oversize_package_file_detected",
                matched_documents=oversize_package_records,
                extra_details={
                    "general_file_limit_bytes": _ECTD_VALIDATION_STANDARD_GENERAL_FILE_SIZE_LIMIT_BYTES,
                    "xpt_file_limit_bytes": _ECTD_VALIDATION_STANDARD_XPT_FILE_SIZE_LIMIT_BYTES,
                },
            ),
        )

    return (
        "pass",
        f"Validated eCTD package file-size limits for {len(checked_package_records)} package root(s).",
        _build_requirement_details(
            {},
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_FILE_SIZE_LIMIT_CITATION,
            match_strength="package_file_sizes_within_limit",
            matched_documents=checked_package_records,
            extra_details={
                "general_file_limit_bytes": _ECTD_VALIDATION_STANDARD_GENERAL_FILE_SIZE_LIMIT_BYTES,
                "xpt_file_limit_bytes": _ECTD_VALIDATION_STANDARD_XPT_FILE_SIZE_LIMIT_BYTES,
            },
        ),
    )


def _evaluate_ectd_directory_reference_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    xml_documents = [
        document
        for document in documents
        if str(document.get("filename") or "").strip().lower().endswith(".xml")
    ]
    cn_regional_documents = [
        document for document in xml_documents if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
    ]
    index_documents = [
        document for document in xml_documents if str(document.get("filename") or "").strip().lower() == "index.xml"
    ]

    if not cn_regional_documents or not index_documents:
        return (
            "na",
            "Directory-reference coverage checks require both cn-regional.xml and index.xml.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "unreferenced_directories": [],
                    "declared_directory_prefixes": [],
                },
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for cn_regional in cn_regional_documents:
        cn_source_path = str(cn_regional.get("source_path") or "").strip()
        package_root = Path(cn_source_path).resolve().parents[2] if cn_source_path else None
        matching_index = None
        for candidate in index_documents:
            candidate_path = str(candidate.get("source_path") or "").strip()
            if not package_root or not candidate_path:
                continue
            try:
                candidate_root = (
                    Path(candidate_path).resolve().parent
                    if Path(candidate_path).name.lower() == "index.xml"
                    else Path(candidate_path).resolve().parents[2]
                )
            except OSError:
                continue
            if candidate_root == package_root:
                matching_index = candidate
                break
        if matching_index is None or package_root is None:
            continue

        declared_directory_prefixes: set[str] = set()
        for xml_document in [cn_regional, matching_index]:
            for href in (xml_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_hrefs", []) or []:
                normalized_href = str(href or "").strip().replace("\\", "/")
                parts = [part for part in normalized_href.split("/") if part]
                for index in range(1, max(len(parts) - 1, 0) + 1):
                    declared_directory_prefixes.add("/".join(parts[:index]))

        actual_directories = sorted(
            str(path.relative_to(package_root)).replace("\\", "/")
            for path in package_root.rglob("*")
            if path.is_dir() and str(path.relative_to(package_root)).replace("\\", "/")
        )
        unreferenced_directories = [
            directory
            for directory in actual_directories
            if directory not in _ECTD_XML_DIRECTORY_REFERENCE_EXEMPT_DIRS
            and directory not in declared_directory_prefixes
        ]

        matched_documents = [
            {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "module_label": str(document.get("module_label") or "").strip(),
            }
            for document in [cn_regional, matching_index]
        ]
        normalized_record = {
            "document_id": str(cn_regional.get("document_id") or "").strip(),
            "filename": str(cn_regional.get("filename") or "").strip(),
            "module_label": str(cn_regional.get("module_label") or "").strip(),
            "matched_documents": matched_documents,
            "declared_directory_prefixes": sorted(declared_directory_prefixes),
        }
        if unreferenced_directories:
            failing_documents.append(
                {
                    **normalized_record,
                    "unreferenced_directories": unreferenced_directories,
                }
            )
        else:
            passing_documents.append(normalized_record)

    if failing_documents:
        return (
            "fail",
            "Detected package directories that are not covered by XML skeleton directory structure references.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_CITATION,
                match_strength="unreferenced_package_directory_structure",
                matched_documents=_dedupe_documents_for_requirement_rows(failing_documents),
                extra_details={
                    "unreferenced_directories": sorted(
                        {
                            directory
                            for document in failing_documents
                            for directory in document.get("unreferenced_directories", []) or []
                        }
                    ),
                    "declared_directory_prefixes": sorted(
                        {
                            prefix
                            for document in failing_documents
                            for prefix in document.get("declared_directory_prefixes", []) or []
                        }
                    ),
                },
            ),
        )

    return (
        "pass",
        "Validated XML skeleton directory-reference coverage for eCTD package directories.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_DIRECTORY_REFERENCE_REQUIREMENT_CITATION,
            match_strength="valid_package_directory_reference_coverage",
            matched_documents=_dedupe_documents_for_requirement_rows(passing_documents),
            extra_details={
                "unreferenced_directories": [],
                "declared_directory_prefixes": sorted(
                    {
                        prefix
                        for document in passing_documents
                        for prefix in document.get("declared_directory_prefixes", []) or []
                    }
                ),
            },
        ),
    )


def _evaluate_ectd_empty_directory_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_EMPTY_DIRECTORY_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    package_records: dict[str, dict[str, Any]] = {}
    for document in documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        if sequence_root is None:
            continue
        record = package_records.setdefault(
            str(sequence_root),
            {
                "sequence_root": sequence_root,
                "documents": [],
            },
        )
        record["documents"].append(document)

    if not package_records:
        return (
            "na",
            "No resolvable eCTD package roots were available, so empty-directory checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_EMPTY_DIRECTORY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_EMPTY_DIRECTORY_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "empty_directories": [],
                },
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for record in package_records.values():
        sequence_root = Path(record["sequence_root"])
        empty_directories = sorted(
            str(path.relative_to(sequence_root)).replace("\\", "/")
            for path in sequence_root.rglob("*")
            if path.is_dir()
            and str(path.relative_to(sequence_root)).replace("\\", "/")
            and not any(path.iterdir())
            and str(path.relative_to(sequence_root)).replace("\\", "/") not in _ECTD_EMPTY_DIRECTORY_EXEMPT_DIRS
        )

        matched_documents = [
            {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "module_label": str(document.get("module_label") or "").strip(),
            }
            for document in record["documents"]
        ]
        normalized_record = {
            "sequence_root": str(sequence_root),
            "matched_documents": matched_documents,
        }
        if empty_directories:
            failing_documents.append(
                {
                    **normalized_record,
                    "empty_directories": empty_directories,
                }
            )
        else:
            passing_documents.append(normalized_record)

    if failing_documents:
        return (
            "fail",
            "Detected non-scaffold empty directories inside the submitted eCTD sequence package.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_EMPTY_DIRECTORY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_EMPTY_DIRECTORY_REQUIREMENT_CITATION,
                match_strength="empty_package_directory_detected",
                matched_documents=_dedupe_documents_for_requirement_rows(failing_documents),
                extra_details={
                    "empty_directories": sorted(
                        {
                            directory
                            for document in failing_documents
                            for directory in document.get("empty_directories", []) or []
                        }
                    ),
                },
            ),
        )

    return (
        "pass",
        "Validated absence of non-scaffold empty directories in the eCTD sequence package.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_EMPTY_DIRECTORY_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_EMPTY_DIRECTORY_REQUIREMENT_CITATION,
            match_strength="no_non_scaffold_empty_directories",
            matched_documents=_dedupe_documents_for_requirement_rows(passing_documents),
            extra_details={
                "empty_directories": [],
            },
        ),
    )


def _normalize_placeholder_marker_text(value: str) -> str:
    normalized = re.sub(r"[\s\-_:/\\.,;()（）【】\[\]<>《》]+", "", str(value or "").strip().lower())
    return normalized


def _normalize_ectd_checksum_type(value: Any) -> str:
    return " ".join(str(value or "").split()).strip().upper()


def _normalize_ectd_checksum_value(value: Any) -> str:
    return " ".join(str(value or "").split()).strip().lower()


def _evaluate_ectd_entity_file_reuse_warning_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_ID)
    sequence_packages = _collect_ectd_sequence_package_contexts(material_contract)
    if not sequence_packages:
        return (
            "na",
            "No eCTD sequence-package context was available, so duplicate-entity-file reuse checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "duplicate_entity_file_groups": [],
                    "prior_sequence_duplicate_entity_file_groups": [],
                    "application_prior_sequence_duplicate_entity_file_groups": [],
                },
            ),
        )

    def _path_is_within(candidate: Path | None, root: Path | None) -> bool:
        if candidate is None or root is None:
            return False
        try:
            candidate.relative_to(root)
            return True
        except ValueError:
            return False

    def _build_package_checksum_groups(package: dict[str, Any]) -> dict[tuple[str, str], dict[str, Any]]:
        matched_documents = list(package.get("matched_documents", []) or [])
        xml_documents = [
            document
            for document in matched_documents
            if str(document.get("filename") or "").strip().lower().endswith(".xml")
        ]
        checksum_groups: dict[tuple[str, str], dict[str, Any]] = {}
        for document in xml_documents:
            source_path = str(document.get("source_path") or "").strip()
            sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
            leaf_records = list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
            for record in leaf_records:
                href = str(record.get("href") or "").strip()
                checksum_type = _normalize_ectd_checksum_type(record.get("checksum_type"))
                checksum = _normalize_ectd_checksum_value(record.get("checksum"))
                if not href or not checksum_type or not checksum:
                    continue
                resolved_path = None
                if sequence_root is not None:
                    try:
                        resolved_path = (sequence_root / href).resolve()
                    except OSError:
                        resolved_path = None
                group = checksum_groups.setdefault(
                    (checksum_type, checksum),
                    {
                        "checksum_type": checksum_type,
                        "checksum": checksum,
                        "entries": [],
                    },
                )
                group["entries"].append(
                    {
                        "href": href,
                        "resolved_path": str(resolved_path) if resolved_path is not None else "",
                    }
                )
        return checksum_groups

    applicable_packages: list[dict[str, Any]] = []
    warning_packages: list[dict[str, Any]] = []
    passing_packages: list[dict[str, Any]] = []
    duplicate_entity_file_groups: list[dict[str, Any]] = []
    prior_sequence_duplicate_entity_file_groups: list[dict[str, Any]] = []
    application_prior_sequence_duplicate_entity_file_groups: list[dict[str, Any]] = []
    package_lookup: dict[tuple[str, str], dict[str, Any]] = {}
    package_summaries_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    checksum_groups_by_key: dict[tuple[str, str], dict[tuple[str, str], dict[str, Any]]] = {}
    sequence_root_by_key: dict[tuple[str, str], Path] = {}

    for package in sequence_packages:
        application_key = str(package.get("application_key") or "").strip()
        sequence_number = str(package.get("sequence_number") or "").strip()
        if application_key and sequence_number:
            package_lookup[(application_key, sequence_number)] = package
            for document in list(package.get("matched_documents", []) or []):
                sequence_root = _resolve_ectd_sequence_root_from_source_path(str(document.get("source_path") or "").strip())
                if sequence_root is not None:
                    sequence_root_by_key[(application_key, sequence_number)] = sequence_root
                    break

        checksum_groups = _build_package_checksum_groups(package)
        if application_key and sequence_number:
            checksum_groups_by_key[(application_key, sequence_number)] = checksum_groups

        if not checksum_groups:
            continue

        def _entity_target_key(entry: dict[str, Any]) -> str:
            resolved_path = str(entry.get("resolved_path") or "").strip()
            if resolved_path:
                return resolved_path
            return str(entry.get("href") or "").strip()

        duplicate_groups_for_package = [
            {
                "checksum_type": group["checksum_type"],
                "checksum": group["checksum"],
                "hrefs": _dedupe_preserve_order_strings(
                    [str(entry.get("href") or "").strip() for entry in group["entries"]]
                ),
            }
            for group in checksum_groups.values()
            if len(
                _dedupe_preserve_order_strings(
                    [_entity_target_key(entry) for entry in group["entries"]]
                )
            )
            > 1
        ]
        package_summary = {
            "document_id": str(package.get("sequence_package_id") or "").strip(),
            "filename": f"sequence-{str(package.get('sequence_number') or '').strip() or 'unknown'}",
            "module_label": "",
            "duplicate_entity_file_groups": duplicate_groups_for_package,
            "prior_sequence_duplicate_entity_file_groups": [],
        }
        if application_key and sequence_number:
            package_summaries_by_key[(application_key, sequence_number)] = package_summary
        applicable_packages.append(package_summary)
        if duplicate_groups_for_package:
            duplicate_entity_file_groups.extend(duplicate_groups_for_package)
            warning_packages.append(package_summary)
        else:
            passing_packages.append(package_summary)

    for package in sequence_packages:
        application_key = str(package.get("application_key") or "").strip()
        sequence_number = str(package.get("sequence_number") or "").strip()
        related_sequence_number = str(package.get("related_sequence_number") or "").strip()
        if (
            not application_key
            or not sequence_number
            or not related_sequence_number
            or related_sequence_number == sequence_number
        ):
            continue
        current_key = (application_key, sequence_number)
        previous_key = (application_key, related_sequence_number)
        current_groups = checksum_groups_by_key.get(current_key)
        previous_groups = checksum_groups_by_key.get(previous_key)
        package_summary = package_summaries_by_key.get(current_key)
        previous_sequence_root = sequence_root_by_key.get(previous_key)
        if current_groups is None or previous_groups is None or package_summary is None:
            continue

        prior_groups_for_package: list[dict[str, Any]] = []
        for group_key, current_group in current_groups.items():
            previous_group = previous_groups.get(group_key)
            if previous_group is None:
                continue
            current_hrefs = _dedupe_preserve_order_strings(
                [
                    str(entry.get("href") or "").strip()
                    for entry in current_group["entries"]
                    if not _path_is_within(
                        Path(str(entry.get("resolved_path") or "").strip())
                        if str(entry.get("resolved_path") or "").strip()
                        else None,
                        previous_sequence_root,
                    )
                ]
            )
            if not current_hrefs:
                continue
            prior_group = {
                "current_sequence_number": sequence_number,
                "related_sequence_number": related_sequence_number,
                "checksum_type": current_group["checksum_type"],
                "checksum": current_group["checksum"],
                "current_hrefs": current_hrefs,
                "previous_hrefs": _dedupe_preserve_order_strings(
                    [str(entry.get("href") or "").strip() for entry in previous_group["entries"]]
                ),
            }
            prior_groups_for_package.append(prior_group)
            prior_sequence_duplicate_entity_file_groups.append(prior_group)

        if prior_groups_for_package:
            package_summary["prior_sequence_duplicate_entity_file_groups"] = prior_groups_for_package
            if package_summary not in warning_packages:
                warning_packages.append(package_summary)
            if package_summary in passing_packages:
                passing_packages.remove(package_summary)

    for package in sequence_packages:
        application_key = str(package.get("application_key") or "").strip()
        sequence_number = str(package.get("sequence_number") or "").strip()
        related_sequence_number = str(package.get("related_sequence_number") or "").strip()
        if not application_key or not sequence_number or not _ECTD_SEQUENCE_NUMBER_PATTERN.match(sequence_number):
            continue
        current_key = (application_key, sequence_number)
        current_groups = checksum_groups_by_key.get(current_key)
        package_summary = package_summaries_by_key.get(current_key)
        if current_groups is None or package_summary is None:
            continue

        non_related_prior_groups_for_package: list[dict[str, Any]] = []
        for prior_key, prior_groups in checksum_groups_by_key.items():
            prior_application_key, prior_sequence_number = prior_key
            if prior_application_key != application_key:
                continue
            if prior_sequence_number == sequence_number or prior_sequence_number == related_sequence_number:
                continue
            if not _ECTD_SEQUENCE_NUMBER_PATTERN.match(prior_sequence_number):
                continue
            if int(prior_sequence_number) >= int(sequence_number):
                continue

            prior_sequence_root = sequence_root_by_key.get(prior_key)
            for group_key, current_group in current_groups.items():
                previous_group = prior_groups.get(group_key)
                if previous_group is None:
                    continue
                current_hrefs = _dedupe_preserve_order_strings(
                    [
                        str(entry.get("href") or "").strip()
                        for entry in current_group["entries"]
                        if not _path_is_within(
                            Path(str(entry.get("resolved_path") or "").strip())
                            if str(entry.get("resolved_path") or "").strip()
                            else None,
                            prior_sequence_root,
                        )
                    ]
                )
                if not current_hrefs:
                    continue
                prior_group = {
                    "current_sequence_number": sequence_number,
                    "source_sequence_number": prior_sequence_number,
                    "checksum_type": current_group["checksum_type"],
                    "checksum": current_group["checksum"],
                    "current_hrefs": current_hrefs,
                    "previous_hrefs": _dedupe_preserve_order_strings(
                        [str(entry.get("href") or "").strip() for entry in previous_group["entries"]]
                    ),
                }
                non_related_prior_groups_for_package.append(prior_group)
                application_prior_sequence_duplicate_entity_file_groups.append(prior_group)

        if non_related_prior_groups_for_package:
            package_summary["application_prior_sequence_duplicate_entity_file_groups"] = non_related_prior_groups_for_package
            if package_summary not in warning_packages:
                warning_packages.append(package_summary)
            if package_summary in passing_packages:
                passing_packages.remove(package_summary)

    if not applicable_packages:
        return (
            "na",
            "No eCTD leaf checksum metadata was available at sequence-package scope, so duplicate-entity-file reuse checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "duplicate_entity_file_groups": [],
                    "prior_sequence_duplicate_entity_file_groups": [],
                    "application_prior_sequence_duplicate_entity_file_groups": [],
                },
            ),
        )

    if warning_packages:
        if (
            duplicate_entity_file_groups
            and prior_sequence_duplicate_entity_file_groups
            and application_prior_sequence_duplicate_entity_file_groups
        ):
            summary = (
                "Detected duplicate entity-file submissions within the current sequence package and across both related and earlier prior sequences."
            )
            match_strength = "mixed_duplicate_entity_file_submission_detected"
        elif duplicate_entity_file_groups and prior_sequence_duplicate_entity_file_groups:
            summary = (
                "Detected duplicate entity-file submissions both within the current sequence package and across the related prior sequence."
            )
            match_strength = "mixed_duplicate_entity_file_submission_detected"
        elif duplicate_entity_file_groups and application_prior_sequence_duplicate_entity_file_groups:
            summary = (
                "Detected duplicate entity-file submissions both within the current sequence package and across earlier prior sequences in the same application."
            )
            match_strength = "mixed_duplicate_entity_file_submission_detected"
        elif prior_sequence_duplicate_entity_file_groups and application_prior_sequence_duplicate_entity_file_groups:
            summary = (
                "Detected current-sequence entity files that duplicate files already submitted in both the related prior sequence and other earlier prior sequences in the same application."
            )
            match_strength = "mixed_duplicate_entity_file_submission_detected"
        elif duplicate_entity_file_groups:
            summary = (
                "Detected multiple entity-file hrefs within the same sequence package that declare the same checksum pair and therefore look reusable rather than separately submitted."
            )
            match_strength = "duplicate_entity_file_submission_detected"
        elif application_prior_sequence_duplicate_entity_file_groups:
            summary = (
                "Detected entity files in the current sequence package that declare the same checksum pair as files already submitted in earlier prior sequences in the same application and therefore look reusable rather than separately resubmitted."
            )
            match_strength = "application_prior_sequence_duplicate_entity_file_submission_detected"
        else:
            summary = (
                "Detected entity files in the current sequence package that declare the same checksum pair as files already submitted in the related prior sequence and therefore look reusable rather than separately resubmitted."
            )
            match_strength = "prior_sequence_duplicate_entity_file_submission_detected"
        return (
            "warn",
            summary,
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_CITATION,
                match_strength=match_strength,
                matched_documents=warning_packages,
                extra_details={
                    "duplicate_entity_file_groups": duplicate_entity_file_groups,
                    "prior_sequence_duplicate_entity_file_groups": prior_sequence_duplicate_entity_file_groups,
                    "application_prior_sequence_duplicate_entity_file_groups": application_prior_sequence_duplicate_entity_file_groups,
                },
            ),
        )

    return (
        "pass",
        "Validated absence of obvious duplicate entity-file submissions within the current sequence package.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_ENTITY_FILE_REUSE_WARNING_REQUIREMENT_CITATION,
            match_strength="no_duplicate_entity_file_submission_detected",
            matched_documents=passing_packages,
            extra_details={
                "duplicate_entity_file_groups": [],
                "prior_sequence_duplicate_entity_file_groups": [],
                "application_prior_sequence_duplicate_entity_file_groups": [],
            },
        ),
    )


def _normalize_ectd_xml_lang(value: Any) -> str:
    return " ".join(str(value or "").split()).strip().lower()


def _evaluate_ectd_leaf_xml_lang_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_LEAF_XML_LANG_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in documents
        if list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
    ]

    if not applicable_documents:
        return (
            "na",
            "No eCTD leaf xml:lang metadata was available, so leaf-language classification checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_LEAF_XML_LANG_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_LEAF_XML_LANG_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "chinese_dossier_leaf_hrefs": [],
                    "foreign_reference_leaf_hrefs": [],
                    "empty_xml_lang_leaf_hrefs": [],
                    "missing_xml_lang_leaf_hrefs": [],
                    "invalid_xml_lang_entries": [],
                },
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    applicable_detail_documents: list[dict[str, Any]] = []
    chinese_dossier_leaf_hrefs: list[str] = []
    foreign_reference_leaf_hrefs: list[str] = []
    empty_xml_lang_leaf_hrefs: list[str] = []
    missing_xml_lang_leaf_hrefs: list[str] = []
    invalid_xml_lang_entries: list[dict[str, str]] = []

    for document in applicable_documents:
        chinese_leafs: list[str] = []
        foreign_leafs: list[str] = []
        empty_leafs: list[str] = []
        missing_leafs: list[str] = []
        invalid_entries: list[dict[str, str]] = []

        for record in document["ectd_leaf_records"]:
            href = str(record.get("href") or "").strip()
            if not href:
                continue
            xml_lang = _normalize_ectd_xml_lang(record.get("xml_lang"))
            xml_lang_present = bool(record.get("xml_lang_present"))

            if not xml_lang_present:
                chinese_leafs.append(href)
                missing_leafs.append(href)
                continue
            if not xml_lang:
                chinese_leafs.append(href)
                empty_leafs.append(href)
                continue
            if xml_lang == "zh":
                chinese_leafs.append(href)
                continue

            foreign_leafs.append(href)
            if xml_lang not in _ECTD_ISO639_1_LANGUAGE_CODES:
                invalid_entries.append({"href": href, "xml_lang": xml_lang})

        chinese_dossier_leaf_hrefs.extend(chinese_leafs)
        foreign_reference_leaf_hrefs.extend(foreign_leafs)
        empty_xml_lang_leaf_hrefs.extend(empty_leafs)
        missing_xml_lang_leaf_hrefs.extend(missing_leafs)
        invalid_xml_lang_entries.extend(invalid_entries)

        normalized_document = {
            **document,
            "chinese_dossier_leaf_hrefs": chinese_leafs,
            "foreign_reference_leaf_hrefs": foreign_leafs,
            "empty_xml_lang_leaf_hrefs": empty_leafs,
            "missing_xml_lang_leaf_hrefs": missing_leafs,
            "invalid_xml_lang_entries": invalid_entries,
        }
        applicable_detail_documents.append(normalized_document)
        if invalid_entries:
            failing_documents.append(normalized_document)

    extra_details = {
        "chinese_dossier_leaf_hrefs": _dedupe_preserve_order_strings(chinese_dossier_leaf_hrefs),
        "foreign_reference_leaf_hrefs": _dedupe_preserve_order_strings(foreign_reference_leaf_hrefs),
        "empty_xml_lang_leaf_hrefs": _dedupe_preserve_order_strings(empty_xml_lang_leaf_hrefs),
        "missing_xml_lang_leaf_hrefs": _dedupe_preserve_order_strings(missing_xml_lang_leaf_hrefs),
        "invalid_xml_lang_entries": invalid_xml_lang_entries,
        "contract": _ECTD_FOREIGN_REFERENCE_CONTRACT_DETAILS,
    }

    if failing_documents:
        return (
            "fail",
            "Detected eCTD leaf xml:lang values that do not follow ISO639-1.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_LEAF_XML_LANG_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_LEAF_XML_LANG_REQUIREMENT_CITATION,
                match_strength="invalid_leaf_xml_lang_value",
                matched_documents=failing_documents,
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated xml:lang classification for {len(applicable_documents)} eCTD XML document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_LEAF_XML_LANG_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_LEAF_XML_LANG_REQUIREMENT_CITATION,
            match_strength="leaf_xml_lang_classified",
            matched_documents=applicable_detail_documents,
            extra_details=extra_details,
        ),
    )


def _classify_ectd_leaf_language(record: dict[str, Any]) -> str:
    xml_lang = _normalize_ectd_xml_lang(record.get("xml_lang"))
    xml_lang_present = bool(record.get("xml_lang_present"))
    if not xml_lang_present or not xml_lang or xml_lang == "zh":
        return "chinese"
    return "foreign"


def _evaluate_ectd_foreign_reference_structure_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in documents
        if list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
    ]

    if not applicable_documents:
        return (
            "na",
            "No eCTD leaf structure metadata was available, so foreign-reference sibling-structure checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "foreign_reference_leaf_hrefs": [],
                    "missing_chinese_sibling_foreign_leaf_hrefs": [],
                    "out_of_order_foreign_leaf_hrefs": [],
                    "contract": _ECTD_FOREIGN_REFERENCE_CONTRACT_DETAILS,
                },
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    foreign_reference_leaf_hrefs: list[str] = []
    missing_chinese_sibling_foreign_leaf_hrefs: list[str] = []
    out_of_order_foreign_leaf_hrefs: list[str] = []

    for document in applicable_documents:
        grouped_records: dict[str, list[tuple[int, dict[str, Any]]]] = {}
        for index, record in enumerate(document["ectd_leaf_records"]):
            parent_pointer = str(record.get("parent_pointer") or "").strip()
            group_key = parent_pointer or "__missing_parent__"
            grouped_records.setdefault(group_key, []).append((index, record))

        document_foreign_leafs: list[str] = []
        document_missing_chinese: list[str] = []
        document_out_of_order: list[str] = []

        for group_records in grouped_records.values():
            chinese_indices: list[int] = []
            foreign_items: list[tuple[int, str]] = []
            for index, record in group_records:
                href = str(record.get("href") or "").strip()
                if not href:
                    continue
                language_class = _classify_ectd_leaf_language(record)
                if language_class == "foreign":
                    foreign_items.append((index, href))
                    document_foreign_leafs.append(href)
                else:
                    chinese_indices.append(index)

            if not foreign_items:
                continue
            if not chinese_indices:
                document_missing_chinese.extend(href for _, href in foreign_items)
                continue

            latest_chinese_index = max(chinese_indices)
            for index, href in foreign_items:
                if index < latest_chinese_index:
                    document_out_of_order.append(href)

        foreign_reference_leaf_hrefs.extend(document_foreign_leafs)
        missing_chinese_sibling_foreign_leaf_hrefs.extend(document_missing_chinese)
        out_of_order_foreign_leaf_hrefs.extend(document_out_of_order)

        normalized_document = {
            **document,
            "foreign_reference_leaf_hrefs": _dedupe_preserve_order_strings(document_foreign_leafs),
            "missing_chinese_sibling_foreign_leaf_hrefs": _dedupe_preserve_order_strings(document_missing_chinese),
            "out_of_order_foreign_leaf_hrefs": _dedupe_preserve_order_strings(document_out_of_order),
        }
        if document_missing_chinese or document_out_of_order:
            failing_documents.append(normalized_document)
        else:
            passing_documents.append(normalized_document)

    extra_details = {
        "foreign_reference_leaf_hrefs": _dedupe_preserve_order_strings(foreign_reference_leaf_hrefs),
        "missing_chinese_sibling_foreign_leaf_hrefs": _dedupe_preserve_order_strings(
            missing_chinese_sibling_foreign_leaf_hrefs
        ),
        "out_of_order_foreign_leaf_hrefs": _dedupe_preserve_order_strings(out_of_order_foreign_leaf_hrefs),
        "contract": _ECTD_FOREIGN_REFERENCE_CONTRACT_DETAILS,
    }

    if failing_documents:
        return (
            "fail",
            "Detected foreign-reference leafs that are not colocated with or ordered after same-parent Chinese dossier leafs.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_CITATION,
                match_strength="foreign_reference_structure_violation",
                matched_documents=failing_documents,
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated foreign-reference sibling structure for {len(applicable_documents)} eCTD XML document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_FOREIGN_REFERENCE_STRUCTURE_REQUIREMENT_CITATION,
            match_strength="foreign_reference_structure_aligned",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _normalize_ectd_leaf_operation(value: Any) -> str:
    return " ".join(str(value or "").split()).strip().lower()


def _evaluate_ectd_leaf_operation_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_LEAF_OPERATION_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in documents
        if list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
    ]

    operation_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        operation_records = [
            record
            for record in document["ectd_leaf_records"]
            if bool(record.get("operation_present"))
        ]
        if operation_records:
            operation_documents.append({**document, "ectd_leaf_records": operation_records})

    if not operation_documents:
        return (
            "na",
            "No eCTD leaf operation metadata was available, so lifecycle-operation checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_LEAF_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_LEAF_OPERATION_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "allowed_operations": sorted(_ECTD_ALLOWED_LEAF_OPERATIONS),
                    "invalid_leaf_operations": [],
                },
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    invalid_leaf_operations: list[dict[str, str]] = []
    for document in operation_documents:
        invalid_operations_for_document: list[dict[str, str]] = []
        for record in document["ectd_leaf_records"]:
            href = str(record.get("href") or "").strip()
            operation = _normalize_ectd_leaf_operation(record.get("operation"))
            if not operation or operation in _ECTD_ALLOWED_LEAF_OPERATIONS:
                continue
            invalid_operations_for_document.append({"href": href, "operation": operation})
        if invalid_operations_for_document:
            invalid_leaf_operations.extend(invalid_operations_for_document)
            failing_documents.append(
                {
                    **document,
                    "invalid_leaf_operations": invalid_operations_for_document,
                }
            )

    if failing_documents:
        return (
            "fail",
            "Detected eCTD leaf operation values outside the allowed new/replace/delete/append set.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_LEAF_OPERATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_LEAF_OPERATION_REQUIREMENT_CITATION,
                match_strength="invalid_leaf_operation_value",
                matched_documents=failing_documents,
                extra_details={
                    "allowed_operations": sorted(_ECTD_ALLOWED_LEAF_OPERATIONS),
                    "invalid_leaf_operations": invalid_leaf_operations,
                },
            ),
        )

    return (
        "pass",
        f"Validated allowed leaf operation values for {len(operation_documents)} eCTD XML document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_LEAF_OPERATION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_LEAF_OPERATION_REQUIREMENT_CITATION,
            match_strength="valid_leaf_operation_values",
            matched_documents=operation_documents,
            extra_details={
                "allowed_operations": sorted(_ECTD_ALLOWED_LEAF_OPERATIONS),
                "invalid_leaf_operations": [],
            },
        ),
    )


def _build_ectd_leaf_record_match_key(document: dict[str, Any], record: dict[str, Any]) -> tuple[str, str, str]:
    return (
        str(document.get("filename") or "").strip().lower(),
        str(record.get("parent_pointer") or "").strip(),
        str(record.get("leaf_title") or "").strip(),
    )


def _evaluate_ectd_replace_language_consistency_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_ID)
    sequence_packages = _collect_ectd_sequence_package_contexts(material_contract)
    if not sequence_packages:
        return (
            "na",
            "No eCTD sequence-package context was available, so replace-language consistency checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "mismatched_replace_leaf_pairs": [],
                    "contract": _ECTD_FOREIGN_REFERENCE_CONTRACT_DETAILS,
                },
            ),
        )

    package_lookup = {
        (
            str(package.get("application_key") or "").strip(),
            str(package.get("sequence_number") or "").strip(),
        ): package
        for package in sequence_packages
        if str(package.get("application_key") or "").strip() and str(package.get("sequence_number") or "").strip()
    }

    compared_pairs: list[dict[str, str]] = []
    mismatched_pairs: list[dict[str, str]] = []
    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for package in sequence_packages:
        application_key = str(package.get("application_key") or "").strip()
        related_sequence_number = str(package.get("related_sequence_number") or "").strip()
        current_sequence_number = str(package.get("sequence_number") or "").strip()
        if not application_key or not related_sequence_number or related_sequence_number == current_sequence_number:
            continue

        previous_package = package_lookup.get((application_key, related_sequence_number))
        if previous_package is None:
            continue

        previous_leaf_lookup: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
        for previous_document in previous_package.get("matched_documents", []) or []:
            previous_filename = str(previous_document.get("filename") or "").strip().lower()
            if not previous_filename.endswith(".xml"):
                continue
            previous_leaf_records = list((previous_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
            for previous_record in previous_leaf_records:
                match_key = _build_ectd_leaf_record_match_key(previous_document, previous_record)
                if not match_key[1] or not match_key[2]:
                    continue
                previous_leaf_lookup.setdefault(match_key, []).append(
                    {
                        **previous_record,
                        "filename": str(previous_document.get("filename") or "").strip(),
                    }
                )

        package_mismatched_pairs: list[dict[str, str]] = []
        package_compared_pairs: list[dict[str, str]] = []
        package_documents: list[dict[str, Any]] = []

        for current_document in package.get("matched_documents", []) or []:
            current_filename = str(current_document.get("filename") or "").strip().lower()
            if not current_filename.endswith(".xml"):
                continue
            current_leaf_records = list((current_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
            for current_record in current_leaf_records:
                if _normalize_ectd_leaf_operation(current_record.get("operation")) != "replace":
                    continue
                match_key = _build_ectd_leaf_record_match_key(current_document, current_record)
                if not match_key[1] or not match_key[2]:
                    continue
                previous_candidates = previous_leaf_lookup.get(match_key, [])
                if len(previous_candidates) != 1:
                    continue
                previous_record = previous_candidates[0]
                current_language_class = _classify_ectd_leaf_language(current_record)
                previous_language_class = _classify_ectd_leaf_language(previous_record)
                pair_payload = {
                    "current_href": str(current_record.get("href") or "").strip(),
                    "current_xml_lang": _normalize_ectd_xml_lang(current_record.get("xml_lang")),
                    "current_language_class": current_language_class,
                    "previous_href": str(previous_record.get("href") or "").strip(),
                    "previous_xml_lang": _normalize_ectd_xml_lang(previous_record.get("xml_lang")),
                    "previous_language_class": previous_language_class,
                }
                package_compared_pairs.append(pair_payload)
                compared_pairs.append(pair_payload)
                if current_language_class != previous_language_class:
                    package_mismatched_pairs.append(pair_payload)
                    mismatched_pairs.append(pair_payload)
                    package_documents.append(current_document)

        if package_compared_pairs:
            normalized_row = {
                "sequence_number": current_sequence_number,
                "related_sequence_number": related_sequence_number,
                "matched_documents": _dedupe_documents_for_requirement_rows(
                    [{"matched_documents": package_documents or list(package.get("matched_documents", []) or [])}]
                ),
                "mismatched_replace_leaf_pairs": package_mismatched_pairs,
                "compared_replace_leaf_pairs": package_compared_pairs,
            }
            if package_mismatched_pairs:
                failing_documents.append(normalized_row)
            else:
                passing_documents.append(normalized_row)

    if not compared_pairs:
        return (
            "na",
            "No uniquely matched replace-leaf historical pairs were available for language-consistency checks.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "mismatched_replace_leaf_pairs": [],
                    "contract": _ECTD_FOREIGN_REFERENCE_CONTRACT_DETAILS,
                },
            ),
        )

    if mismatched_pairs:
        return (
            "fail",
            "Detected replace-operation leafs whose language class does not match the uniquely matched prior-sequence leaf.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_CITATION,
                match_strength="replace_language_class_mismatch",
                matched_documents=failing_documents,
                extra_details={
                    "mismatched_replace_leaf_pairs": mismatched_pairs,
                    "contract": _ECTD_FOREIGN_REFERENCE_CONTRACT_DETAILS,
                },
            ),
        )

    return (
        "pass",
        f"Validated replace-language consistency for {len(compared_pairs)} uniquely matched replace leaf pair(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_REPLACE_LANGUAGE_CONSISTENCY_REQUIREMENT_CITATION,
            match_strength="replace_language_class_consistent",
            matched_documents=passing_documents,
            extra_details={"mismatched_replace_leaf_pairs": []},
        ),
    )


def _is_within_stf_required_zone(record: dict[str, Any]) -> bool:
    leaf_pointer = str(record.get("leaf_pointer") or "").strip().lower()
    parent_pointer = str(record.get("parent_pointer") or "").strip().lower()
    if any(marker in leaf_pointer for marker in _ECTD_STF_POINTER_MARKERS):
        return True
    if any(marker in parent_pointer for marker in _ECTD_STF_POINTER_MARKERS):
        return True
    href = str(record.get("href") or "").strip().replace("\\", "/").lower()
    if href.startswith("m4/42"):
        return True
    return False


def _is_direct_child_of_stf_section(record: dict[str, Any]) -> bool:
    if not _is_within_stf_required_zone(record):
        return False
    parent_local_tag = _normalize_fact_value(record.get("parent_local_tag")).lower()
    normalized_parent_tag = "".join(ch for ch in parent_local_tag if ch.isalnum())
    return any(normalized_parent_tag.startswith(prefix) for prefix in _ECTD_STF_PARENT_TAG_PREFIXES)


def _has_explicit_stf_parent_tag_signal(record: dict[str, Any]) -> bool:
    if not _is_within_stf_required_zone(record) or _is_direct_child_of_stf_section(record):
        return False
    parent_local_tag = _normalize_fact_value(record.get("parent_local_tag")).lower()
    normalized_parent_tag = "".join(ch for ch in parent_local_tag if ch.isalnum())
    href = str(record.get("href") or "").strip().lower()
    if not normalized_parent_tag:
        return False
    if href.endswith(".xpt"):
        return normalized_parent_tag.endswith("dataset")
    if normalized_parent_tag in _ECTD_STF_EXPLICIT_PARENT_EXACT_TAGS:
        return True
    return any(
        normalized_parent_tag.endswith(suffix)
        for suffix in _ECTD_STF_EXPLICIT_PARENT_SUFFIXES
    )


def _is_stf_append_leaf(record: dict[str, Any]) -> bool:
    return _has_explicit_stf_parent_tag_signal(record)


def _is_m537_case_report_form_leaf(record: dict[str, Any]) -> bool:
    pointer_values = [
        str(record.get("leaf_pointer") or "").strip().replace("\\", "/").lower(),
        str(record.get("parent_pointer") or "").strip().replace("\\", "/").lower(),
        str(record.get("href") or "").strip().replace("\\", "/").lower(),
        str(record.get("parent_local_tag") or "").strip().replace("\\", "/").lower(),
    ]
    pointer_values.extend(str(value or "").strip().replace("\\", "/").lower() for value in list(record.get("ancestor_local_tags") or []))
    pointer_values.extend(
        str(value or "").strip().replace("\\", "/").lower()
        for value in list(record.get("ancestor_normalized_names") or [])
    )
    for value in pointer_values:
        comparable_value = f"/{value.strip('/')}"
        normalized_value = "".join(ch for ch in value if ch.isalnum())
        if any(marker in comparable_value for marker in _ECTD_STF_M537_SECTION_MARKERS):
            return True
        if normalized_value.startswith("m537") or "m537" in normalized_value:
            return True
    return False


def _evaluate_ectd_append_stf_scope_requirement(
    material_contract: dict[str, Any],
    *,
    requirement_id: str,
    citation_anchor: str,
    document_filename: str | None = None,
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(requirement_id)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in documents
        if list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
        and (
            document_filename is None
            or str(document.get("filename") or "").strip().lower() == document_filename.lower()
        )
    ]

    append_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        append_records = [
            record
            for record in document["ectd_leaf_records"]
            if _normalize_ectd_leaf_operation(record.get("operation")) == "append"
        ]
        if append_records:
            append_documents.append({**document, "ectd_leaf_records": append_records})

    if not append_documents:
        return (
            "na",
            "No append lifecycle operations were declared, so STF-sensitive append checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "stf_append_leaf_hrefs": [],
                    "non_stf_append_leaf_hrefs": [],
                },
            ),
        )

    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    stf_append_leaf_hrefs: list[str] = []
    non_stf_append_leaf_hrefs: list[str] = []

    for document in append_documents:
        stf_hrefs: list[str] = []
        non_stf_hrefs: list[str] = []
        for record in document["ectd_leaf_records"]:
            href = str(record.get("href") or "").strip()
            if not href:
                continue
            if _is_stf_append_leaf(record):
                stf_hrefs.append(href)
                stf_append_leaf_hrefs.append(href)
            else:
                non_stf_hrefs.append(href)
                non_stf_append_leaf_hrefs.append(href)

        normalized_document = {
            **document,
            "stf_append_leaf_hrefs": _dedupe_preserve_order_strings(stf_hrefs),
            "non_stf_append_leaf_hrefs": _dedupe_preserve_order_strings(non_stf_hrefs),
        }
        if non_stf_hrefs:
            warning_documents.append(normalized_document)
        else:
            passing_documents.append(normalized_document)

    extra_details = {
        "stf_append_leaf_hrefs": _dedupe_preserve_order_strings(stf_append_leaf_hrefs),
        "non_stf_append_leaf_hrefs": _dedupe_preserve_order_strings(non_stf_append_leaf_hrefs),
    }

    if warning_documents:
        return (
            "warn",
            "Detected append lifecycle operations that are not clearly STF-scoped and therefore should be treated as warning-level usage.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=requirement_id,
                fallback_citation_anchor=citation_anchor,
                match_strength="non_stf_append_detected",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )

    return (
        "pass",
        f"Validated STF-scoped append usage for {len(append_documents)} eCTD XML document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=requirement_id,
            fallback_citation_anchor=citation_anchor,
            match_strength="stf_append_only",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_non_stf_append_warning_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    return _evaluate_ectd_append_stf_scope_requirement(
        material_contract,
        requirement_id=_ECTD_NON_STF_APPEND_WARNING_REQUIREMENT_ID,
        citation_anchor=_ECTD_NON_STF_APPEND_WARNING_REQUIREMENT_CITATION,
    )


