def _evaluate_ectd_stf_study_identifier_title_match_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_xml_documents(material_contract)
    index_documents = [
        document
        for document in _collect_ectd_submission_metadata_documents(material_contract)
        if str(document.get("filename") or "").strip().lower() == "index.xml"
    ]
    leaf_id_records_by_id: dict[str, list[dict[str, Any]]] = {}
    for document in index_documents:
        metadata = dict(document.get("ectd_submission_metadata") or {})
        leaf_titles_by_pointer = {
            str(record.get("leaf_pointer") or "").strip(): dict(record)
            for record in list(metadata.get("ectd_leaf_title_records") or [])
            if str(record.get("leaf_pointer") or "").strip()
        }
        for attribute in list(metadata.get("ectd_attribute_records") or []):
            if _normalize_xml_name_for_rules(attribute.get("element_normalized_name") or attribute.get("element_local_tag")) != "leaf":
                continue
            if _normalize_xml_name_for_rules(attribute.get("normalized_attribute_name") or attribute.get("attribute_name")) != "id":
                continue
            leaf_id = _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
            leaf_pointer = str(attribute.get("element_pointer") or "").strip()
            if not leaf_id or not leaf_pointer:
                continue
            title_record = leaf_titles_by_pointer.get(leaf_pointer, {})
            leaf_id_records_by_id.setdefault(leaf_id, []).append(
                {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "leaf_id": leaf_id,
                    "leaf_pointer": leaf_pointer,
                    "index_leaf_title": _normalize_fact_value(title_record.get("normalized_title_text")),
                    "index_leaf_title_present": bool(title_record.get("title_present")),
                }
            )

    mismatches: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []
    unresolved_references: list[dict[str, Any]] = []
    ambiguous_references: list[dict[str, Any]] = []
    missing_title_references: list[dict[str, Any]] = []
    comparable_reference_count = 0

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        attribute_records = list(document.get("ectd_attribute_records") or [])
        study_identifier_pointers = [
            str(record.get("element_pointer") or "").strip()
            for record in element_records
            if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
            == "studyidentifier"
            and str(record.get("element_pointer") or "").strip()
        ]
        title_records = [
            record
            for record in element_records
            if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
            == "title"
            and str(record.get("parent_pointer") or "").strip() in study_identifier_pointers
        ]
        stf_title_values = [
            _normalize_fact_value(record.get("element_text"))
            for record in title_records
            if _normalize_fact_value(record.get("element_text"))
        ]
        stf_title_values = _dedupe_preserve_order_strings(stf_title_values)
        doc_content_hrefs = [
            {
                "doc_content_pointer": str(attribute.get("element_pointer") or "").strip(),
                "referenced_leaf_id": _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value")),
            }
            for attribute in attribute_records
            if _normalize_xml_name_for_rules(attribute.get("element_normalized_name") or attribute.get("element_local_tag"))
            == "doccontent"
            and _normalize_xml_name_for_rules(attribute.get("normalized_attribute_name") or attribute.get("attribute_name"))
            == "href"
            and _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
        ]

        document_mismatches: list[dict[str, Any]] = []
        document_prerequisites: list[dict[str, Any]] = []
        if len(stf_title_values) != 1:
            document_prerequisites.append(
                {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "reason": "missing_or_ambiguous_study_identifier_title",
                    "stf_title_values": stf_title_values,
                }
            )
        if not doc_content_hrefs:
            document_prerequisites.append(
                {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "reason": "missing_doc_content_href",
                }
            )
        if document_prerequisites:
            prerequisite_documents.append({**document, "study_title_match_prerequisites": document_prerequisites})
            continue

        stf_title = stf_title_values[0]
        document_unresolved: list[dict[str, Any]] = []
        document_ambiguous: list[dict[str, Any]] = []
        document_missing_titles: list[dict[str, Any]] = []
        document_compared_count = 0
        for href_record in doc_content_hrefs:
            referenced_leaf_id = href_record["referenced_leaf_id"]
            index_leaf_records = leaf_id_records_by_id.get(referenced_leaf_id, [])
            base_issue = {
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "doc_content_pointer": href_record["doc_content_pointer"],
                "referenced_leaf_id": referenced_leaf_id,
            }
            if not index_leaf_records:
                issue = {**base_issue, "reason": "index_leaf_id_not_found"}
                unresolved_references.append(issue)
                document_unresolved.append(issue)
                continue
            if len(index_leaf_records) != 1:
                issue = {
                    **base_issue,
                    "reason": "index_leaf_id_not_unique",
                    "matching_index_leaf_count": len(index_leaf_records),
                }
                ambiguous_references.append(issue)
                document_ambiguous.append(issue)
                continue
            index_leaf_record = index_leaf_records[0]
            index_leaf_title = _normalize_fact_value(index_leaf_record.get("index_leaf_title"))
            if not index_leaf_title:
                issue = {
                    **base_issue,
                    "reason": "index_leaf_title_missing_or_blank",
                    "index_leaf_pointer": str(index_leaf_record.get("leaf_pointer") or "").strip(),
                    "index_source_path": str(index_leaf_record.get("source_path") or "").strip(),
                }
                missing_title_references.append(issue)
                document_missing_titles.append(issue)
                continue
            comparable_reference_count += 1
            document_compared_count += 1
            if stf_title == index_leaf_title:
                continue
            issue = {
                **base_issue,
                "stf_title": stf_title,
                "index_leaf_title": index_leaf_title,
                "index_leaf_pointer": str(index_leaf_record.get("leaf_pointer") or "").strip(),
                "index_source_path": str(index_leaf_record.get("source_path") or "").strip(),
            }
            mismatches.append(issue)
            document_mismatches.append(issue)

        if document_mismatches:
            warning_documents.append({**document, "study_title_mismatches": document_mismatches})
        elif document_unresolved or document_ambiguous or document_missing_titles:
            prerequisite_documents.append(
                {
                    **document,
                    "unresolved_doc_content_references": document_unresolved,
                    "ambiguous_doc_content_references": document_ambiguous,
                    "missing_index_leaf_title_references": document_missing_titles,
                }
            )
        elif document_compared_count:
            passing_documents.append({**document, "checked_study_title_reference_count": document_compared_count})

    extra_details = {
        "checked_stf_study_title_reference_count": comparable_reference_count,
        "stf_study_title_mismatches": mismatches,
        "stf_study_title_unresolved_references": unresolved_references,
        "stf_study_title_ambiguous_references": ambiguous_references,
        "stf_study_title_missing_index_leaf_titles": missing_title_references,
        "stf_study_title_prerequisite_documents": prerequisite_documents,
    }
    if not stf_documents:
        return (
            "na",
            "No STF XML documents were available in module 4/5 STF zones, so study-title matching is not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if not index_documents:
        return (
            "na",
            "No index.xml document was available, so STF study-title matching needs backbone leaf-title prerequisite evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_CITATION,
                match_strength="index_leaf_title_prerequisite_missing",
                matched_documents=prerequisite_documents,
                extra_details=extra_details,
            ),
        )
    if mismatches:
        return (
            "warn",
            "Detected STF study-identifier titles that do not match the referenced index leaf titles.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_CITATION,
                match_strength="stf_study_identifier_title_mismatch",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if comparable_reference_count == 0:
        return (
            "na",
            "STF study-title matching needs exactly one STF study-identifier title and uniquely resolved index leaf ID/title evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_CITATION,
                match_strength="stf_study_title_match_prerequisite_missing",
                matched_documents=prerequisite_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated {comparable_reference_count} STF study-title reference(s) against index leaf titles.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_IDENTIFIER_TITLE_MATCH_CITATION,
            match_strength="stf_study_identifier_title_matches_index_leaf_title",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


_ECTD_STF_REQUIRED_CATEGORY_SECTION_NAMES = {
    "m4231singledosetoxicity": "4.2.3.1",
    "m4232repeatdosetoxicity": "4.2.3.2",
    "m42341longtermstudies": "4.2.3.4.1",
    "m5351studyreportsofcontrolledclinicalstudiespertinenttotheclaimedindication": "5.3.5.1",
}
_ECTD_STF_REQUIRED_CATEGORY_PATH_MARKERS = (
    ("4.2.3.1", ("m4231", "4231")),
    ("4.2.3.2", ("m4232", "4232")),
    ("4.2.3.4.1", ("m42341", "42341")),
    ("5.3.5.1", ("m5351", "5351")),
)


def _normalize_ectd_rule_path(value: Any) -> str:
    candidate = unquote(str(value or "").strip()).replace("\\", "/").lower()
    while "//" in candidate:
        candidate = candidate.replace("//", "/")
    while candidate.startswith("./"):
        candidate = candidate[2:]
    return candidate.strip("/")


def _relative_ectd_source_path_key(source_path: str) -> str:
    sequence_root = _find_ectd_sequence_root_for_file_path(source_path)
    if sequence_root is None:
        return ""
    try:
        relative_path = Path(source_path).resolve().relative_to(sequence_root.resolve())
    except (OSError, ValueError):
        return ""
    return _normalize_ectd_rule_path(str(relative_path))


def _infer_stf_required_category_sections_from_path(path_value: Any) -> list[str]:
    normalized_path = _normalize_ectd_rule_path(path_value)
    if not normalized_path:
        return []
    matched_sections: list[str] = []
    for segment in normalized_path.split("/"):
        normalized_segment = _normalize_xml_name_for_rules(segment)
        if not normalized_segment:
            continue
        for section_number, markers in _ECTD_STF_REQUIRED_CATEGORY_PATH_MARKERS:
            if any(normalized_segment.startswith(marker) for marker in markers):
                matched_sections.append(section_number)
    return _dedupe_preserve_order_strings(matched_sections)


def _infer_stf_required_category_sections_from_leaf_context(
    leaf_record: dict[str, Any],
    element_records_by_pointer: dict[str, dict[str, Any]],
) -> list[str]:
    candidate_names: list[str] = []
    parent_name = _normalize_xml_name_for_rules(leaf_record.get("parent_local_tag"))
    if parent_name:
        candidate_names.append(parent_name)
    for pointer_key in (
        str(leaf_record.get("parent_pointer") or "").strip(),
        str(leaf_record.get("leaf_pointer") or "").strip(),
    ):
        element_record = element_records_by_pointer.get(pointer_key, {})
        candidate_names.append(
            _normalize_xml_name_for_rules(
                element_record.get("element_normalized_name") or element_record.get("element_local_tag")
            )
        )
        candidate_names.extend(
            _normalize_xml_name_for_rules(name)
            for name in list(element_record.get("ancestor_normalized_names") or [])
        )
        candidate_names.extend(
            _normalize_xml_name_for_rules(name)
            for name in list(element_record.get("ancestor_local_tags") or [])
        )
    matched_sections = [
        _ECTD_STF_REQUIRED_CATEGORY_SECTION_NAMES[name]
        for name in _dedupe_preserve_order_strings(candidate_names)
        if name in _ECTD_STF_REQUIRED_CATEGORY_SECTION_NAMES
    ]
    return _dedupe_preserve_order_strings(matched_sections)


def _build_stf_required_category_index_leaf_records_by_href(
    index_documents: list[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    records_by_href: dict[str, list[dict[str, Any]]] = {}
    for document in index_documents:
        metadata = dict(document.get("ectd_submission_metadata") or {})
        element_records_by_pointer = {
            str(record.get("element_pointer") or "").strip(): dict(record)
            for record in list(metadata.get("ectd_element_records") or [])
            if str(record.get("element_pointer") or "").strip()
        }
        for leaf_record in list(metadata.get("ectd_leaf_records") or []):
            href = _normalize_fact_value(leaf_record.get("href"))
            href_key = _normalize_ectd_rule_path(href)
            if not href_key:
                continue
            context_sections = _infer_stf_required_category_sections_from_leaf_context(
                dict(leaf_record),
                element_records_by_pointer,
            )
            path_sections = _infer_stf_required_category_sections_from_path(href)
            required_sections = _dedupe_preserve_order_strings([*context_sections, *path_sections])
            if not required_sections:
                continue
            records_by_href.setdefault(href_key, []).append(
                {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "href": href,
                    "leaf_pointer": str(leaf_record.get("leaf_pointer") or "").strip(),
                    "required_category_sections": required_sections,
                    "section_evidence": "index_leaf_context" if context_sections else "index_leaf_href_path",
                }
            )
    return records_by_href


def _match_stf_document_to_required_category_index_records(
    document: dict[str, Any],
    records_by_href: dict[str, list[dict[str, Any]]],
) -> list[dict[str, Any]]:
    relative_key = _relative_ectd_source_path_key(str(document.get("source_path") or ""))
    if relative_key and relative_key in records_by_href:
        return list(records_by_href.get(relative_key, []) or [])

    source_key = _normalize_ectd_rule_path(document.get("source_path"))
    if not source_key:
        return []
    matched_records: list[dict[str, Any]] = []
    for href_key, href_records in records_by_href.items():
        if source_key == href_key or source_key.endswith(f"/{href_key}"):
            matched_records.extend(dict(record) for record in href_records)
    return matched_records


def _collect_stf_study_identifier_category_evidence(
    element_records: list[dict[str, Any]],
) -> tuple[list[str], list[str]]:
    study_identifier_pointers = {
        str(record.get("element_pointer") or "").strip()
        for record in element_records
        if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
        == "studyidentifier"
        and str(record.get("element_pointer") or "").strip()
    }
    category_pointers: list[str] = []
    blank_category_pointers: list[str] = []
    if not study_identifier_pointers:
        blank_category_pointers.append("missing-study-identifier/category:missing")
        return category_pointers, blank_category_pointers

    category_records = [
        record
        for record in element_records
        if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
        == "category"
        and str(record.get("parent_pointer") or "").strip() in study_identifier_pointers
    ]
    if not category_records:
        blank_category_pointers.extend(f"{pointer}/category:missing" for pointer in sorted(study_identifier_pointers))
        return category_pointers, blank_category_pointers

    for category_record in category_records:
        pointer = str(category_record.get("element_pointer") or "").strip()
        if _normalize_fact_value(category_record.get("element_text")):
            category_pointers.append(pointer)
        else:
            blank_category_pointers.append(pointer)
    return (
        _dedupe_preserve_order_strings(category_pointers),
        _dedupe_preserve_order_strings(blank_category_pointers),
    )


def _evaluate_ectd_stf_required_section_category_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_xml_documents(material_contract)
    index_documents = [
        document
        for document in _collect_ectd_submission_metadata_documents(material_contract)
        if str(document.get("filename") or "").strip().lower() == "index.xml"
    ]
    index_records_by_href = _build_stf_required_category_index_leaf_records_by_href(index_documents)

    missing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []
    checked_required_section_document_count = 0

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        matched_index_records = _match_stf_document_to_required_category_index_records(document, index_records_by_href)
        matched_index_sections = _dedupe_preserve_order_strings(
            [
                section
                for record in matched_index_records
                for section in list(record.get("required_category_sections") or [])
                if str(section or "").strip()
            ]
        )
        path_sections = _infer_stf_required_category_sections_from_path(document.get("source_path"))
        required_sections = _dedupe_preserve_order_strings([*matched_index_sections, *path_sections])
        if not required_sections:
            prerequisite_documents.append(
                {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "reason": "stf_required_category_section_not_identified",
                }
            )
            continue

        checked_required_section_document_count += 1
        category_pointers, blank_category_pointers = _collect_stf_study_identifier_category_evidence(element_records)
        document_record = {
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "required_category_sections": required_sections,
            "matched_index_leaf_hrefs": _dedupe_preserve_order_strings(
                [str(record.get("href") or "").strip() for record in matched_index_records]
            ),
            "category_pointers": category_pointers,
            "category_blank_pointers": blank_category_pointers,
            "section_evidence": _dedupe_preserve_order_strings(
                [
                    *[str(record.get("section_evidence") or "").strip() for record in matched_index_records],
                    *("source_path" for _ in path_sections),
                ]
            ),
        }
        if not category_pointers:
            missing_documents.append(document_record)
        else:
            passing_documents.append(document_record)

    extra_details = {
        "checked_stf_required_section_category_document_count": checked_required_section_document_count,
        "stf_required_section_category_missing_documents": missing_documents,
        "stf_required_section_category_passing_documents": passing_documents,
        "stf_required_section_category_prerequisite_documents": prerequisite_documents,
    }
    if not stf_documents:
        return (
            "na",
            "No STF XML documents were available in module 4/5 STF zones, so required-section category checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if missing_documents:
        return (
            "warn",
            "Detected STF XML documents in category-required CTD sections without non-empty study-identifier category information.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_CITATION,
                match_strength="stf_required_section_category_missing",
                matched_documents=missing_documents,
                extra_details=extra_details,
            ),
        )
    if checked_required_section_document_count == 0:
        return (
            "na",
            "No STF XML document could be linked to CTD sections that require category information; index.xml context or clear numeric section path evidence is needed.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_CITATION,
                match_strength="stf_required_section_category_prerequisite_missing",
                matched_documents=prerequisite_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated STF category information for {checked_required_section_document_count} STF XML document(s) in category-required CTD sections.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_REQUIRED_SECTION_CATEGORY_CITATION,
            match_strength="stf_required_section_category_present",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _normalize_ectd_resolved_path_key(path: Path | None) -> str:
    if path is None:
        return ""
    try:
        return os.path.normcase(os.path.normpath(str(path.resolve())))
    except OSError:
        return ""


def _collect_stf_study_identifier_study_id_values(
    document: dict[str, Any],
) -> tuple[list[str], list[str]]:
    element_records = list(document.get("ectd_element_records") or [])
    study_identifier_pointers = {
        str(record.get("element_pointer") or "").strip()
        for record in element_records
        if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
        == "studyidentifier"
        and str(record.get("element_pointer") or "").strip()
    }
    if not study_identifier_pointers:
        return [], ["missing-study-identifier/study-id:missing"]
    study_id_records = [
        record
        for record in element_records
        if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
        == "studyid"
        and str(record.get("parent_pointer") or "").strip() in study_identifier_pointers
    ]
    if not study_id_records:
        return [], [f"{pointer}/study-id:missing" for pointer in sorted(study_identifier_pointers)]
    values: list[str] = []
    blank_pointers: list[str] = []
    for record in study_id_records:
        value = _normalize_fact_value(record.get("element_text"))
        if value:
            values.append(value)
        else:
            blank_pointers.append(str(record.get("element_pointer") or "").strip())
    return _dedupe_preserve_order_strings(values), _dedupe_preserve_order_strings(blank_pointers)


def _summarize_stf_study_id_document(document: dict[str, Any]) -> dict[str, Any]:
    values, blank_pointers = _collect_stf_study_identifier_study_id_values(document)
    return {
        "document_id": str(document.get("document_id") or "").strip(),
        "filename": str(document.get("filename") or "").strip(),
        "source_path": str(document.get("source_path") or "").strip(),
        "study_id_values": values,
        "study_id_blank_pointers": blank_pointers,
    }


def _build_stf_study_id_documents_by_path(
    stf_documents: list[dict[str, Any]],
) -> dict[str, dict[str, Any]]:
    documents_by_path: dict[str, dict[str, Any]] = {}
    for document in stf_documents:
        source_path = str(document.get("source_path") or "").strip()
        if not source_path:
            continue
        path_key = _normalize_ectd_resolved_path_key(Path(source_path))
        if not path_key:
            continue
        documents_by_path[path_key] = {**document, **_summarize_stf_study_id_document(document)}
    return documents_by_path


def _build_stf_study_id_lifecycle_prerequisite(
    *,
    document: dict[str, Any],
    record: dict[str, Any],
    sequence_root: Path | None,
    current_path_key: str,
    previous_path_key: str,
    reason: str,
) -> dict[str, Any]:
    return {
        **_summarize_ectd_lifecycle_graph_operation(
            document,
            record,
            sequence_root=sequence_root,
            target_key=previous_path_key,
        ),
        "resolved_current_href_path": current_path_key,
        "resolved_modified_file_path": previous_path_key,
        "prerequisite": reason,
    }


def _evaluate_ectd_stf_study_id_lifecycle_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_xml_documents(material_contract)
    lifecycle_documents = _collect_ectd_lifecycle_documents_by_filename(material_contract, "index.xml")
    stf_documents_by_path = _build_stf_study_id_documents_by_path(stf_documents)

    compared_pairs: list[dict[str, Any]] = []
    mismatches: list[dict[str, Any]] = []
    prerequisite_records: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in lifecycle_documents:
        source_path = str(document.get("source_path") or "").strip()
        sequence_root = _resolve_ectd_sequence_root_from_source_path(source_path)
        document_mismatches: list[dict[str, Any]] = []
        document_compared_pairs: list[dict[str, Any]] = []
        document_prerequisites: list[dict[str, Any]] = []
        for record in list(document.get("ectd_leaf_lifecycle_records") or []):
            operation = _normalize_ectd_leaf_operation(record.get("operation"))
            if operation not in {"replace", "append"}:
                continue
            current_href = str(record.get("href") or "").strip()
            modified_file_href = str(record.get("modified_file_href") or "").strip()
            if not current_href or not modified_file_href:
                continue

            current_path = _resolve_ectd_lifecycle_target_path(sequence_root, current_href)
            previous_path = _resolve_ectd_lifecycle_target_path(sequence_root, modified_file_href)
            current_path_key = _normalize_ectd_resolved_path_key(current_path)
            previous_path_key = _normalize_ectd_resolved_path_key(previous_path)
            current_path_signal = _is_stf_xml_source_path(str(current_path or ""))
            previous_path_signal = _is_stf_xml_source_path(str(previous_path or ""))
            if not current_path_signal and not previous_path_signal:
                continue
            if not current_path_key or not previous_path_key:
                prerequisite = _build_stf_study_id_lifecycle_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    current_path_key=current_path_key,
                    previous_path_key=previous_path_key,
                    reason="stf_lifecycle_path_unresolvable",
                )
                prerequisite_records.append(prerequisite)
                document_prerequisites.append(prerequisite)
                continue

            current_stf_document = stf_documents_by_path.get(current_path_key)
            previous_stf_document = stf_documents_by_path.get(previous_path_key)
            if current_stf_document is None or previous_stf_document is None:
                prerequisite = _build_stf_study_id_lifecycle_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    current_path_key=current_path_key,
                    previous_path_key=previous_path_key,
                    reason="current_or_previous_stf_xml_document_missing",
                )
                prerequisite_records.append(prerequisite)
                document_prerequisites.append(prerequisite)
                continue

            current_study_ids = list(current_stf_document.get("study_id_values") or [])
            previous_study_ids = list(previous_stf_document.get("study_id_values") or [])
            if len(current_study_ids) != 1 or len(previous_study_ids) != 1:
                prerequisite = _build_stf_study_id_lifecycle_prerequisite(
                    document=document,
                    record=record,
                    sequence_root=sequence_root,
                    current_path_key=current_path_key,
                    previous_path_key=previous_path_key,
                    reason="current_or_previous_stf_study_id_missing_or_ambiguous",
                )
                prerequisite["current_stf_document"] = _summarize_stf_study_id_document(current_stf_document)
                prerequisite["previous_stf_document"] = _summarize_stf_study_id_document(previous_stf_document)
                prerequisite_records.append(prerequisite)
                document_prerequisites.append(prerequisite)
                continue

            pair = {
                **_summarize_ectd_lifecycle_graph_operation(
                    document,
                    record,
                    sequence_root=sequence_root,
                    target_key=previous_path_key,
                ),
                "resolved_current_href_path": current_path_key,
                "resolved_modified_file_path": previous_path_key,
                "current_stf_filename": str(current_stf_document.get("filename") or "").strip(),
                "current_stf_source_path": str(current_stf_document.get("source_path") or "").strip(),
                "current_study_id": current_study_ids[0],
                "previous_stf_filename": str(previous_stf_document.get("filename") or "").strip(),
                "previous_stf_source_path": str(previous_stf_document.get("source_path") or "").strip(),
                "previous_study_id": previous_study_ids[0],
            }
            compared_pairs.append(pair)
            document_compared_pairs.append(pair)
            if current_study_ids[0] != previous_study_ids[0]:
                mismatches.append(pair)
                document_mismatches.append(pair)

        if document_mismatches:
            warning_documents.append(
                {**_summarize_ectd_lifecycle_document(document), "stf_study_id_lifecycle_mismatches": document_mismatches}
            )
        elif document_compared_pairs:
            passing_documents.append(
                {**_summarize_ectd_lifecycle_document(document), "checked_stf_study_id_lifecycle_pairs": document_compared_pairs}
            )
        elif document_prerequisites:
            warning_documents.append(
                {**_summarize_ectd_lifecycle_document(document), "stf_study_id_lifecycle_prerequisites": document_prerequisites}
            )

    extra_details = {
        "checked_stf_study_id_lifecycle_pair_count": len(compared_pairs),
        "stf_study_id_lifecycle_mismatches": mismatches,
        "stf_study_id_lifecycle_prerequisites": prerequisite_records,
    }
    if not stf_documents:
        return (
            "na",
            "No STF XML documents were available in module 4/5 STF zones, so STF study-id lifecycle checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if not lifecycle_documents:
        return (
            "na",
            "No index.xml lifecycle metadata was available, so STF study-id consistency needs lifecycle prerequisite evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_CITATION,
                match_strength="stf_study_id_lifecycle_prerequisite_missing",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if mismatches:
        return (
            "warn",
            "Detected STF lifecycle pairs whose study-identifier study-id values differ.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_CITATION,
                match_strength="stf_study_id_lifecycle_mismatch",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if not compared_pairs:
        return (
            "na",
            "No local STF lifecycle pairs had both current and modified-file STF XML documents with unique non-empty study-id values.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_CITATION,
                match_strength="stf_study_id_lifecycle_prerequisite_missing",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated {len(compared_pairs)} STF lifecycle study-id pair(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_STUDY_ID_LIFECYCLE_CITATION,
            match_strength="stf_study_id_lifecycle_consistent",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_valid_values_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_xml_documents(material_contract)
    file_tag_values, category_values_by_name, valid_values_source_documents = _build_stf_valid_values_lookup()
    invalid_file_tag_values: list[dict[str, Any]] = []
    invalid_category_values: list[dict[str, Any]] = []
    unclassified_category_values: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    comparable_value_count = 0

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        attribute_records = list(document.get("ectd_attribute_records") or [])
        name_attributes_by_pointer: dict[str, str] = {}
        for attribute in attribute_records:
            if _normalize_xml_name_for_rules(attribute.get("normalized_attribute_name") or attribute.get("attribute_name")) != "name":
                continue
            element_pointer = str(attribute.get("element_pointer") or "").strip()
            value = _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
            if element_pointer and value:
                name_attributes_by_pointer[element_pointer] = value

        document_invalid_file_tags: list[dict[str, Any]] = []
        document_invalid_categories: list[dict[str, Any]] = []
        document_unclassified_categories: list[dict[str, Any]] = []

        for element in element_records:
            element_name = _normalize_xml_name_for_rules(
                element.get("element_normalized_name") or element.get("element_local_tag")
            )
            element_pointer = str(element.get("element_pointer") or "").strip()
            if element_name == "filetag":
                tag_value = name_attributes_by_pointer.get(element_pointer, "")
                if not tag_value:
                    continue
                comparable_value_count += 1
                if tag_value in file_tag_values:
                    continue
                issue = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "element_pointer": element_pointer,
                    "value": tag_value,
                }
                invalid_file_tag_values.append(issue)
                document_invalid_file_tags.append(issue)
            elif element_name == "category":
                category_name = name_attributes_by_pointer.get(element_pointer, "")
                category_value = _normalize_fact_value(element.get("element_text"))
                if not category_name or not category_value:
                    continue
                comparable_value_count += 1
                allowed_values = category_values_by_name.get(category_name.lower())
                issue = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "element_pointer": element_pointer,
                    "name": category_name,
                    "value": category_value,
                }
                if allowed_values is None:
                    unclassified_category_values.append(issue)
                    document_unclassified_categories.append(issue)
                    continue
                if category_value in allowed_values:
                    continue
                invalid_category_values.append(issue)
                document_invalid_categories.append(issue)

        if document_invalid_file_tags or document_invalid_categories:
            warning_documents.append(
                {
                    **document,
                    "invalid_file_tag_values": document_invalid_file_tags,
                    "invalid_category_values": document_invalid_categories,
                }
            )
        elif document_unclassified_categories:
            warning_documents.append(
                {
                    **document,
                    "unclassified_category_values": document_unclassified_categories,
                }
            )
        elif comparable_value_count:
            passing_documents.append(document)

    extra_details = {
        "checked_stf_valid_value_count": comparable_value_count,
        "stf_file_tag_invalid_values": invalid_file_tag_values,
        "stf_category_invalid_values": invalid_category_values,
        "stf_category_unclassified_values": unclassified_category_values,
        "stf_valid_values_source_documents": valid_values_source_documents,
    }
    if not stf_documents:
        return (
            "na",
            "No STF XML documents were available in module 4/5 STF zones, so valid-values checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if not file_tag_values and not category_values_by_name:
        return (
            "na",
            "The local STF valid-values bundle was not available, so tag/category value checks need valid-values.xml prerequisite evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_CITATION,
                match_strength="valid_values_bundle_missing",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if invalid_file_tag_values or invalid_category_values:
        return (
            "warn",
            "Detected STF file-tag or category values that are not present in local valid-values.xml.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_CITATION,
                match_strength="stf_valid_values_invalid",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if unclassified_category_values:
        return (
            "na",
            "STF category values were present, but their category names were not classified in local valid-values.xml.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_CITATION,
                match_strength="stf_category_name_unclassified",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if comparable_value_count == 0:
        return (
            "na",
            "No comparable STF file-tag name attributes or named category values were available for valid-values checks.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated {comparable_value_count} STF file-tag/category value(s) against local valid-values.xml.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_VALID_VALUES_CITATION,
            match_strength="stf_valid_values_present",
            matched_documents=passing_documents + valid_values_source_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_leaf_reference_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_xml_documents(material_contract)
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in stf_documents:
        leaf_pointers = [
            str(record.get("element_pointer") or "").strip()
            for record in document.get("ectd_element_records", []) or []
            if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
            == "leaf"
            and str(record.get("element_pointer") or "").strip()
        ]
        if leaf_pointers:
            passing_documents.append(
                {
                    **document,
                    "leaf_reference_count": len(leaf_pointers),
                    "leaf_reference_pointers": leaf_pointers,
                }
            )
            continue
        warning_documents.append(
            {
                **document,
                "leaf_reference_count": 0,
                "leaf_reference_pointers": [],
            }
        )

    extra_details = {
        "stf_leaf_reference_missing_documents": warning_documents,
        "checked_stf_leaf_reference_document_count": len(stf_documents),
    }
    if not stf_documents:
        return (
            "na",
            "No STF XML documents were available in module 4/5 STF zones, so STF leaf-reference checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if warning_documents:
        return (
            "warn",
            "Detected STF XML documents that do not reference any leaf element.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_CITATION,
                match_strength="stf_leaf_reference_missing",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated at least one leaf reference for {len(stf_documents)} STF XML document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_LEAF_REFERENCE_CITATION,
            match_strength="stf_leaf_reference_present",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _is_strongly_classifiable_stf_document(document: dict[str, Any]) -> bool:
    filename = str(document.get("filename") or "").strip()
    source_path = str(document.get("source_path") or "").strip()
    element_records = list(document.get("ectd_element_records") or [])
    return (
        _is_stf_xml_filename(filename)
        and _is_stf_xml_source_path(source_path)
        and _is_stf_like_xml_document(element_records)
    )


def _local_path_key(path: Path | None) -> str:
    if path is None:
        return ""
    try:
        return os.path.normcase(os.path.normpath(str(path.resolve())))
    except OSError:
        return ""


def _resolve_stf_leaf_href_candidates(source_path: str, href: str) -> list[Path]:
    normalized_href = unquote(str(href or "").strip()).replace("\\", "/")
    if not normalized_href or "://" in normalized_href or normalized_href.startswith("#"):
        return []
    try:
        source_file = Path(source_path).resolve()
    except OSError:
        return []
    candidates: list[Path] = []
    try:
        candidates.append((source_file.parent / PurePosixPath(normalized_href)).resolve())
    except OSError:
        pass
    sequence_root = _find_ectd_sequence_root_for_file_path(source_path)
    if sequence_root is not None:
        try:
            candidates.append((sequence_root / PurePosixPath(normalized_href)).resolve())
        except OSError:
            pass
    unique_candidates: list[Path] = []
    seen_keys: set[str] = set()
    for candidate in candidates:
        key = _local_path_key(candidate)
        if not key or key in seen_keys:
            continue
        seen_keys.add(key)
        unique_candidates.append(candidate)
    return unique_candidates


def _summarize_stf_leaf_reference(
    *,
    document: dict[str, Any],
    leaf_pointer: str,
    href: str,
    target_source_path: str = "",
    reason: str = "",
) -> dict[str, Any]:
    row = {
        "filename": str(document.get("filename") or "").strip(),
        "source_path": str(document.get("source_path") or "").strip(),
        "leaf_pointer": leaf_pointer,
        "leaf_href": href,
    }
    if target_source_path:
        row["target_source_path"] = target_source_path
    if reason:
        row["reason"] = reason
    return row


def _evaluate_ectd_stf_no_stf_reference_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    xml_documents: list[dict[str, Any]] = []
    for document in documents:
        filename = str(document.get("filename") or "").strip()
        if not _is_stf_xml_filename(filename):
            continue
        metadata = dict(document.get("ectd_submission_metadata") or {})
        xml_documents.append(
            {
                **document,
                "ectd_element_records": list(metadata.get("ectd_element_records") or []),
                "ectd_attribute_records": list(metadata.get("ectd_attribute_records") or []),
            }
        )

    strong_stf_documents = [
        document for document in xml_documents if _is_strongly_classifiable_stf_document(document)
    ]
    strong_stf_documents_by_path = {
        key: document
        for document in strong_stf_documents
        for key in [_local_path_key(Path(str(document.get("source_path") or "")))]
        if key
    }

    invalid_references: list[dict[str, Any]] = []
    checked_references: list[dict[str, Any]] = []
    prerequisite_references: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []

    for document in strong_stf_documents:
        source_path = str(document.get("source_path") or "").strip()
        source_key = _local_path_key(Path(source_path))
        attribute_records = list(document.get("ectd_attribute_records") or [])
        leaf_href_attributes = [
            attribute
            for attribute in attribute_records
            if _normalize_xml_name_for_rules(attribute.get("element_normalized_name") or attribute.get("element_local_tag"))
            == "leaf"
            and _normalize_xml_name_for_rules(attribute.get("normalized_attribute_name") or attribute.get("attribute_name"))
            == "href"
            and _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
        ]

        document_invalid: list[dict[str, Any]] = []
        document_checked: list[dict[str, Any]] = []
        document_prerequisites: list[dict[str, Any]] = []
        for attribute in leaf_href_attributes:
            href = _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
            leaf_pointer = str(attribute.get("element_pointer") or "").strip()
            normalized_href = _normalize_ectd_rule_path(href)
            target_filename = normalized_href.rsplit("/", 1)[-1]
            if target_filename and not target_filename.endswith(".xml"):
                checked = _summarize_stf_leaf_reference(
                    document=document,
                    leaf_pointer=leaf_pointer,
                    href=href,
                    reason="target_not_xml",
                )
                document_checked.append(checked)
                checked_references.append(checked)
                continue
            if target_filename == "define.xml":
                checked = _summarize_stf_leaf_reference(
                    document=document,
                    leaf_pointer=leaf_pointer,
                    href=href,
                    reason="target_define_xml_not_stf",
                )
                document_checked.append(checked)
                checked_references.append(checked)
                continue

            candidates = _resolve_stf_leaf_href_candidates(source_path, href)
            matching_stf_document: dict[str, Any] | None = None
            for candidate in candidates:
                candidate_key = _local_path_key(candidate)
                if not candidate_key or candidate_key == source_key:
                    continue
                if candidate_key in strong_stf_documents_by_path:
                    matching_stf_document = strong_stf_documents_by_path[candidate_key]
                    break
            if matching_stf_document is not None:
                issue = _summarize_stf_leaf_reference(
                    document=document,
                    leaf_pointer=leaf_pointer,
                    href=href,
                    target_source_path=str(matching_stf_document.get("source_path") or "").strip(),
                    reason="target_is_stf_xml",
                )
                document_invalid.append(issue)
                invalid_references.append(issue)
                checked_references.append(issue)
                continue

            if target_filename.endswith(".xml"):
                prerequisite = _summarize_stf_leaf_reference(
                    document=document,
                    leaf_pointer=leaf_pointer,
                    href=href,
                    reason="xml_target_not_locally_classifiable_as_stf_or_non_stf",
                )
                document_prerequisites.append(prerequisite)
                prerequisite_references.append(prerequisite)
                continue

            prerequisite = _summarize_stf_leaf_reference(
                document=document,
                leaf_pointer=leaf_pointer,
                href=href,
                reason="target_href_not_classifiable",
            )
            document_prerequisites.append(prerequisite)
            prerequisite_references.append(prerequisite)

        if document_invalid:
            warning_documents.append({**document, "invalid_stf_to_stf_references": document_invalid})
        elif document_checked:
            passing_documents.append({**document, "checked_stf_leaf_references": document_checked})
        elif document_prerequisites:
            prerequisite_documents.append({**document, "stf_reference_prerequisites": document_prerequisites})

    extra_details = {
        "checked_stf_leaf_references": checked_references,
        "invalid_stf_to_stf_references": invalid_references,
        "stf_reference_prerequisites": prerequisite_references,
    }

    if not strong_stf_documents:
        return (
            "na",
            "No locally classifiable STF XML documents were available, so STF-to-STF reference checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if warning_documents:
        return (
            "warn",
            "Detected STF XML leaf references that resolve to another locally classifiable STF XML document.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_CITATION,
                match_strength="stf_references_another_stf",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if checked_references:
        return (
            "pass",
            f"Validated {len(checked_references)} STF leaf reference(s) without locally detected STF-to-STF targets.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_CITATION,
                match_strength="stf_does_not_reference_another_stf",
                matched_documents=passing_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "na",
        "STF XML documents were present, but their leaf references could not be classified against local STF XML targets.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_NO_STF_REFERENCE_CITATION,
            match_strength="stf_reference_target_prerequisite_missing",
            matched_documents=prerequisite_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_directory_location_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_like_xml_documents(material_contract)
    invalid_documents: list[dict[str, Any]] = []
    unknown_documents: list[dict[str, Any]] = []
    allowed_documents: list[dict[str, Any]] = []

    for document in stf_documents:
        source_path = str(document.get("source_path") or "").strip()
        classification, reason = _classify_ectd_stf_directory_location(source_path)
        document_with_location = {
            **document,
            "directory_location_classification": classification,
            "directory_location_reason": reason,
        }
        if classification == "invalid":
            invalid_documents.append(document_with_location)
        elif classification == "allowed":
            allowed_documents.append(document_with_location)
        else:
            unknown_documents.append(document_with_location)

    extra_details = {
        "stf_directory_location_invalid_documents": invalid_documents,
        "stf_directory_location_unknown_documents": unknown_documents,
        "checked_stf_directory_location_document_count": len(stf_documents),
    }
    if not stf_documents:
        return (
            "na",
            "No STF-like XML documents were available, so STF directory-location checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if invalid_documents:
        return (
            "warn",
            "Detected STF XML files outside the allowed Module 4 4.2.x or Module 5 5.3.1.x-5.3.5.x locations.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_CITATION,
                match_strength="stf_directory_location_invalid",
                matched_documents=invalid_documents,
                extra_details=extra_details,
            ),
        )
    if not allowed_documents:
        return (
            "na",
            "STF-like XML documents were present, but their module directory could not be classified reliably.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_CITATION,
                match_strength="stf_directory_location_unclassified",
                matched_documents=unknown_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated STF directory location for {len(allowed_documents)} STF XML document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DIRECTORY_LOCATION_CITATION,
            match_strength="stf_directory_location_allowed",
            matched_documents=allowed_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_doc_content_file_tag_count_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_REQUIREMENT_ID)
    stf_documents = _collect_ectd_stf_xml_documents(material_contract)
    checked_doc_content_count = 0
    invalid_issues: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        doc_content_records = [
            record
            for record in element_records
            if _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
            == "doccontent"
        ]
        document_issues: list[dict[str, Any]] = []
        for doc_content_record in doc_content_records:
            checked_doc_content_count += 1
            doc_content_pointer = str(doc_content_record.get("element_pointer") or "").strip()
            file_tag_records = [
                record
                for record in element_records
                if str(record.get("parent_pointer") or "").strip() == doc_content_pointer
                and _normalize_xml_name_for_rules(record.get("element_normalized_name") or record.get("element_local_tag"))
                == "filetag"
            ]
            if len(file_tag_records) == 1:
                continue
            issue = {
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "doc_content_pointer": doc_content_pointer,
                "file_tag_count": len(file_tag_records),
                "file_tag_pointers": [
                    str(record.get("element_pointer") or "").strip()
                    for record in file_tag_records
                    if str(record.get("element_pointer") or "").strip()
                ],
            }
            document_issues.append(issue)
            invalid_issues.append(issue)
        if document_issues:
            warning_documents.append(
                {
                    **document,
                    "doc_content_file_tag_count_issues": document_issues,
                }
            )
        elif doc_content_records:
            passing_documents.append(
                {
                    **document,
                    "checked_doc_content_count": len(doc_content_records),
                }
            )

    extra_details = {
        "checked_stf_doc_content_count": checked_doc_content_count,
        "stf_doc_content_file_tag_count_issues": invalid_issues,
    }
    if not stf_documents:
        return (
            "na",
            "No STF XML documents were available in module 4/5 STF zones, so doc-content file-tag count checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if checked_doc_content_count == 0:
        return (
            "na",
            "No STF doc-content elements were available, so doc-content file-tag count checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if invalid_issues:
        return (
            "warn",
            "Detected STF doc-content elements that do not contain exactly one direct file-tag child.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_CITATION,
                match_strength="stf_doc_content_file_tag_count_invalid",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated exactly one direct file-tag child for {checked_doc_content_count} STF doc-content element(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DOC_CONTENT_FILE_TAG_COUNT_CITATION,
            match_strength="stf_doc_content_file_tag_count_valid",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _is_module5_stf_source_path(source_path: str) -> bool:
    normalized_path = str(source_path or "").strip().replace("\\", "/").lower()
    comparable_path = f"/{normalized_path.lstrip('/')}"
    return "/m5/53" in comparable_path or "/m5/5-3" in comparable_path


def _classify_stf_dataset_leaf_href(href: str) -> tuple[str, set[str]]:
    normalized_href = str(href or "").strip().replace("\\", "/").lower()
    filename = normalized_href.rsplit("/", 1)[-1]
    if filename.endswith(".xpt"):
        return "xpt_dataset", _ECTD_STF_XPT_DATASET_FILE_TAGS
    if filename == "define.xml":
        return "define_xml", _ECTD_STF_DEFINE_XML_DATASET_FILE_TAGS
    return "", set()


def _evaluate_ectd_stf_dataset_file_tag_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_REQUIREMENT_ID)
    stf_documents = [
        document
        for document in _collect_ectd_stf_xml_documents(material_contract)
        if _is_module5_stf_source_path(str(document.get("source_path") or ""))
    ]
    invalid_values: list[dict[str, Any]] = []
    prerequisite_items: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_count = 0

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        attribute_records = list(document.get("ectd_attribute_records") or [])
        attributes_by_element: dict[str, dict[str, str]] = {}
        for attribute in attribute_records:
            element_pointer = str(attribute.get("element_pointer") or "").strip()
            attribute_name = _normalize_xml_name_for_rules(
                attribute.get("normalized_attribute_name") or attribute.get("attribute_name")
            )
            value = _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
            if element_pointer and attribute_name:
                attributes_by_element.setdefault(element_pointer, {})[attribute_name] = value

        doc_content_records = [
            element
            for element in element_records
            if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
            == "doccontent"
            and str(element.get("element_pointer") or "").strip()
        ]
        document_invalid_values: list[dict[str, Any]] = []
        document_prerequisites: list[dict[str, Any]] = []
        document_checked_count = 0

        for doc_content in doc_content_records:
            doc_content_pointer = str(doc_content.get("element_pointer") or "").strip()
            child_elements = [
                element
                for element in element_records
                if str(element.get("parent_pointer") or "").strip() == doc_content_pointer
            ]
            file_tag_records = [
                element
                for element in child_elements
                if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
                == "filetag"
            ]
            leaf_records = [
                element
                for element in child_elements
                if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
                == "leaf"
            ]
            comparable_leafs: list[dict[str, Any]] = []
            for leaf in leaf_records:
                leaf_pointer = str(leaf.get("element_pointer") or "").strip()
                href = attributes_by_element.get(leaf_pointer, {}).get("href", "")
                dataset_kind, allowed_tags = _classify_stf_dataset_leaf_href(href)
                if not dataset_kind:
                    continue
                comparable_leafs.append(
                    {
                        "href": href,
                        "dataset_kind": dataset_kind,
                        "allowed_file_tags": sorted(allowed_tags),
                    }
                )
            if not comparable_leafs:
                continue

            file_tag_names = [
                attributes_by_element.get(str(record.get("element_pointer") or "").strip(), {}).get("name", "")
                for record in file_tag_records
            ]
            file_tag_names = [value for value in file_tag_names if value]
            if len(file_tag_names) != 1:
                prerequisite = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "doc_content_pointer": doc_content_pointer,
                    "file_tag_count": len(file_tag_names),
                    "dataset_leaf_hrefs": [leaf["href"] for leaf in comparable_leafs],
                    "reason": "unique_file_tag_name_required",
                }
                prerequisite_items.append(prerequisite)
                document_prerequisites.append(prerequisite)
                continue

            file_tag_name = file_tag_names[0]
            for comparable_leaf in comparable_leafs:
                checked_count += 1
                document_checked_count += 1
                allowed_tags = set(comparable_leaf["allowed_file_tags"])
                if file_tag_name in allowed_tags:
                    continue
                issue = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "doc_content_pointer": doc_content_pointer,
                    "href": comparable_leaf["href"],
                    "dataset_kind": comparable_leaf["dataset_kind"],
                    "file_tag": file_tag_name,
                    "allowed_file_tags": comparable_leaf["allowed_file_tags"],
                }
                invalid_values.append(issue)
                document_invalid_values.append(issue)

        if document_invalid_values:
            warning_documents.append({**document, "invalid_dataset_file_tags": document_invalid_values})
        elif document_checked_count:
            passing_documents.append(document)
        elif document_prerequisites:
            warning_documents.append({**document, "dataset_file_tag_prerequisites": document_prerequisites})

    extra_details = {
        "checked_stf_dataset_file_tag_count": checked_count,
        "stf_dataset_file_tag_invalid_values": invalid_values,
        "stf_dataset_file_tag_prerequisites": prerequisite_items,
        "xpt_allowed_file_tags": sorted(_ECTD_STF_XPT_DATASET_FILE_TAGS),
        "define_xml_allowed_file_tags": sorted(_ECTD_STF_DEFINE_XML_DATASET_FILE_TAGS),
    }
    if not stf_documents:
        return (
            "na",
            "No Module 5 STF XML documents were available, so clinical dataset STF file-tag checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if invalid_values:
        return (
            "warn",
            "Detected Module 5 clinical dataset STF references whose file-tag is not allowed for the referenced dataset file type.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_CITATION,
                match_strength="stf_dataset_file_tag_invalid",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if checked_count == 0:
        return (
            "na",
            "No comparable Module 5 STF dataset references with a unique file-tag were available for 5.18 checks.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_CITATION,
                match_strength="stf_dataset_file_tag_prerequisite_missing",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated {checked_count} Module 5 STF dataset file-tag reference(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_FILE_TAG_CITATION,
            match_strength="stf_dataset_file_tag_valid",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _dataset_name_from_stf_href(href: str) -> str:
    normalized_href = str(href or "").strip().replace("\\", "/").lower()
    filename = normalized_href.rsplit("/", 1)[-1]
    if "." in filename:
        filename = filename.rsplit(".", 1)[0]
    return filename


def _evaluate_ectd_stf_dataset_required_files_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_REQUIREMENT_ID)
    stf_documents = [
        document
        for document in _collect_ectd_stf_xml_documents(material_contract)
        if _is_module5_stf_source_path(str(document.get("source_path") or ""))
    ]
    missing_items: list[dict[str, Any]] = []
    prerequisite_items: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_family_count = 0

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        attribute_records = list(document.get("ectd_attribute_records") or [])
        attributes_by_element: dict[str, dict[str, str]] = {}
        for attribute in attribute_records:
            element_pointer = str(attribute.get("element_pointer") or "").strip()
            attribute_name = _normalize_xml_name_for_rules(
                attribute.get("normalized_attribute_name") or attribute.get("attribute_name")
            )
            value = _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
            if element_pointer and attribute_name:
                attributes_by_element.setdefault(element_pointer, {})[attribute_name] = value

        families = {
            "data_tabulation": {
                "dataset_names": set(),
                "dataset_hrefs": [],
                "definition_hrefs": [],
                "required_dataset": "dm",
                "required_dataset_item": "dm_dataset",
                "required_definition_item": "data_definition",
            },
            "analysis": {
                "dataset_names": set(),
                "dataset_hrefs": [],
                "definition_hrefs": [],
                "required_dataset": "adsl",
                "required_dataset_item": "adsl_dataset",
                "required_definition_item": "data_definition",
            },
        }
        document_prerequisites: list[dict[str, Any]] = []

        for doc_content in element_records:
            if (
                _normalize_xml_name_for_rules(doc_content.get("element_normalized_name") or doc_content.get("element_local_tag"))
                != "doccontent"
            ):
                continue
            doc_content_pointer = str(doc_content.get("element_pointer") or "").strip()
            if not doc_content_pointer:
                continue
            child_elements = [
                element
                for element in element_records
                if str(element.get("parent_pointer") or "").strip() == doc_content_pointer
            ]
            file_tag_names = [
                attributes_by_element.get(str(element.get("element_pointer") or "").strip(), {}).get("name", "")
                for element in child_elements
                if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
                == "filetag"
            ]
            file_tag_names = [value for value in file_tag_names if value]
            leaf_hrefs = [
                attributes_by_element.get(str(element.get("element_pointer") or "").strip(), {}).get("href", "")
                for element in child_elements
                if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
                == "leaf"
            ]
            leaf_hrefs = [href for href in leaf_hrefs if href]
            if len(file_tag_names) != 1:
                if leaf_hrefs:
                    prerequisite = {
                        "filename": str(document.get("filename") or "").strip(),
                        "source_path": str(document.get("source_path") or "").strip(),
                        "doc_content_pointer": doc_content_pointer,
                        "file_tag_count": len(file_tag_names),
                        "leaf_hrefs": leaf_hrefs,
                        "reason": "unique_file_tag_name_required",
                    }
                    prerequisite_items.append(prerequisite)
                    document_prerequisites.append(prerequisite)
                continue

            file_tag_name = file_tag_names[0]
            if file_tag_name in _ECTD_STF_DATA_TABULATION_DATASET_FILE_TAGS:
                for href in leaf_hrefs:
                    if _classify_stf_dataset_leaf_href(href)[0] == "xpt_dataset":
                        families["data_tabulation"]["dataset_hrefs"].append(href)
                        families["data_tabulation"]["dataset_names"].add(_dataset_name_from_stf_href(href))
            elif file_tag_name == "data-tabulation-data-definition":
                for href in leaf_hrefs:
                    if _classify_stf_dataset_leaf_href(href)[0] == "define_xml":
                        families["data_tabulation"]["definition_hrefs"].append(href)
            elif file_tag_name in _ECTD_STF_ANALYSIS_DATASET_FILE_TAGS:
                for href in leaf_hrefs:
                    if _classify_stf_dataset_leaf_href(href)[0] == "xpt_dataset":
                        families["analysis"]["dataset_hrefs"].append(href)
                        families["analysis"]["dataset_names"].add(_dataset_name_from_stf_href(href))
            elif file_tag_name == "analysis-data-definition":
                for href in leaf_hrefs:
                    if _classify_stf_dataset_leaf_href(href)[0] == "define_xml":
                        families["analysis"]["definition_hrefs"].append(href)

        document_missing_items: list[dict[str, Any]] = []
        checked_families: list[str] = []
        for family_name, family in families.items():
            if not family["dataset_hrefs"] and not family["definition_hrefs"]:
                continue
            checked_family_count += 1
            checked_families.append(family_name)
            if family["required_dataset"] not in family["dataset_names"]:
                issue = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "dataset_family": family_name,
                    "missing_item": family["required_dataset_item"],
                    "observed_dataset_names": sorted(family["dataset_names"]),
                    "observed_dataset_hrefs": list(family["dataset_hrefs"]),
                    "observed_definition_hrefs": list(family["definition_hrefs"]),
                }
                missing_items.append(issue)
                document_missing_items.append(issue)
            if not family["definition_hrefs"]:
                issue = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "dataset_family": family_name,
                    "missing_item": family["required_definition_item"],
                    "observed_dataset_names": sorted(family["dataset_names"]),
                    "observed_dataset_hrefs": list(family["dataset_hrefs"]),
                    "observed_definition_hrefs": [],
                }
                missing_items.append(issue)
                document_missing_items.append(issue)

        if document_missing_items:
            warning_documents.append({**document, "dataset_package_missing_items": document_missing_items})
        elif checked_families:
            passing_documents.append({**document, "checked_dataset_families": checked_families})
        elif document_prerequisites:
            warning_documents.append({**document, "dataset_package_prerequisites": document_prerequisites})

    extra_details = {
        "checked_stf_dataset_family_count": checked_family_count,
        "stf_dataset_package_missing_items": missing_items,
        "stf_dataset_package_prerequisites": prerequisite_items,
    }
    if not stf_documents:
        return (
            "na",
            "No Module 5 STF XML documents were available, so clinical dataset required-file checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if missing_items:
        return (
            "warn",
            "Detected Module 5 STF clinical dataset package families missing required dm/adsl dataset or data-definition evidence.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_CITATION,
                match_strength="stf_dataset_package_required_files_missing",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if checked_family_count == 0:
        return (
            "na",
            "No comparable raw or analysis dataset family evidence was available for 5.19 checks.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_CITATION,
                match_strength="stf_dataset_package_prerequisite_missing",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated required dataset and data-definition evidence for {checked_family_count} STF dataset family group(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_REQUIRED_FILES_CITATION,
            match_strength="stf_dataset_package_required_files_present",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_dataset_unique_names_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_REQUIREMENT_ID)
    stf_documents = [
        document
        for document in _collect_ectd_stf_xml_documents(material_contract)
        if _is_module5_stf_source_path(str(document.get("source_path") or ""))
    ]
    duplicate_names: list[dict[str, Any]] = []
    prerequisite_items: list[dict[str, Any]] = []
    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    checked_dataset_count = 0

    for document in stf_documents:
        element_records = list(document.get("ectd_element_records") or [])
        attribute_records = list(document.get("ectd_attribute_records") or [])
        attributes_by_element: dict[str, dict[str, str]] = {}
        for attribute in attribute_records:
            element_pointer = str(attribute.get("element_pointer") or "").strip()
            attribute_name = _normalize_xml_name_for_rules(
                attribute.get("normalized_attribute_name") or attribute.get("attribute_name")
            )
            value = _normalize_fact_value(attribute.get("normalized_value") or attribute.get("raw_value"))
            if element_pointer and attribute_name:
                attributes_by_element.setdefault(element_pointer, {})[attribute_name] = value

        dataset_entries_by_name: dict[str, list[dict[str, Any]]] = {}
        document_prerequisites: list[dict[str, Any]] = []
        study_id_values, study_id_blank_pointers = _collect_stf_study_identifier_study_id_values(document)

        for doc_content in element_records:
            if (
                _normalize_xml_name_for_rules(doc_content.get("element_normalized_name") or doc_content.get("element_local_tag"))
                != "doccontent"
            ):
                continue
            doc_content_pointer = str(doc_content.get("element_pointer") or "").strip()
            if not doc_content_pointer:
                continue
            child_elements = [
                element
                for element in element_records
                if str(element.get("parent_pointer") or "").strip() == doc_content_pointer
            ]
            file_tag_names = [
                attributes_by_element.get(str(element.get("element_pointer") or "").strip(), {}).get("name", "")
                for element in child_elements
                if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
                == "filetag"
            ]
            file_tag_names = [value for value in file_tag_names if value]
            leaf_hrefs = [
                attributes_by_element.get(str(element.get("element_pointer") or "").strip(), {}).get("href", "")
                for element in child_elements
                if _normalize_xml_name_for_rules(element.get("element_normalized_name") or element.get("element_local_tag"))
                == "leaf"
            ]
            leaf_hrefs = [href for href in leaf_hrefs if href]
            xpt_hrefs = [href for href in leaf_hrefs if _classify_stf_dataset_leaf_href(href)[0] == "xpt_dataset"]
            if not xpt_hrefs:
                continue
            if len(file_tag_names) != 1:
                prerequisite = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "doc_content_pointer": doc_content_pointer,
                    "file_tag_count": len(file_tag_names),
                    "leaf_hrefs": xpt_hrefs,
                    "reason": "unique_dataset_file_tag_name_required",
                }
                prerequisite_items.append(prerequisite)
                document_prerequisites.append(prerequisite)
                continue
            file_tag_name = file_tag_names[0]
            if file_tag_name not in _ECTD_STF_XPT_DATASET_FILE_TAGS:
                prerequisite = {
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "doc_content_pointer": doc_content_pointer,
                    "file_tag": file_tag_name,
                    "leaf_hrefs": xpt_hrefs,
                    "reason": "dataset_file_tag_required_for_dataset_name_comparison",
                }
                prerequisite_items.append(prerequisite)
                document_prerequisites.append(prerequisite)
                continue
            for href in xpt_hrefs:
                dataset_name = _dataset_name_from_stf_href(href)
                if not dataset_name:
                    continue
                checked_dataset_count += 1
                dataset_entries_by_name.setdefault(dataset_name, []).append(
                    {
                        "doc_content_pointer": doc_content_pointer,
                        "href": href,
                        "file_tag": file_tag_name,
                    }
                )

        document_duplicate_names: list[dict[str, Any]] = []
        for dataset_name in sorted(dataset_entries_by_name):
            entries = dataset_entries_by_name[dataset_name]
            if len(entries) < 2:
                continue
            issue = {
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "study_id_values": study_id_values,
                "study_id_blank_pointers": study_id_blank_pointers,
                "dataset_name": dataset_name,
                "dataset_hrefs": [entry["href"] for entry in entries],
                "dataset_file_tags": [entry["file_tag"] for entry in entries],
                "doc_content_pointers": [entry["doc_content_pointer"] for entry in entries],
            }
            duplicate_names.append(issue)
            document_duplicate_names.append(issue)

        if document_duplicate_names:
            warning_documents.append({**document, "duplicate_dataset_names": document_duplicate_names})
        elif dataset_entries_by_name:
            passing_documents.append(
                {
                    **document,
                    "checked_dataset_names": sorted(dataset_entries_by_name),
                    "study_id_values": study_id_values,
                }
            )
        elif document_prerequisites:
            warning_documents.append({**document, "dataset_name_prerequisites": document_prerequisites})

    extra_details = {
        "checked_stf_dataset_name_count": checked_dataset_count,
        "stf_duplicate_dataset_names": duplicate_names,
        "stf_dataset_name_prerequisites": prerequisite_items,
        "dataset_name_identity": "lowercase_xpt_filename_stem",
        "same_study_boundary": "single_module5_stf_xml_document",
    }
    if not stf_documents:
        return (
            "na",
            "No Module 5 STF XML documents were available, so duplicate dataset-name checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if duplicate_names:
        return (
            "warn",
            "Detected duplicate .xpt dataset names within a Module 5 STF study document.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_CITATION,
                match_strength="stf_duplicate_dataset_names_detected",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    if checked_dataset_count == 0:
        return (
            "na",
            "No comparable Module 5 STF .xpt dataset entries were available for duplicate dataset-name checks.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_CITATION,
                match_strength="stf_dataset_name_prerequisite_missing",
                matched_documents=warning_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "pass",
        f"Validated {checked_dataset_count} Module 5 STF dataset name reference(s) for duplicates.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_DATASET_UNIQUE_NAMES_CITATION,
            match_strength="stf_dataset_names_unique",
            matched_documents=passing_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_m537_prohibited_when_stf_used_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in documents
        if list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
    ]

    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    prerequisite_documents: list[dict[str, Any]] = []
    stf_usage_leaf_hrefs: list[str] = []
    m537_leaf_hrefs: list[str] = []

    for document in applicable_documents:
        records = list(document["ectd_leaf_records"])
        document_stf_usage_records = [
            record
            for record in records
            if _is_within_stf_required_zone(record) and _has_explicit_stf_parent_tag_signal(record)
        ]
        document_m537_records = [record for record in records if _is_m537_case_report_form_leaf(record)]
        document_stf_hrefs = [
            str(record.get("href") or "").strip()
            for record in document_stf_usage_records
            if str(record.get("href") or "").strip()
        ]
        document_m537_hrefs = [
            str(record.get("href") or "").strip()
            for record in document_m537_records
            if str(record.get("href") or "").strip()
        ]
        if document_stf_hrefs:
            stf_usage_leaf_hrefs.extend(document_stf_hrefs)
        if document_m537_hrefs:
            m537_leaf_hrefs.extend(document_m537_hrefs)

        if document_stf_usage_records and document_m537_records:
            failing_documents.append(
                {
                    **document,
                    "stf_usage_leaf_hrefs": _dedupe_preserve_order_strings(document_stf_hrefs),
                    "m537_leaf_hrefs": _dedupe_preserve_order_strings(document_m537_hrefs),
                }
            )
        elif document_stf_usage_records:
            passing_documents.append(
                {
                    **document,
                    "stf_usage_leaf_hrefs": _dedupe_preserve_order_strings(document_stf_hrefs),
                    "m537_leaf_hrefs": [],
                }
            )
        elif document_m537_records:
            prerequisite_documents.append(
                {
                    **document,
                    "m537_leaf_hrefs": _dedupe_preserve_order_strings(document_m537_hrefs),
                    "reason": "stf_usage_not_detected",
                }
            )

    extra_details = {
        "stf_usage_leaf_hrefs": _dedupe_preserve_order_strings(stf_usage_leaf_hrefs),
        "m537_leaf_hrefs": _dedupe_preserve_order_strings(m537_leaf_hrefs),
        "m537_prerequisite_documents": prerequisite_documents,
    }
    if not applicable_documents:
        return (
            "na",
            "No index.xml leaf records were available, so 5.3.7 case-report-form prohibition checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details=extra_details,
            ),
        )
    if failing_documents:
        return (
            "fail",
            "Detected 5.3.7 case-report-form leafs in an eCTD sequence that also uses STF structure.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_CITATION,
                match_strength="m537_leaf_present_while_stf_used",
                matched_documents=failing_documents,
                extra_details=extra_details,
            ),
        )
    if passing_documents:
        return (
            "pass",
            f"Validated {len(passing_documents)} index document(s) that use STF without 5.3.7 leafs.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_CITATION,
                match_strength="stf_used_without_m537_leafs",
                matched_documents=passing_documents,
                extra_details=extra_details,
            ),
        )
    return (
        "na",
        "No explicit STF usage was detected in index.xml leaf structure, so the 5.3.7 prohibition condition is not applicable.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_VALIDATION_STANDARD_STF_M537_PROHIBITED_CITATION,
            match_strength="stf_usage_prerequisite_missing",
            matched_documents=prerequisite_documents,
            extra_details=extra_details,
        ),
    )


def _evaluate_ectd_stf_required_zone_structure_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_ID)
    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents = [
        {
            **document,
            "ectd_leaf_records": list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or []),
        }
        for document in documents
        if list((document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records") or [])
    ]

    stf_zone_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        stf_records = [record for record in document["ectd_leaf_records"] if _is_within_stf_required_zone(record)]
        if stf_records:
            stf_zone_documents.append({**document, "ectd_leaf_records": stf_records})

    if not stf_zone_documents:
        return (
            "na",
            "No leafs were detected inside STF-required zones, so STF structure checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "direct_child_stf_required_leaf_hrefs": [],
                    "ambiguous_stf_parent_leaf_hrefs": [],
                },
            ),
        )

    warning_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    direct_child_hrefs: list[str] = []
    ambiguous_parent_hrefs: list[str] = []

    for document in stf_zone_documents:
        document_direct_child_hrefs: list[str] = []
        document_ambiguous_parent_hrefs: list[str] = []
        for record in document["ectd_leaf_records"]:
            href = str(record.get("href") or "").strip()
            if not href:
                continue
            if _is_direct_child_of_stf_section(record):
                document_direct_child_hrefs.append(href)
                direct_child_hrefs.append(href)
                continue
            if not _has_explicit_stf_parent_tag_signal(record):
                document_ambiguous_parent_hrefs.append(href)
                ambiguous_parent_hrefs.append(href)

        normalized_document = {
            **document,
            "direct_child_stf_required_leaf_hrefs": _dedupe_preserve_order_strings(document_direct_child_hrefs),
            "ambiguous_stf_parent_leaf_hrefs": _dedupe_preserve_order_strings(document_ambiguous_parent_hrefs),
        }
        if document_direct_child_hrefs or document_ambiguous_parent_hrefs:
            warning_documents.append(normalized_document)
        else:
            passing_documents.append(normalized_document)

    if warning_documents:
        if direct_child_hrefs and ambiguous_parent_hrefs:
            match_strength = "stf_structure_mixed_issues"
            summary = (
                "Detected STF-required zone leafs that are either attached directly to the section container "
                "or nested under non-explicit wrapper tags instead of clear STF study/study-report/dataset tags."
            )
        elif direct_child_hrefs:
            match_strength = "stf_structure_missing_intermediate_tag"
            summary = (
                "Detected STF-required zone leafs that are attached directly to the section container "
                "instead of a study-tag structure."
            )
        else:
            match_strength = "stf_structure_nested_without_explicit_stf_tag"
            summary = (
                "Detected STF-required zone leafs nested under generic wrapper tags rather than clear "
                "STF study/study-report/dataset parent tags."
            )
        return (
            "warn",
            summary,
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_CITATION,
                match_strength=match_strength,
                matched_documents=warning_documents,
                extra_details={
                    "direct_child_stf_required_leaf_hrefs": _dedupe_preserve_order_strings(direct_child_hrefs),
                    "ambiguous_stf_parent_leaf_hrefs": _dedupe_preserve_order_strings(ambiguous_parent_hrefs),
                },
            ),
        )

    return (
        "pass",
        f"Validated nested STF structure for {len(stf_zone_documents)} eCTD XML document(s) in STF-required zones.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_STF_REQUIRED_ZONE_STRUCTURE_REQUIREMENT_CITATION,
            match_strength="stf_structure_nested",
            matched_documents=passing_documents,
            extra_details={
                "direct_child_stf_required_leaf_hrefs": [],
                "ambiguous_stf_parent_leaf_hrefs": [],
            },
        ),
    )


def _evaluate_ectd_placeholder_document_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_ID)
    documents = list(material_contract.get("documents", []) or [])
    paragraph_index = list(material_contract.get("paragraph_index", []) or [])
    metadata_documents = _collect_ectd_submission_metadata_documents(material_contract)
    xml_documents = [
        document
        for document in metadata_documents
        if str(document.get("filename") or "").strip().lower().endswith(".xml")
    ]
    cn_regional_documents = [
        document for document in xml_documents if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
    ]
    index_documents = [
        document for document in xml_documents if str(document.get("filename") or "").strip().lower() == "index.xml"
    ]

    if not cn_regional_documents or not index_documents:
        return (
            "na",
            "Placeholder-document checks require both cn-regional.xml and index.xml.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "placeholder_documents": [],
                },
            ),
        )

    failing_documents: list[dict[str, Any]] = []
    passing_documents: list[dict[str, Any]] = []
    for cn_regional in cn_regional_documents:
        cn_source_path = str(cn_regional.get("source_path") or "").strip()
        package_root = Path(cn_source_path).resolve().parents[2] if cn_source_path else None
        if package_root is None:
            continue

        declared_hrefs: set[str] = set()
        matching_documents: list[dict[str, Any]] = []
        for xml_document in [*cn_regional_documents, *index_documents]:
            xml_source_path = str(xml_document.get("source_path") or "").strip()
            if not xml_source_path:
                continue
            try:
                xml_package_root = (
                    Path(xml_source_path).resolve().parent
                    if Path(xml_source_path).name.lower() == "index.xml"
                    else Path(xml_source_path).resolve().parents[2]
                )
            except OSError:
                continue
            if xml_package_root != package_root:
                continue
            matching_documents.append(xml_document)
            declared_hrefs.update(
                str(item or "").strip()
                for item in (xml_document.get("ectd_submission_metadata") or {}).get("ectd_leaf_hrefs", []) or []
                if str(item or "").strip()
            )

        placeholder_documents: list[dict[str, str]] = []
        evaluated_documents: list[dict[str, Any]] = []
        for document in documents:
            document_id = str(document.get("document_id") or "").strip()
            source_path = str(document.get("source_path") or "").strip()
            if not source_path:
                continue
            try:
                resolved_path = Path(source_path).resolve()
            except OSError:
                continue
            if resolved_path.suffix.lower() != ".pdf":
                continue
            try:
                relative_path = str(resolved_path.relative_to(package_root)).replace("\\", "/")
            except ValueError:
                continue
            if relative_path not in declared_hrefs:
                continue

            evaluated_documents.append(document)
            summary = dict(document.get("summary", {}) or {})
            content_evidence_count = int(summary.get("content_evidence_count", 0) or 0)
            content_unit_count = int(summary.get("content_unit_count", 0) or 0)
            if content_evidence_count <= 0 and content_unit_count <= 0:
                placeholder_documents.append(
                    {
                        "filename": str(document.get("filename") or "").strip(),
                        "relative_path": relative_path,
                        "reason": "missing_actual_content",
                    }
                )
                continue

            marker_texts: set[str] = set()
            for paragraph in paragraph_index:
                if str(paragraph.get("document_id") or "").strip() != document_id:
                    continue
                normalized_text = _normalize_placeholder_marker_text(str(paragraph.get("text") or ""))
                if normalized_text:
                    marker_texts.add(normalized_text)

            if marker_texts and marker_texts.issubset(_ECTD_PLACEHOLDER_TEXT_MARKERS):
                placeholder_documents.append(
                    {
                        "filename": str(document.get("filename") or "").strip(),
                        "relative_path": relative_path,
                        "reason": "placeholder_marker_text",
                    }
                )

        if not evaluated_documents:
            continue

        normalized_record = {
            "matched_documents": [
                {
                    "document_id": str(document.get("document_id") or "").strip(),
                    "filename": str(document.get("filename") or "").strip(),
                    "source_path": str(document.get("source_path") or "").strip(),
                    "module_label": str(document.get("module_label") or "").strip(),
                }
                for document in [*matching_documents, *evaluated_documents]
            ],
        }
        if placeholder_documents:
            failing_documents.append(
                {
                    **normalized_record,
                    "placeholder_documents": placeholder_documents,
                }
            )
        else:
            passing_documents.append(normalized_record)

    if failing_documents:
        return (
            "fail",
            "Detected declared PDF documents that appear to be placeholder documents without actual content.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_CITATION,
                match_strength="placeholder_declared_document_detected",
                matched_documents=_dedupe_documents_for_requirement_rows(failing_documents),
                extra_details={
                    "placeholder_documents": [
                        dict(item)
                        for document in failing_documents
                        for item in document.get("placeholder_documents", []) or []
                    ],
                },
            ),
        )

    if not passing_documents:
        return (
            "na",
            "No declared PDF content targets were available for placeholder-document checks.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "placeholder_documents": [],
                },
            ),
        )

    return (
        "pass",
        "Validated absence of obvious placeholder documents among declared PDF content targets.",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_PLACEHOLDER_DOCUMENT_REQUIREMENT_CITATION,
            match_strength="no_placeholder_declared_documents",
            matched_documents=_dedupe_documents_for_requirement_rows(passing_documents),
            extra_details={
                "placeholder_documents": [],
            },
        ),
    )


def _evaluate_ectd_module1_directory_alignment_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_ATTACHMENT_14_REQUIREMENT_ID)
    authoritative_lookup, authoritative_documents = _build_authoritative_module1_directory_prefix_lookup()
    if not authoritative_lookup:
        return (
            "na",
            "Attachment 1-4 authoritative module-1 directory prefixes were unavailable, so module-1 directory alignment checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "authoritative_directory_prefixes": {},
                    "checked_leaf_records": [],
                    "violating_leaf_records": [],
                },
            ),
        )

    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents: list[dict[str, Any]] = []
    for document in documents:
        filename = str(document.get("filename") or "").strip().lower()
        if filename != "cn-regional.xml":
            continue
        leaf_records = [
            dict(record)
            for record in (document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records", []) or []
            if isinstance(record, dict)
        ]
        if not leaf_records:
            continue
        applicable_documents.append({**document, "ectd_leaf_records": leaf_records})

    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml leaf records were available, so module-1 directory alignment checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=authoritative_documents,
                extra_details={
                    "authoritative_directory_prefixes": dict(sorted(authoritative_lookup.items())),
                    "checked_leaf_records": [],
                    "violating_leaf_records": [],
                },
            ),
        )

    checked_leaf_records: list[dict[str, Any]] = []
    violating_leaf_records: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        document_checked_records: list[dict[str, Any]] = []
        document_violations: list[dict[str, Any]] = []
        for record in document["ectd_leaf_records"]:
            parent_local_tag = str(record.get("parent_local_tag") or "").strip()
            href = str(record.get("href") or "").strip()
            if not parent_local_tag or not href:
                continue
            expected_directory_prefix = authoritative_lookup.get(parent_local_tag)
            if not expected_directory_prefix:
                continue
            actual_directory_prefix = _normalize_posix_dir_prefix(href).lower()
            normalized_expected_prefix = str(expected_directory_prefix).strip().lower()
            checked_record = {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "parent_local_tag": parent_local_tag,
                "href": href,
                "actual_directory_prefix": actual_directory_prefix,
                "expected_directory_prefix": normalized_expected_prefix,
            }
            document_checked_records.append(checked_record)
            checked_leaf_records.append(checked_record)
            if actual_directory_prefix != normalized_expected_prefix:
                document_violations.append(checked_record)
                violating_leaf_records.append(checked_record)
        if document_violations:
            failing_documents.append(
                {
                    **document,
                    "checked_leaf_records": document_checked_records,
                    "violating_leaf_records": document_violations,
                }
            )

    authoritative_prefixes = dict(sorted(authoritative_lookup.items()))
    matched_documents = [*applicable_documents, *authoritative_documents]
    if not checked_leaf_records:
        return (
            "na",
            "No cn-regional.xml leaf parent elements matched authoritative Attachment 1-4 module-1 elements, so directory alignment checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=matched_documents,
                extra_details={
                    "authoritative_directory_prefixes": authoritative_prefixes,
                    "checked_leaf_records": [],
                    "violating_leaf_records": [],
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected cn-regional.xml leaf directory prefixes that do not align with the authoritative Attachment 1-4 module-1 directory structure.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_REQUIREMENT_CITATION,
                match_strength="invalid_module1_leaf_directory_prefix",
                matched_documents=[*failing_documents, *authoritative_documents],
                extra_details={
                    "authoritative_directory_prefixes": authoritative_prefixes,
                    "checked_leaf_records": checked_leaf_records,
                    "violating_leaf_records": violating_leaf_records,
                },
            ),
        )

    return (
        "pass",
        f"Validated Attachment 1-4 directory-prefix alignment for {len(checked_leaf_records)} comparable cn-regional.xml leaf record(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_ATTACHMENT_14_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_ATTACHMENT_14_REQUIREMENT_CITATION,
            match_strength="valid_module1_leaf_directory_prefix",
            matched_documents=matched_documents,
            extra_details={
                "authoritative_directory_prefixes": authoritative_prefixes,
                "checked_leaf_records": checked_leaf_records,
                "violating_leaf_records": [],
            },
        ),
    )


def _evaluate_ectd_cn_regional_root_structure_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_ID)
    authoritative_root, authoritative_documents = _build_authoritative_cn_regional_root_structure()
    if not authoritative_root:
        return (
            "na",
            "Attachment 1-1 authoritative cn-regional root structure was unavailable, so cn-regional root-structure checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "expected_root_structure": {},
                    "violating_root_documents": [],
                },
            ),
        )

    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so cn-regional root-structure checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=authoritative_documents,
                extra_details={
                    "expected_root_structure": authoritative_root,
                    "violating_root_documents": [],
                },
            ),
        )

    expected_root_name = str(authoritative_root.get("name") or "").strip()
    expected_children = list(authoritative_root.get("children", []) or [])
    expected_child_names = [str(child.get("name") or "").strip() for child in expected_children if str(child.get("name") or "").strip()]

    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        if not nodes:
            failing_documents.append(
                {
                    **document,
                    "root_local_tag": "",
                    "actual_child_names": [],
                    "unexpected_child_names": [],
                    "missing_required_child_names": expected_child_names,
                    "child_count_mismatches": [],
                    "root_structure_issue": "unparseable_or_empty_xml_tree",
                }
            )
            continue

        root_node = dict(nodes[0] or {})
        root_pointer = str(root_node.get("pointer") or "").strip()
        root_local_tag = str(root_node.get("local_tag") or "").strip()
        actual_child_names = [
            str(node.get("local_tag") or "").strip()
            for node in nodes
            if _parent_xml_pointer(str(node.get("pointer") or "").strip()) == root_pointer
            and str(node.get("local_tag") or "").strip()
        ]
        actual_child_counts: dict[str, int] = {}
        for name in actual_child_names:
            actual_child_counts[name] = actual_child_counts.get(name, 0) + 1

        missing_required_child_names: list[str] = []
        child_count_mismatches: list[dict[str, Any]] = []
        for child in expected_children:
            child_name = str(child.get("name") or "").strip()
            min_occurs = int(str(child.get("min_occurs") or "1").strip() or "1")
            max_occurs_raw = str(child.get("max_occurs") or "1").strip() or "1"
            max_occurs = None if max_occurs_raw == "unbounded" else int(max_occurs_raw)
            actual_count = int(actual_child_counts.get(child_name, 0))
            if actual_count < min_occurs:
                missing_required_child_names.append(child_name)
            if actual_count < min_occurs or (max_occurs is not None and actual_count > max_occurs):
                child_count_mismatches.append(
                    {
                        "name": child_name,
                        "expected_min_occurs": min_occurs,
                        "expected_max_occurs": max_occurs_raw,
                        "actual_count": actual_count,
                    }
                )

        unexpected_child_names = sorted({name for name in actual_child_names if name not in expected_child_names})
        if (
            root_local_tag != expected_root_name
            or missing_required_child_names
            or unexpected_child_names
            or child_count_mismatches
        ):
            failing_documents.append(
                {
                    **document,
                    "root_local_tag": root_local_tag,
                    "actual_child_names": actual_child_names,
                    "unexpected_child_names": unexpected_child_names,
                    "missing_required_child_names": missing_required_child_names,
                    "child_count_mismatches": child_count_mismatches,
                    "root_structure_issue": (
                        "root_tag_mismatch"
                        if root_local_tag != expected_root_name
                        else "root_child_structure_mismatch"
                    ),
                }
            )

    if failing_documents:
        return (
            "fail",
            "Detected cn-regional.xml root structures that do not align with the authoritative Attachment 1-1 root definition.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_CITATION,
                match_strength="invalid_cn_regional_root_structure",
                matched_documents=[*failing_documents, *authoritative_documents],
                extra_details={
                    "expected_root_structure": authoritative_root,
                    "violating_root_documents": failing_documents,
                },
            ),
        )

    return (
        "pass",
        f"Validated Attachment 1-1 cn-regional root structure for {len(applicable_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_ATTACHMENT_11_ROOT_REQUIREMENT_CITATION,
            match_strength="valid_cn_regional_root_structure",
            matched_documents=[*applicable_documents, *authoritative_documents],
            extra_details={
                "expected_root_structure": authoritative_root,
                "violating_root_documents": [],
            },
        ),
    )


def _evaluate_ectd_cn_envelope_structure_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_ID)
    authoritative_fields, authoritative_documents = _build_authoritative_cn_envelope_structure()
    if not authoritative_fields:
        return (
            "na",
            "Attachment 1-1 authoritative cn-envelope structure was unavailable, so cn-envelope structure checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "expected_envelope_fields": [],
                    "violating_envelope_documents": [],
                },
            ),
        )

    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so cn-envelope structure checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=authoritative_documents,
                extra_details={
                    "expected_envelope_fields": authoritative_fields,
                    "violating_envelope_documents": [],
                },
            ),
        )

    expected_field_names = [str(field.get("name") or "").strip() for field in authoritative_fields]
    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        if not nodes:
            failing_documents.append(
                {
                    **document,
                    "actual_envelope_field_names": [],
                    "missing_required_field_names": expected_field_names,
                    "unexpected_field_names": [],
                    "field_count_mismatches": [],
                    "expected_field_order": expected_field_names,
                    "field_order_matches": False,
                    "envelope_structure_issue": "unparseable_or_empty_xml_tree",
                }
            )
            continue

        envelope_nodes = [
            dict(node)
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "cn-envelope"
        ]
        if len(envelope_nodes) != 1:
            failing_documents.append(
                {
                    **document,
                    "actual_envelope_field_names": [],
                    "missing_required_field_names": expected_field_names,
                    "unexpected_field_names": [],
                    "field_count_mismatches": [],
                    "expected_field_order": expected_field_names,
                    "field_order_matches": False,
                    "envelope_structure_issue": "cn_envelope_count_mismatch",
                    "actual_envelope_count": len(envelope_nodes),
                }
            )
            continue

        envelope_pointer = str(envelope_nodes[0].get("pointer") or "").strip()
        actual_field_names = [
            str(node.get("local_tag") or "").strip()
            for node in nodes
            if _parent_xml_pointer(str(node.get("pointer") or "").strip()) == envelope_pointer
            and str(node.get("local_tag") or "").strip()
        ]
        actual_field_counts: dict[str, int] = {}
        for name in actual_field_names:
            actual_field_counts[name] = actual_field_counts.get(name, 0) + 1

        missing_required_field_names: list[str] = []
        field_count_mismatches: list[dict[str, Any]] = []
        for field in authoritative_fields:
            field_name = str(field.get("name") or "").strip()
            min_occurs = int(str(field.get("min_occurs") or "1").strip() or "1")
            max_occurs_raw = str(field.get("max_occurs") or "1").strip() or "1"
            max_occurs = None if max_occurs_raw == "unbounded" else int(max_occurs_raw)
            actual_count = int(actual_field_counts.get(field_name, 0))
            if actual_count < min_occurs:
                missing_required_field_names.append(field_name)
            if actual_count < min_occurs or (max_occurs is not None and actual_count > max_occurs):
                field_count_mismatches.append(
                    {
                        "name": field_name,
                        "expected_min_occurs": min_occurs,
                        "expected_max_occurs": max_occurs_raw,
                        "actual_count": actual_count,
                    }
                )

        unexpected_field_names = sorted({name for name in actual_field_names if name not in expected_field_names})
        field_order_matches = actual_field_names == expected_field_names
        if (
            missing_required_field_names
            or unexpected_field_names
            or field_count_mismatches
            or not field_order_matches
        ):
            failing_documents.append(
                {
                    **document,
                    "actual_envelope_field_names": actual_field_names,
                    "missing_required_field_names": missing_required_field_names,
                    "unexpected_field_names": unexpected_field_names,
                    "field_count_mismatches": field_count_mismatches,
                    "expected_field_order": expected_field_names,
                    "field_order_matches": field_order_matches,
                    "envelope_structure_issue": (
                        "field_order_mismatch"
                        if not field_order_matches and not (missing_required_field_names or unexpected_field_names or field_count_mismatches)
                        else "field_structure_mismatch"
                    ),
                }
            )

    if failing_documents:
        return (
            "fail",
            "Detected cn-envelope field structures that do not align with the authoritative Attachment 1-1 envelope definition.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_CITATION,
                match_strength="invalid_cn_envelope_structure",
                matched_documents=[*failing_documents, *authoritative_documents],
                extra_details={
                    "expected_envelope_fields": authoritative_fields,
                    "violating_envelope_documents": failing_documents,
                },
            ),
        )

    return (
        "pass",
        f"Validated Attachment 1-1 cn-envelope structure for {len(applicable_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_ATTACHMENT_11_ENVELOPE_REQUIREMENT_CITATION,
            match_strength="valid_cn_envelope_structure",
            matched_documents=[*applicable_documents, *authoritative_documents],
            extra_details={
                "expected_envelope_fields": authoritative_fields,
                "violating_envelope_documents": [],
            },
        ),
    )


def _evaluate_ectd_cn_content_top_level_structure_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_ID)
    authoritative_elements, authoritative_documents = _build_authoritative_cn_content_top_level_structure()
    if not authoritative_elements:
        return (
            "na",
            "Attachment 1-1 authoritative cn-content top-level structure was unavailable, so cn-content top-level checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "expected_content_top_level_elements": [],
                    "violating_content_documents": [],
                },
            ),
        )

    applicable_documents = [
        {
            "document_id": str(document.get("document_id") or "").strip(),
            "filename": str(document.get("filename") or "").strip(),
            "source_path": str(document.get("source_path") or "").strip(),
            "module_label": str(((document.get("classification") or {}).get("module_label")) or "").strip(),
        }
        for document in material_contract.get("documents", []) or []
        if str(document.get("filename") or "").strip().lower() == "cn-regional.xml"
        and str(document.get("source_path") or "").strip()
    ]
    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml documents were available, so cn-content top-level checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=authoritative_documents,
                extra_details={
                    "expected_content_top_level_elements": authoritative_elements,
                    "violating_content_documents": [],
                },
            ),
        )

    expected_element_names = [str(field.get("name") or "").strip() for field in authoritative_elements]
    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        source_path = Path(document["source_path"])
        try:
            parsed_document = parse_file(source_path)
        except OSError:
            parsed_document = {}
        nodes = list((((parsed_document.get("document_ast") or {}).get("nodes")) or parsed_document.get("nodes") or []))
        if not nodes:
            failing_documents.append(
                {
                    **document,
                    "actual_content_top_level_names": [],
                    "missing_required_element_names": expected_element_names,
                    "unexpected_element_names": [],
                    "element_count_mismatches": [],
                    "expected_present_element_order": [],
                    "order_matches": False,
                    "content_structure_issue": "unparseable_or_empty_xml_tree",
                }
            )
            continue

        content_nodes = [
            dict(node)
            for node in nodes
            if str(node.get("local_tag") or "").strip() == "cn-content"
        ]
        if len(content_nodes) != 1:
            failing_documents.append(
                {
                    **document,
                    "actual_content_top_level_names": [],
                    "missing_required_element_names": expected_element_names,
                    "unexpected_element_names": [],
                    "element_count_mismatches": [],
                    "expected_present_element_order": [],
                    "order_matches": False,
                    "content_structure_issue": "cn_content_count_mismatch",
                    "actual_content_count": len(content_nodes),
                }
            )
            continue

        content_pointer = str(content_nodes[0].get("pointer") or "").strip()
        actual_element_names = [
            str(node.get("local_tag") or "").strip()
            for node in nodes
            if _parent_xml_pointer(str(node.get("pointer") or "").strip()) == content_pointer
            and str(node.get("local_tag") or "").strip()
        ]
        actual_element_counts: dict[str, int] = {}
        for name in actual_element_names:
            actual_element_counts[name] = actual_element_counts.get(name, 0) + 1

        missing_required_element_names: list[str] = []
        element_count_mismatches: list[dict[str, Any]] = []
        for element in authoritative_elements:
            element_name = str(element.get("name") or "").strip()
            min_occurs = int(str(element.get("min_occurs") or "1").strip() or "1")
            max_occurs_raw = str(element.get("max_occurs") or "1").strip() or "1"
            max_occurs = None if max_occurs_raw == "unbounded" else int(max_occurs_raw)
            actual_count = int(actual_element_counts.get(element_name, 0))
            if actual_count < min_occurs:
                missing_required_element_names.append(element_name)
            if actual_count < min_occurs or (max_occurs is not None and actual_count > max_occurs):
                element_count_mismatches.append(
                    {
                        "name": element_name,
                        "expected_min_occurs": min_occurs,
                        "expected_max_occurs": max_occurs_raw,
                        "actual_count": actual_count,
                    }
                )

        unexpected_element_names = sorted({name for name in actual_element_names if name not in expected_element_names})
        expected_present_element_order = [
            element_name
            for element_name in expected_element_names
            if int(actual_element_counts.get(element_name, 0)) > 0
        ]
        order_matches = actual_element_names == expected_present_element_order
        if (
            missing_required_element_names
            or unexpected_element_names
            or element_count_mismatches
            or not order_matches
        ):
            failing_documents.append(
                {
                    **document,
                    "actual_content_top_level_names": actual_element_names,
                    "missing_required_element_names": missing_required_element_names,
                    "unexpected_element_names": unexpected_element_names,
                    "element_count_mismatches": element_count_mismatches,
                    "expected_present_element_order": expected_present_element_order,
                    "order_matches": order_matches,
                    "content_structure_issue": (
                        "top_level_order_mismatch"
                        if not order_matches and not (missing_required_element_names or unexpected_element_names or element_count_mismatches)
                        else "top_level_structure_mismatch"
                    ),
                }
            )

    if failing_documents:
        return (
            "fail",
            "Detected cn-content top-level structures that do not align with the authoritative Attachment 1-1 content definition.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_CITATION,
                match_strength="invalid_cn_content_top_level_structure",
                matched_documents=[*failing_documents, *authoritative_documents],
                extra_details={
                    "expected_content_top_level_elements": authoritative_elements,
                    "violating_content_documents": failing_documents,
                },
            ),
        )

    return (
        "pass",
        f"Validated Attachment 1-1 cn-content top-level structure for {len(applicable_documents)} cn-regional.xml document(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_ATTACHMENT_11_CONTENT_REQUIREMENT_CITATION,
            match_strength="valid_cn_content_top_level_structure",
            matched_documents=[*applicable_documents, *authoritative_documents],
            extra_details={
                "expected_content_top_level_elements": authoritative_elements,
                "violating_content_documents": [],
            },
        ),
    )


def _evaluate_ectd_module1_leaf_parent_entry_kind_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_ID)
    authoritative_lookup, authoritative_documents = _build_authoritative_module1_entry_kind_lookup()
    if not authoritative_lookup:
        return (
            "na",
            "Attachment 1-4 authoritative module-1 entry-kind data was unavailable, so module-1 leaf-parent entry-kind checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=[],
                extra_details={
                    "authoritative_entry_kinds": {},
                    "checked_leaf_records": [],
                    "violating_leaf_records": [],
                },
            ),
        )

    documents = _collect_ectd_submission_metadata_documents(material_contract)
    applicable_documents: list[dict[str, Any]] = []
    for document in documents:
        filename = str(document.get("filename") or "").strip().lower()
        if filename != "cn-regional.xml":
            continue
        leaf_records = [
            dict(record)
            for record in (document.get("ectd_submission_metadata") or {}).get("ectd_leaf_records", []) or []
            if isinstance(record, dict)
        ]
        if not leaf_records:
            continue
        applicable_documents.append({**document, "ectd_leaf_records": leaf_records})

    if not applicable_documents:
        return (
            "na",
            "No cn-regional.xml leaf records were available, so module-1 leaf-parent entry-kind checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=authoritative_documents,
                extra_details={
                    "authoritative_entry_kinds": dict(sorted(authoritative_lookup.items())),
                    "checked_leaf_records": [],
                    "violating_leaf_records": [],
                },
            ),
        )

    checked_leaf_records: list[dict[str, Any]] = []
    violating_leaf_records: list[dict[str, Any]] = []
    failing_documents: list[dict[str, Any]] = []
    for document in applicable_documents:
        document_checked_records: list[dict[str, Any]] = []
        document_violations: list[dict[str, Any]] = []
        for record in document["ectd_leaf_records"]:
            parent_local_tag = str(record.get("parent_local_tag") or "").strip()
            href = str(record.get("href") or "").strip()
            if not parent_local_tag or not href:
                continue
            authoritative_entry_kind = authoritative_lookup.get(parent_local_tag)
            if not authoritative_entry_kind:
                continue
            checked_record = {
                "document_id": str(document.get("document_id") or "").strip(),
                "filename": str(document.get("filename") or "").strip(),
                "source_path": str(document.get("source_path") or "").strip(),
                "parent_local_tag": parent_local_tag,
                "href": href,
                "authoritative_entry_kind": authoritative_entry_kind,
            }
            document_checked_records.append(checked_record)
            checked_leaf_records.append(checked_record)
            if authoritative_entry_kind != "文件":
                document_violations.append(checked_record)
                violating_leaf_records.append(checked_record)
        if document_violations:
            failing_documents.append(
                {
                    **document,
                    "checked_leaf_records": document_checked_records,
                    "violating_leaf_records": document_violations,
                }
            )

    authoritative_entry_kinds = dict(sorted(authoritative_lookup.items()))
    matched_documents = [*applicable_documents, *authoritative_documents]
    if not checked_leaf_records:
        return (
            "na",
            "No cn-regional.xml leaf parent elements matched authoritative Attachment 1-4 entry-kind records, so module-1 leaf-parent entry-kind checks are not applicable.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_CITATION,
                match_strength="not_applicable",
                matched_documents=matched_documents,
                extra_details={
                    "authoritative_entry_kinds": authoritative_entry_kinds,
                    "checked_leaf_records": [],
                    "violating_leaf_records": [],
                },
            ),
        )

    if failing_documents:
        return (
            "fail",
            "Detected cn-regional.xml leaf nodes that are attached directly to Attachment 1-4 directory entries instead of file-bearing module-1 elements.",
            _build_requirement_details(
                requirement,
                fallback_requirement_id=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_ID,
                fallback_citation_anchor=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_CITATION,
                match_strength="invalid_module1_leaf_parent_entry_kind",
                matched_documents=[*failing_documents, *authoritative_documents],
                extra_details={
                    "authoritative_entry_kinds": authoritative_entry_kinds,
                    "checked_leaf_records": checked_leaf_records,
                    "violating_leaf_records": violating_leaf_records,
                },
            ),
        )

    return (
        "pass",
        f"Validated Attachment 1-4 leaf-parent entry-kind alignment for {len(checked_leaf_records)} comparable cn-regional.xml leaf record(s).",
        _build_requirement_details(
            requirement,
            fallback_requirement_id=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_ID,
            fallback_citation_anchor=_ECTD_ATTACHMENT_14_ENTRY_KIND_REQUIREMENT_CITATION,
            match_strength="valid_module1_leaf_parent_entry_kind",
            matched_documents=matched_documents,
            extra_details={
                "authoritative_entry_kinds": authoritative_entry_kinds,
                "checked_leaf_records": checked_leaf_records,
                "violating_leaf_records": [],
            },
        ),
    )


