def _evaluate_class3_reference_material_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_CLASS3_REFERENCE_REQUIREMENT_ID)
    class3_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_CLASS3_SIGNAL_PATTERN,
    )
    if not class3_documents:
        return (
            "na",
            "No deterministic Class 3 registration signals were found, so the reference-sample material requirement is not applicable.",
            {
                "requirement_id": _CLASS3_REFERENCE_REQUIREMENT_ID,
                "source_clause_id": str(requirement.get("source_clause_id") or "").strip(),
                "citation_anchor": str(requirement.get("citation_anchor") or _CLASS3_REFERENCE_REQUIREMENT_CITATION),
                "match_strength": "not_applicable",
                "matched_documents": [],
            },
        )

    reference_material_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_REFERENCE_SAMPLE_SIGNAL_PATTERN,
    )
    matched_documents: list[dict[str, Any]] = []
    seen_filenames: set[str] = set()
    for document in [*class3_documents, *reference_material_documents]:
        filename = str(document.get("filename") or "").strip()
        if not filename or filename in seen_filenames:
            continue
        matched_documents.append(document)
        seen_filenames.add(filename)

    details = {
        "requirement_id": _CLASS3_REFERENCE_REQUIREMENT_ID,
        "source_clause_id": str(requirement.get("source_clause_id") or "").strip(),
        "citation_anchor": str(requirement.get("citation_anchor") or _CLASS3_REFERENCE_REQUIREMENT_CITATION),
        "match_strength": (
            "explicit_reference_materials"
            if reference_material_documents
            else "class3_signal_without_reference_materials"
        ),
        "matched_documents": matched_documents,
    }

    class3_preview = ", ".join(
        str(item.get("filename") or "").strip()
        for item in class3_documents[:4]
        if str(item.get("filename") or "").strip()
    )
    if reference_material_documents:
        reference_preview = ", ".join(
            str(item.get("filename") or "").strip()
            for item in reference_material_documents[:4]
            if str(item.get("filename") or "").strip()
        )
        return (
            "pass",
            "已检测到 3 类参比一致性申报信号，且存在参比制剂材料信号："
            + reference_preview
            + ".",
            details,
        )

    return (
        "warn",
        "已检测到 3 类参比一致性申报信号（"
        + class3_preview
        + "），但未发现可确定识别的参比制剂材料信号。",
        details,
    )

