def _evaluate_class5_1_clinical_advantage_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_CLASS5_1_ADVANTAGE_REQUIREMENT_ID)
    class5_1_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_CLASS5_1_SIGNAL_PATTERN,
    )
    if not class5_1_documents:
        return (
            "na",
            "No deterministic 5.1 类 registration signals were found, so the clinical-advantage requirement is not applicable.",
            {
                "requirement_id": _CLASS5_1_ADVANTAGE_REQUIREMENT_ID,
                "source_clause_id": str(requirement.get("source_clause_id") or "").strip(),
                "citation_anchor": str(requirement.get("citation_anchor") or _CLASS5_1_ADVANTAGE_REQUIREMENT_CITATION),
                "match_strength": "not_applicable",
                "matched_documents": [],
            },
        )

    clinical_trial_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_CLINICAL_TRIAL_SIGNAL_PATTERN,
    )
    reference_material_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_REFERENCE_SAMPLE_SIGNAL_PATTERN,
    )
    clinical_advantage_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_CLINICAL_ADVANTAGE_SIGNAL_PATTERN,
    )

    matched_documents: list[dict[str, Any]] = []
    seen_filenames: set[str] = set()
    for document in [*class5_1_documents, *clinical_trial_documents, *reference_material_documents, *clinical_advantage_documents]:
        filename = str(document.get("filename") or "").strip()
        if not filename or filename in seen_filenames:
            continue
        matched_documents.append(document)
        seen_filenames.add(filename)

    details = {
        "requirement_id": _CLASS5_1_ADVANTAGE_REQUIREMENT_ID,
        "source_clause_id": str(requirement.get("source_clause_id") or "").strip(),
        "citation_anchor": str(requirement.get("citation_anchor") or _CLASS5_1_ADVANTAGE_REQUIREMENT_CITATION),
        "match_strength": (
            "explicit_clinical_advantage_evidence"
            if clinical_trial_documents and reference_material_documents and clinical_advantage_documents
            else "class5_1_signal_missing_clinical_advantage_evidence"
        ),
        "matched_documents": matched_documents,
    }

    if clinical_trial_documents and reference_material_documents and clinical_advantage_documents:
        return (
            "pass",
            "已检测到 5.1 类申报信号，且存在临床试验材料、参比制剂材料和明确临床优势信号。",
            details,
        )

    return (
        "warn",
        "已检测到 5.1 类申报信号，但临床优势支持证据仍不完整，需补充临床试验材料、参比制剂材料或明确临床优势说明。",
        details,
    )


def _evaluate_eclinical_database_requirement(
    material_contract: dict[str, Any],
) -> tuple[str, str, dict[str, Any]]:
    requirement = _load_requirement_record(_ECLINICAL_DATABASE_REQUIREMENT_ID)
    marketing_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_MARKETING_REGISTRATION_SIGNAL_PATTERN,
    )
    clinical_trial_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_CLINICAL_TRIAL_SIGNAL_PATTERN,
    )

    if not marketing_documents or not clinical_trial_documents:
        return (
            "na",
            "No deterministic marketing-registration plus clinical-trial signals were found, so the eClinical database requirement is not applicable.",
            {
                "requirement_id": _ECLINICAL_DATABASE_REQUIREMENT_ID,
                "source_clause_id": str(requirement.get("source_clause_id") or "").strip(),
                "citation_anchor": str(requirement.get("citation_anchor") or _ECLINICAL_DATABASE_REQUIREMENT_CITATION),
                "match_strength": "not_applicable",
                "matched_documents": [],
            },
        )

    database_documents = _collect_documents_by_pattern(
        material_contract,
        signal_pattern=_ECLINICAL_DATABASE_SIGNAL_PATTERN,
    )
    matched_documents: list[dict[str, Any]] = []
    seen_filenames: set[str] = set()
    for document in [*marketing_documents, *clinical_trial_documents, *database_documents]:
        filename = str(document.get("filename") or "").strip()
        if not filename or filename in seen_filenames:
            continue
        matched_documents.append(document)
        seen_filenames.add(filename)

    details = {
        "requirement_id": _ECLINICAL_DATABASE_REQUIREMENT_ID,
        "source_clause_id": str(requirement.get("source_clause_id") or "").strip(),
        "citation_anchor": str(requirement.get("citation_anchor") or _ECLINICAL_DATABASE_REQUIREMENT_CITATION),
        "match_strength": (
            "explicit_eclinical_database"
            if database_documents
            else "marketing_signal_without_eclinical_database"
        ),
        "matched_documents": matched_documents,
    }

    if database_documents:
        return (
            "pass",
            "已检测到上市注册与临床试验材料信号，且存在电子临床试验数据库信号。",
            details,
        )

    return (
        "warn",
        "已检测到上市注册与临床试验材料信号，但未发现可确定识别的电子临床试验数据库信号。",
        details,
    )


def _evaluate_law_clause_material_requirement(
    material_contract: dict[str, Any],
    *,
    citation_anchor: str,
    signal_pattern: re.Pattern[str],
    signal_label: str,
    expected_roles: list[str],
    missing_status: str,
    missing_match_strength: str,
) -> tuple[str, str, dict[str, Any]]:
    signal_documents = _collect_documents_by_pattern(material_contract, signal_pattern=signal_pattern)
    if not signal_documents:
        return (
            "na",
            f"No deterministic {signal_label} signals were found, so this regulation clause is not applicable.",
            _build_clause_requirement_details(
                citation_anchor=citation_anchor,
                match_strength="not_applicable",
                matched_documents=[],
            ),
        )

    role_documents_by_role = {
        role_name: _collect_documents_by_material_role(material_contract, role_name)
        for role_name in expected_roles
    }
    missing_roles = [role_name for role_name, documents in role_documents_by_role.items() if not documents]
    matched_documents: list[dict[str, Any]] = []
    seen_filenames: set[str] = set()
    for document in [*signal_documents, *[item for docs in role_documents_by_role.values() for item in docs]]:
        filename = str(document.get("filename") or "").strip()
        if not filename or filename in seen_filenames:
            continue
        matched_documents.append(document)
        seen_filenames.add(filename)

    if not missing_roles:
        return (
            "pass",
            f"已检测到 {signal_label}信号，且相关材料角色齐全：{', '.join(expected_roles)}。",
            _build_clause_requirement_details(
                citation_anchor=citation_anchor,
                match_strength="explicit_material_roles",
                matched_documents=matched_documents,
            ),
        )

    return (
        missing_status,
        f"已检测到 {signal_label}信号，但缺少材料角色：{', '.join(missing_roles)}。",
        _build_clause_requirement_details(
            citation_anchor=citation_anchor,
            match_strength=missing_match_strength,
            matched_documents=matched_documents,
        ),
    )


