def _evaluate_article6_data_traceability_support(material_contract: dict[str, Any]) -> tuple[str, str]:
    fact_index = list(material_contract.get("fact_index", []) or [])
    if not fact_index:
        return (
            "na",
            "当前未提取到可用于《药品管理法实施条例》第六条判断的原子事实与证据链，本规则暂不适用。",
        )

    provenance_rows = build_atomic_fact_provenance_rows(material_contract)
    alignment_rows = build_atomic_fact_signal_alignment_rows(material_contract)
    support_rows = build_atomic_fact_support_quality_rows(material_contract)
    intra_document_consistency_rows = build_intra_document_fact_signal_consistency_rows(material_contract)
    cross_document_rows = build_fact_consistency_rows(material_contract)

    missing_provenance = [row for row in provenance_rows if not row.get("has_unit_provenance")]
    misaligned_rows = [row for row in alignment_rows if not row.get("is_aligned")]
    context_only_rows = [row for row in support_rows if row.get("has_context_only_support")]
    intra_document_conflicts = [
        row
        for row in intra_document_consistency_rows
        if int(row.get("signal_count", 0) or 0) >= 2 and not row.get("is_consistent")
    ]
    cross_document_conflicts = [
        row
        for row in cross_document_rows
        if int(row.get("present_value_count", 0) or 0) >= 2 and not row.get("is_consistent")
    ]

    if not any(
        [
            missing_provenance,
            misaligned_rows,
            context_only_rows,
            intra_document_conflicts,
            cross_document_conflicts,
        ]
    ):
        return (
            "pass",
            "当前材料的已提取事实具备可追溯出处，且未发现明显的数据一致性或支撑质量问题，可作为《药品管理法实施条例》第六条的自动化支持性信号。",
        )

    issue_parts: list[str] = []
    if missing_provenance:
        issue_parts.append(f"缺少单元级出处 {len(missing_provenance)} 项")
    if misaligned_rows:
        issue_parts.append(f"事实信号不一致 {len(misaligned_rows)} 项")
    if context_only_rows:
        issue_parts.append(f"仅上下文支撑 {len(context_only_rows)} 项")
    if intra_document_conflicts:
        issue_parts.append(f"文内重复信号冲突 {len(intra_document_conflicts)} 项")
    if cross_document_conflicts:
        issue_parts.append(f"跨文档事实冲突 {len(cross_document_conflicts)} 项")

    return (
        "warn",
        "当前材料在《药品管理法实施条例》第六条要求的“记录和数据真实、准确、完整、可追溯”方面仍存在自动化风险信号："
        + "；".join(issue_parts)
        + "。建议结合原始证据链人工复核。",
    )


def _evaluate_cross_document_fact_consistency(material_contract: dict[str, Any]) -> tuple[str, str]:
    consistency_rows = build_fact_consistency_rows(material_contract)
    comparable_rows = [
        row
        for row in consistency_rows
        if int(row.get("present_value_count", 0) or 0) >= 2
    ]
    if not comparable_rows:
        return (
            "na",
            "Fewer than two document slots expose the same non-empty atomic facts, so cross-document consistency is not "
            "applicable.",
        )

    inconsistent_rows = [row for row in comparable_rows if not row.get("is_consistent")]
    if inconsistent_rows:
        fact_keys = [str(row.get("fact") or "").strip() for row in inconsistent_rows if str(row.get("fact") or "").strip()]
        preview = ", ".join(fact_keys[:5])
        if len(fact_keys) > 5:
            preview += f", +{len(fact_keys) - 5} more"
        return (
            "warn",
            "Cross-document atomic fact mismatches detected for "
            + preview
            + ". Review the consistency board for document-level evidence.",
        )

    return (
        "pass",
        f"Validated {len(comparable_rows)} comparable cross-document atomic fact(s) with no mismatches.",
    )


def _evaluate_non_text_evidence_projection(material_contract: dict[str, Any]) -> tuple[str, str]:
    coverage_rows = build_non_text_asset_coverage_rows(material_contract)
    if not coverage_rows:
        return (
            "na",
            "No table or image assets were detected, so non-text evidence projection checks are not applicable.",
        )

    gap_rows = [row for row in coverage_rows if not row.get("coverage_ready")]
    if gap_rows:
        gap_preview = ", ".join(
            f"{row['filename']}:{row['source_id']}"
            for row in gap_rows[:5]
        )
        if len(gap_rows) > 5:
            gap_preview += f", +{len(gap_rows) - 5} more"
        return (
            "warn",
            "Detected non-text assets without full review-ready projection into evidence/units: "
            + gap_preview
            + ".",
        )

    return (
        "pass",
        f"Validated review-ready projection for {len(coverage_rows)} detected table/image asset(s).",
    )


def _evaluate_section_anchor_coverage(material_contract: dict[str, Any]) -> tuple[str, str]:
    anchor_rows = build_section_anchor_rows(material_contract)
    applicable_rows = [
        row
        for row in anchor_rows
        if int(row.get("content_evidence_count", 0) or 0) > 0
        and int(row.get("content_unit_count", 0) or 0) > 0
    ]
    if not applicable_rows:
        return (
            "na",
            "No review-ready content evidence/units were available for section-anchor coverage checks.",
        )

    gap_rows = [row for row in applicable_rows if not row.get("anchor_ready")]
    if gap_rows:
        preview = ", ".join(
            f"{row['filename']}:{row.get('module_label') or 'unknown-module'}"
            for row in gap_rows[:5]
        )
        if len(gap_rows) > 5:
            preview += f", +{len(gap_rows) - 5} more"
        return (
            "warn",
            "Detected documents without sufficiently consumable section/module anchoring: "
            + preview
            + ".",
        )

    return (
        "pass",
        f"Validated consumable section/module anchoring for {len(applicable_rows)} document(s).",
    )


def _build_toc_alignment_audit_rows(
    alignment_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    audit_rows: list[dict[str, Any]] = []
    for row in alignment_rows:
        if int(row.get("toc_outline_count", 0) or 0) <= 0:
            continue
        audit_rows.append(
            {
                "document_id": str(row.get("document_id") or "").strip() or None,
                "filename": str(row.get("filename") or "").strip() or None,
                "toc_sequence_id": str(row.get("toc_sequence_id") or "").strip() or None,
                "toc_sequence_ids": list(row.get("toc_sequence_ids", []) or []),
                "toc_sequence_titles": list(row.get("toc_sequence_titles", []) or []),
                "toc_sequence_pages": list(row.get("toc_sequence_pages", []) or []),
                "toc_sequence_selection": str(row.get("toc_sequence_selection") or "").strip() or None,
                "toc_sequence_alignment_scores": list(row.get("toc_sequence_alignment_scores", []) or []),
                "excluded_toc_sequence_count": int(row.get("excluded_toc_sequence_count", 0) or 0),
                "excluded_toc_sequence_ids": list(row.get("excluded_toc_sequence_ids", []) or []),
                "toc_outline_count": int(row.get("toc_outline_count", 0) or 0),
                "toc_root_outline_count": int(row.get("toc_root_outline_count", 0) or 0),
                "matched_outline_count": int(row.get("matched_outline_count", 0) or 0),
                "matched_root_outline_count": int(row.get("matched_root_outline_count", 0) or 0),
                "root_outline_coverage_ratio": row.get("root_outline_coverage_ratio"),
                "root_page_order_ready": bool(row.get("root_page_order_ready", False)),
                "root_page_offset_values": list(row.get("root_page_offset_values", []) or []),
                "root_page_offset_ready": bool(row.get("root_page_offset_ready", False)),
                "projected_root_page_values": list(row.get("projected_root_page_values", []) or []),
                "root_page_alignment_rows": list(row.get("root_page_alignment_rows", []) or []),
                "toc_body_alignment_path_rows": list(row.get("toc_body_alignment_path_rows", []) or []),
                "root_page_span_ready": bool(row.get("root_page_span_ready", False)),
                "direct_child_coverage_ratio": row.get("direct_child_coverage_ratio"),
                "direct_child_coverage_ready": bool(row.get("direct_child_coverage_ready", False)),
                "bounded_subtree_coverage_ratio": row.get("bounded_subtree_coverage_ratio"),
                "bounded_subtree_coverage_ready": bool(row.get("bounded_subtree_coverage_ready", False)),
                "missing_body_root_outline_indices": list(row.get("missing_body_root_outline_indices", []) or []),
                "missing_body_direct_child_outline_indices": list(
                    row.get("missing_body_direct_child_outline_indices", []) or []
                ),
                "missing_body_direct_child_path_rows": list(
                    row.get("missing_body_direct_child_path_rows", []) or []
                ),
                "missing_body_bounded_subtree_outline_indices": list(
                    row.get("missing_body_bounded_subtree_outline_indices", []) or []
                ),
                "missing_body_bounded_subtree_path_rows": list(
                    row.get("missing_body_bounded_subtree_path_rows", []) or []
                ),
                "alignment_ready": bool(row.get("alignment_ready", False)),
            }
        )
    return audit_rows


def _evaluate_toc_body_alignment(material_contract: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
    alignment_rows = build_toc_body_alignment_rows(material_contract)
    audit_rows = _build_toc_alignment_audit_rows(alignment_rows)
    applicable_rows = [
        row
        for row in alignment_rows
        if int(row.get("toc_outline_count", 0) or 0) > 0
    ]
    if not applicable_rows:
        return (
            "na",
            "No TOC outline entries were available for TOC-to-body section alignment checks.",
            {"structure_audit_rows": audit_rows},
        )

    gap_rows = [row for row in applicable_rows if not row.get("alignment_ready")]
    if gap_rows:
        preview = ", ".join(
            f"{row['filename']}:{row['toc_outline_count']} TOC / {row['body_outline_count']} body / {row['matched_outline_count']} matched / {row['matched_root_outline_count']} root-matched / root-coverage={row.get('root_outline_coverage_ratio')} / root-page-order={row.get('root_page_order_ready')} / root-page-offset={row.get('root_page_offset_values')} / root-page-span={row.get('root_page_span_ready')} / direct-child-coverage={row.get('direct_child_coverage_ratio')} / subtree-coverage={row.get('bounded_subtree_coverage_ratio')}"
            for row in gap_rows[:5]
        )
        if len(gap_rows) > 5:
            preview += f", +{len(gap_rows) - 5} more"
        return (
            "warn",
            "Detected TOC-to-body outline alignment gaps: " + preview + ".",
            {"structure_audit_rows": audit_rows},
        )

    return (
        "pass",
        f"Validated TOC-to-body outline overlap for {len(applicable_rows)} document(s) with TOC structure.",
        {"structure_audit_rows": audit_rows},
    )


